(window.GIM_TS=window.GIM_TS||{})["Niddah.0"]={"from":0,"a":[["\u0003שמאי אומר: כל הנשים דיין שעתן,\u0004 כלומר, משעה שמבחינות שיצא מהן דם נידה, מאותה שעה בלבד הן נחשבות כטמאות, לטמא את התרומה ואת הטהרות. \u0003הלל אומר: מפקידה\u0004 (בדיקה) \u0003לפקידה,\u0004 כלומר, מזמן בדיקה אחד לזמן בדיקה שני, שאם האשה מגלה בבדיקה שראתה דם, חוששים שמא אותו דם יצא ממנה מיד לאחר הבדיקה הקודמת, ומאותה שעה היא מטמאה מספק את כל הטהרות שהתעסקה בהן, \u0003ואפילו לימים הרבה,\u0004 אם היה הבדל זמן גדול בין בדיקה אחת לחבירתה.","\u0003וחכמים אומרים: לא כדברי זה,\u0004 הלל המחמיר, \u0003ולא כדברי זה,\u0004 שמאי המקל, \u0003אלא מעת לעת\u0004 במשך עשרים וארבע שעות — \u0003ממעטת על יד\u0004 (מכוח, מדין) \u0003מפקידה לפקידה,\u0004 שאם הבדיקה הקודמת היתה יותר מעשרים וארבע שעות לפני הבדיקה הזאת, אינה חוששת אלא מעת לעת למפרע, ונמצא איפוא כי זמן מעת לעת ממעט את הזמן שבין פקידה לפקידה. \u0003ומפקידה לפקידה,\u0004 אם היו שתי הבדיקות רחוקות זו מזו פחות מעת לעת, וכגון שבדקה בבוקר ונמצא טהורה, ובדקה שוב בערב ומצאה טמאה — \u0003ממעטת על יד מעת לעת,\u0004 ואינה חוששת אלא מזמן הבדיקה הקודמת.","כל זה אמרו באשה שאין לה ווסת קבועה, ואולם \u0003כל אשה שיש לה וסת,\u0004 כלומר, זמן קבוע לראיית הדם, ובדקה בזמן זה ומצאה שהיא טמאה — \u0003דיה שעתה,\u0004 ורק מאותו זמן ואילך הוא מטמאה. \u0003והמשמשת\u0004 מיטתה \u0003בעדים\u0004 (בפיסות בד) שבודקת בהם — \u0003הרי זו כפקידה, ו\u0004אם מצאה דם על עדה, הריהי \u0003ממעטת על יד מעת לעת ועל יד מפקידה לפקידה,\u0004 שדבר זה נחשב כבדיקה לעצמה, ואינה צריכה בדיקה נוספת.","\u0003כיצד דיה שעתה?\u0004 — כגון ש\u0003היתה יושבת במטה ועסוקה בטהרות, ופרשה\u0004 מן הטהרות \u0003וראתה\u0004 דם — \u0003היא טמאה והן,\u0004 הטהרות, \u0003טהורות.\u0004","\u0003אף על פי שאמרו\u0004 שאשה שאין לה וסת \u0003מטמאה\u0004 למפרע \u0003מעת לעת,\u0004 במקרה כזה \u0003אינה מונה\u0004 ימי נדה \u0003אלא משעה שראתה.\u0004","שואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003שמאי\u0004 הסבור שאשה הרואה דם נידה אינה מטמאה למפרע? ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 שמאי שכיון שספק הוא אם ראתה קודם הרי כלל הוא: במקום שיש בו ספק העמד דבר על חזקתו, ואף כאן \u0003העמד אשה על חזקתה, ו\u0004הרי כל \u0003אשה\u0004 \u0003בחזקת טהורה\u0004 היא \u0003עומדת,\u0004 ולכן אין לומר שהיא מטמאה למפרע. \u0003ו\u0004אילו \u0003הלל\u0004 טוען כנגד זה: \u0003כי אמר\u0004 \u0005[כאשר אומרים]\u0006 כלל זה שבמקום ספק \u0003העמד דבר על חזקתו\u0004 — הרי זה דווקא \u0003היכא דלית ליה\u0004 \u0005[היכן,\u0006 במקרה, \u0005שאין לו\u0006 לדבר שנפל בו הספק\u0005]\u0006 כל \u0003ריעותא מגופיה\u0004 \u0005[פגם מגופו],\u0006 \u0003אבל איתתא\u0004 \u0005[אשה]\u0006 כיון שהיא רואה דם כרגיל,"],["\u0003כיון\u0004 ש\u0003מגופה\u0004 (מתוכה ומעצמה), שכן טבעה \u0003קחזיא\u0004 \u0005[שהיא רואה]\u0006 דם, ועומדת היא להיטמא — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 כי \u0003אוקמה\u0004 \u0005[העמד אותה]\u0006 על \u0003חזקתה,\u0004 ולכן אין לה חזקת טהרה.","ושואלים: הן לשיטת שמאי והן לשיטת הלל, \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 דין האשה הרואה דם נדה \u0003מ\u0004דינו של \u0003מקוה? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקוה ש\u0004נמדד והיו בו ארבעים סאה מים, כשיעור הראוי לטהר, וטבלו בו טמאים, ולאחר מכן \u0003נמדד\u0004 שוב \u0003ונמצא\u0004 שהוא \u0003חסר\u0004 מהשיעור — \u0003כל טהרות שנעשו\u0004 על ידי אדם או כלים שנטבלו במקוה זה \u0003על גביו\u0004 (על סמך) שהוא כשר, \u0003למפרע\u0004 (לשעבר, לאחור) עד לשעה שנמדד ונמצא שיש בו שיעור ראוי, \u0003בין\u0004 שהיה המקוה עומד \u0003ברשות הרבים, בין\u0004 שהיה עומד \u0003ברשות היחיד\u0004 — הרי הן \u0003טמאות.\u0004 אף שבכלל ספק טומאה ברשות הרבים טהור.","ומסבירים את השאלה: \u0003ל\u0004דעת \u0003שמאי קשיא\u0004 \u0005[קשה]\u0006 מה שאמרו שבמקוה מטמאים את הטהרות \u0003למפרע,\u0004 ואין מעמידים אותו על חזקתו שלא כדברי שמאי בנדה, שמעמידים אותה על חזקת טהרתה ואינה טמאה למפרע.","ואילו \u0003ל\u0004דעת \u0003הלל קשיא\u0004 \u0005[קשה]\u0006 מה שאמרו במקוה שכל הטהרות שנעשו באדם או בכלים שטבלו בו טמאות למפרע טומאת \u0003ודאי\u0004 (שאם היה זה רק מחמת הספק, היו הטהרות שנעשו ברשות הרבים טהורות, כדין ספק טומאה ברשות הרבים), ו\u0003אילו\u0004 אשה שמצאה דם, לשיטת הלל הריהי טמאה למפרע (משעת בדיקה אחרונה) רק מחמת הספק. שכן גם לשיטת חכמים שהיא טמאה כדי \u0003מעת לעת\u0004 למפרע \u0003שבנדה\u0004 ולא מפקידה לפקידה, (והוא הדין לדעת בית הלל) הרי זה רק מחמת הספק, ולכן לדעתם \u0003תולין\u0004 את הטהרות הללו בספק, שאם היו תרומה \u0003לא אוכלין\u0004 אותן, שמא נטמאו, \u0003ו\u0004גם \u0003לא שורפין\u0004 אותן כדין הטהרות שנטמאו ודאי, שמא עדיין טהורות הן. \u0003ואילו הכא\u0004 \u0005[כאן]\u0006 במקוה הרי זו \u0003טומאה ודאי,\u0004 ואף שורפים את הטהרות שנעשו בכלים שהוטבלו בו!","ומשיבים: \u0003התם\u0004 \u0005[שם\u0006 במקוה\u0005]\u0006 הטעם הוא \u0003משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 לגבי הדבר שהוטבל בו \u0003העמד טמא על חזקתו\u0004 שהוא טמא, \u0003ו\u0004כיון שספק הוא אם היתה זו טבילה ראויה, \u0003אימא\u0004 \u0005[אמור]\u0006 שהריהו בחזקתו וכאילו \u0003לא טבל,\u0004 ולכן טומאתו ודאית. ומקשים: \u0003אדרבה\u0004 \u0005[\u0006אמור \u0005להיפך],\u0006 \u0003העמד\u0004 את ה\u0003מקוה על חזקתו\u0004 שהיה שיעור ראוי והיה כשר, \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003לא חסר\u0004 המקוה משיעורו בזמן הטבילה! ומתרצים: \u0003הרי\u0004 הורעה חזקתו זו, שכן הריהו \u0003חסר לפניך!\u0004","ומקשים: אם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן,\u0006 באשה המוצאת דם\u0005]\u0006 הורעה חזקת טהרתה, ש\u0003הרי דם לפניך,\u0004 ותטמא למפרע טומאה ודאית, כדין המקוה! ומשיבים: שונה הוא דין האשה הרואה דם, שכן אנו אומרים בה: \u0003השתא\u0004 \u0005[עכשיו]\u0006 בשעה שבדקה לאחרונה, \u0003הוא דחזאי\u0004 \u0005[שראתה]\u0006 דם נדה. ומקשים: \u0003הכא נמי\u0004 \u0005[כאן,\u0006 במקוה שנמדד ונמצא חסר, \u0005גם כן]\u0006 נאמר: \u0003השתא\u0004 \u0005[עכשיו]\u0006 כשנמדד ונמצא חסר \u0003הוא\u0004 ש\u0003חסר!\u0004","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]\u0006 ביניהם? שכן \u0003התם\u0004 \u0005[שם,\u0006 במקוה\u0005]\u0006 \u0003איכא למימר\u0004 \u0005[יש\u0006 מקום \u0005לומר]\u0006 כי שיעור המים שבו \u0003חסר\u0004 (התמעט) ואתא \u0005[ובא],\u0006 \u0003חסר ואתא\u0004 \u0005[ובא],\u0006 שלא נחסר שיעור המים בבת אחת אלא לאורך זמן, אלא שלא הבחינו בכך עד שנמדד המקוה. והורעה אם כן חזקתו כבר קודם לכן. ואולם \u0003הכא\u0004 \u0005[כאן,\u0006 באשה\u0005]\u0006 שבדקה ומצאה דם, \u0003מי איכא למימר\u0004 \u0005[האם יש\u0006 מקום \u0005לומר]\u0006 כי \u0003חזאי ואתא, חזאי ואתא\u0004 \u0005[ראתה ובאה, ראתה ובאה]?\u0006 והלא ודאי שראייה זו באה בפעם אחת, ורק בשעת ראייתה הורעה חזקתה! ושואלים: \u0003ומאי קושיא\u0004 \u0005[ומה קושיה]\u0006 היא זו? \u0003דלמא הגס הגס חזיתיה\u0004 \u0005[שמא\u0006 אמור גם באשה כי \u0005מעט מעט ראתהו\u0006 לדם\u0005]\u0006 ולא בבת אחת, ומה שונה דינה אם כן ממקוה?","ומשיבים: יש לחלק באופן אחר בין המקוה לנדה, שכן \u0003התם איכא תרתי לריעותא\u0004 \u0005[שם\u0006 במקוה שנמצא חסר \u0005יש שני\u0006 דברים \u0005להרע],\u0006 שהרי יש להעמיד את הטמאים שטבלו במקוה זה על חזקת טומאתם, וגם שהמקוה חסר לפנינו. ואילו \u0003הכא איכא חדא לריעותא\u0004 \u0005[כאן\u0006 באשה שראתה דם \u0005יש\u0006 רק דבר \u0005אחד להרע],\u0006 שנפגמה חזקתה שהרי דם לפניך, ואין בכך לטמא טהרות שנגעה בהן קודם, שהרי חזקת טהרתן לא נפגמה.","ושואלים: לשיטת שמאי שאין האשה הרואה דם טמאה למפרע, \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 דינה \u0003מ\u0004דין ה\u0003חבית? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 היתה לו חבית יין טבל, ו\u0003היה\u0004 בעל החבית \u0003בודק את\u0004 היין הנמצא בתוך \u0003החבית\u0004 לדעת אם לא החמיץ, כדי שיוכל \u0003להיות מפריש עליה,\u0004 על חשבון חבית זו, \u0003תרומה והולך,\u0004 על חביות אחרות של יין טבל. \u0003ואחר כך נמצא\u0004 אותו משקה שבחבית \u0003חומץ,\u0004 ואין מפרישים תרומה מן החומץ על היין. ואולם מאחר שאיננו יודעים מתי החמיצה, אומרים כי \u0003כל\u0004 \u0003שלשה ימים\u0004 שלאחר הבדיקה האחרונה שבה נמצא יין — \u0003ודאי\u0004 הוא שעדיין לא החמיץ, ולכן התרומה שהופרשה מחבית זו באותם ימים הריהי תרומה בודאי, והיין שעליו הופרשה תרומה זו מותר בודאי.","ואולם כל שהופרש מחבית זו \u0003מכאן ואילך,\u0004 לאחר שלושה ימים מזמן הבדיקה האחרונה של החבית — הריהו \u0003ספק\u0004 תרומה. הרי מוכח איפוא מן המשנה שהפגם שנמצא עתה בחבית מערער את חזקת הדבר ואוסרו למפרע, ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003ל\u0004דעת \u0003שמאי\u0004 מדוע אין אומרים כן גם באשה שראתה דם, שתטמא למפרע!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בחבית אנו פוסקים כך, \u0003משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]:\u0006 \u0003העמד טבל על חזקתו, ו\u0004כיון שרק ספק אם נתקן, \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003לא נתקן\u0004 עדיין. ואולם אשה שראתה דם, כיון שעד כה היתה בחזקת טהרה, לכן דיה שעתה. ושואלים על כך: \u0003אדרבה\u0004 \u0005[\u0006אמור \u0005להיפך],\u0006 בחבית יין שנבדקה ונמצאה חומץ יש לומר: \u0003העמד יין על חזקתו, ואימר\u0004 \u0005[ואמור]\u0006 ש\u0003לא החמיץ\u0004 עד שלא נמצא חומץ!","ודוחים: אינך יכול לומר כן, ש\u0003הרי החמיץ לפניך,\u0004 ואינך יכול להעמיד אותו על חזקתו! ושואלים: \u0003הכא נמי\u0004 \u0005[כאן,\u0006 באשה שראתה דם, \u0005גם כן]\u0006 אינך יכול להעמידה על חזקת טהרתה, ש\u0003הרי דם לפניך!\u0004 ומשיבים: באשה יש מקום לומר כי רק \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוא דחזאי\u0004 \u0005[שראתה]\u0006 את הדם, ולא קודם לכן. ושואלים: אם כן \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 אמור כי רק \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוא\u0004 ש\u0003החמיץ!\u0004","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?\u0006 \u0003התם איכא למימר\u0004 \u0005[שם יש\u0006 מקום \u0005לומר]\u0006 כי \u0003החמיץ ואתא\u0004 \u0005[ובא],\u0006 \u0003החמיץ ואתא\u0004 \u0005[ובא].\u0006 כלומר, מעט מעט החמיץ, שלא החמיץ היין בבת אחת אלא לאורך זמן, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 באשה הרואה דם \u0003מי איכא למימר\u0004 \u0005[האם יש\u0006 מקום \u0005לומר]:\u0006 \u0003חזאי ואתא, חזאי ואתא\u0004 \u0005[ראתה ובאה, ראתה ובאה]?\u0006 ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה קושיה]\u0006 היא זו? \u0003דלמא הגס הגס חזיתיה\u0004 \u0005[שמא\u0006 אכן \u0005מעט מעט ראתה אותו]!\u0006","ומתרצים: \u0003התם איכא תרתי לריעותא\u0004 \u0005[שם,\u0006 בחבית, \u0005יש שני\u0006 דברים \u0005להרע],\u0006 שהרי היין שבחביות האחרות בחזקת טבל, ומה שבחבית זו נמצא חומץ, ואילו \u0003הכא איכא חדא לריעותא\u0004 \u0005[כאן,\u0006 באשה, \u0005יש\u0006 דבר \u0005אחד להרע],\u0006 שנפגמה חזקתה בכך, שהרי דם לפניך, ואין בכך לטמא טהרות שנגעה בהן קודם שהרי חזקת טהרתן לא נפגמה.","\u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדין \u0003חבית\u0004 על דין \u0003מקוה: מאי שנא הכא\u0004 \u0005[מה שונה כאן,\u0006 במקוה\u0005],\u0006 שאנו מניחים שהכל ב\u0003ודאי\u0004 טמא, \u0003ומאי שנא הכא\u0004 \u0005[ומה שונה כאן,\u0006 בחבית\u0005]\u0006 שהוא טמא רק מ\u0003ספק?\u0004","\u0003אמר ר'\u0004 \u0003חנינא מסורא: מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ששנה הלכה זו ב\u0003חבית?\u0004 — \u0003ר' שמעון היא, דלגבי\u0004 \u0005[שאצל]\u0006 \u0003מקוה נמי ספקא משוי ליה\u0004 \u0005[גם כן ספק\u0006 הוא \u0005מחשיב אותו]\u0006 ולא כוודאי.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקוה ש\u0004היו בו ארבעים סאה מים כדין ולאחר זמן \u0003נמדד ונמצא חסר\u0004 משיעורו — \u0003כל הטהרות שנעשו על גביו למפרע, בין ברשות הרבים בין ברשות היחיד טמאות\u0004 בודאי.","\u0003ר' שמעון אומר:\u0004 טומאתן רק מספק היא, ולכן \u0003ברשות הרבים\u0004 — \u0003טהורות\u0004 הן, כדין כל ספק טומאה ברשות הרבים, ואילו \u0003ברשות היחיד,\u0004 אף שבכלל כל ספק טומאה בו טמא, במקרה זה רק \u0003תולין\u0004 את התרומה, שאין שורפים ואין אוכלים אותה."],["\u0003ו\u0004מסבירים את שיטותיהם: \u0003שניהם,\u0004 הן חכמים והן ר' שמעון, \u0003לא למדוה\u0004 לשיטותיהם \u0003אלא מ\u0004דין \u0003סוטה.\u0004 כיצד?","— \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי דינו של המקוה שנמדד ונמצא חסר, הריהו \u0003כי\u0004 \u0005[כמו]\u0006 דינה של ה\u0003סוטה, מה סוטה ספק היא\u0004 אם נטמאה אם לאו, שהרי לא ראו שנבעלה לזה שהתייחדה אתו, \u0003ו\u0004אף על פי כן \u0003עשאוה\u0004 (קבעו דינה) בתורה \u0003כודאי,\u0004 שאסורה לבעלה עד שיתברר באמצעות מי הסוטה שהיא טהורה, \u0003הכא נמי\u0004 \u0005[כאן,\u0006 במקוה שנמצא חסר, \u0005גם כן]\u0006 הרי \u0003ספק\u0004 אם היה בו כשיעור הראוי בשעה שהטבילו את הכלים הטמאים ונטהרו, \u0003ו\u0004אף על פי כן \u0003עשאוה\u0004 את התרומה שנגעה בכלים הללו \u0003כודאי\u0004 טמאה, ויוצאת לשריפה.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 אכן \u0003מסוטה\u0004 למדים חכמים את דינם, \u0003אימא\u0004 \u0005[אמור]\u0006 שיהא דין המקוה החסר \u0003כי\u0004 \u0005[כמו]\u0006 דין ה\u0003סוטה\u0004 במדוייק: \u0003מה סוטה,\u0004 אם ספק טומאתה היה \u0003ברשות הרבים,\u0004 ספק זה נידון כ\u0003טהור, הכא נמי\u0004 \u0005[כאן\u0006 לענין הספק במקוה שנחסר נאמר \u0005גם כן]\u0006 שאם הוא עומד \u0003ברשות הרבים\u0004 יהא הטובל בו \u0003טהור!\u0004","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם,\u0006 בסוטה\u0005]\u0006 \u0003משום סתירה הוא\u0004 שהיא נאסרת, \u0003וסתירה ברשות הרבים ליכא\u0004 \u0005[אין]\u0006 במציאות, ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 במקוה שנחסר\u0005]\u0006 הרי הספק \u0003משום\u0004 פסול \u0003חסר הוא,\u0004 ומעתה, \u0003מה לי\u0004 אם המקוה ה\u0003חסר\u0004 הוא \u0003ברשות הרבים, מה לי\u0004 אם המקוה ה\u0003חסר\u0004 הוא \u0003ברשות היחיד,\u0004 בכל אופן יהא פסול!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין לומר כך, שכן \u0003הא\u0004 \u0005[הרי]\u0006 כלל נקוט בידינו ש\u0003כל ספק טומאה ברשות הרבים\u0004 — \u0003טהור,\u0004 יש לומר כי סבורים חכמים שיש להחמיר במקוה שנחסר, \u0003כיון\u0004 \u0003דאיכא\u0004 \u0005[שיש]\u0006 בו \u0003תרתי לריעותא\u0004 \u0005[שני\u0006 דברים \u0005להרע],\u0006 שנחסר המקוה, ושלכלים שהטבילו בו יש חזקת טומאה, ולכן \u0003כודאי טומאה דמי\u0004 \u0005[נחשב]\u0006 הדבר. זהו הסבר שיטת חכמים.","\u0003ו\u0004אף \u0003ר' שמעון סבר\u0004 שדין המקוה שנמצא חסר הוא \u0003כי\u0004 \u0005[כמו]\u0006 דין ה\u0003סוטה, מה סוטה\u0004 אם נסתרה \u0003ברשות הרבים\u0004 — \u0003טהור, הכא נמי\u0004 \u0005[כאן\u0006 במקוה \u0005גם כן]\u0006 אם \u0003ברשות הרבים\u0004 — \u0003טהור.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 אכן ר' שמעון למד את שיטתו \u0003מסוטה, אימא\u0004 \u0005[אמור]\u0006 מעתה שיהיה דין המקוה שנמצא חסר לגמרי \u0003כי\u0004 \u0005[כמו]\u0006 דין ה\u0003סוטה: מה סוטה\u0004 אם נסתרה \u0003ברשות היחיד\u0004 — \u0003טמאה ודאי\u0004 שאסורה לבעלה עד שיתברר על ידי מי הסוטה שהיא טהורה, \u0003הכא נמי\u0004 \u0005[כאן,\u0006 במקוה, \u0005גם כן]\u0006 — כאשר נמצא \u0003ברשות היחיד\u0004 צריכה להיות התרומה \u0003טמאה\u0004 \u0003ודאי,\u0004 ומדוע לדעת ר' שמעון ברשות היחיד רק תולים?","ומשיבים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]\u0006 את הסוטה למקוה לענין רשות היחיד, שכן \u0003התם\u0004 \u0005[שם,\u0006 בסוטה\u0005]\u0006 הנסתרת ברשות היחיד, \u0003יש רגלים לדבר\u0004 לאסור אותה, \u0003שהרי קינא לה\u0004 בעלה מאדם זה, והלכה \u0003ונסתרה\u0004 עמו, ולכן היא נטמאת ודאי, ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 במקוה\u0005]\u0006 \u0003מאי\u0004 \u0005[מה,\u0006 אלו\u0005]\u0006 \u0003רגלים לדבר איכא\u0004 \u0005[יש]\u0006 בכך שנמצא חסר ברשות היחיד, שהרי אין לנו כל ראיה ממצבו עתה, ולכן אין מטמאים את הכלים שהוטבלו בו אלא מספק.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר, \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' שמעון: גמר\u0004 \u0005[למד]\u0006 \u0003סוף טומאה מתחלת טומאה\u0004 (עצם קבלת הטומאה),","\u0003מה תחלת טומאה,\u0004 אם \u0003ספק נגע\u0004 הדבר הטהור בדבר המטמאו, \u0003ספק לא נגע\u0004 — \u0003ברשות הרבים\u0004 הוא \u0003טהור\u0004 לכל הדעות, \u0003אף סוף טומאה,\u0004 אם \u0003ספק טבל,\u0004 כלומר, ספק עלתה לו טבילה, שטבל במקוה ראוי, \u0003ספק לא טבל\u0004 — \u0003ברשות הרבים\u0004 הריהו \u0003טהור.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? — \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003גברא\u0004 \u0005[האיש]\u0006 שספק נגע, הרי \u0003בחזקת טהרה\u0004 הוא \u0003קאי\u0004 \u0005[עומד],\u0006 ולכן \u0003מספקא לא מחתינן ליה\u0004 \u0005[מספק אין אנו מורידים אותו]\u0006 \u0003לטומאה.\u0004 ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003גברא\u0004 \u0005[האיש]\u0006 שספק אם עלתה לו טבילה, הלא \u0003בחזקת טומאה\u0004 הוא \u0003קאי\u0004 \u0005[עומד],\u0006 עד שיתברר שנטהר, ומכיון שלא ניתן לברר מאימתי נחסר המקוה, \u0003מספקא לא מפקינן ליה\u0004 \u0005[מספק אין אנו מוציאים אותו]\u0006 \u0003מטומאתו.\u0004","ועתה חוזרים למשנתנו, ושואלים: \u0003ו\u0004לדעת שמאי, שאין מטמאים את האשה למפרע אלא דיה שעתה, \u0003מאי שנא\u0004 \u0005[\u0006\u0005במה שונה,\u0006 מיוחד\u0005]\u0006 דין זה \u0003ממבוי? דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]:\u0006 \u0003השרץ\u0004 המת \u0003שנמצא במבוי\u0004 — \u0003מטמא למפרע\u0004 כל מה שיכול היה לנגוע בו במבוי זה, \u0003עד\u0004 הזמן \u0003שיאמר\u0004 עליו אדם: \u0003\"בדקתי\u0004 באותו זמן \u0003את המבוי הזה, ולא היה בו שרץ\", א\u0004 \u0003ו עד שעת הכיבוד\u0004 (שעת הניקוי), שמטאטאים את המבוי! הרי שהכל אוסרים למפרע?!","ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן],\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 במבוי \u0003שרצים דגופיה\u0004 \u0005[שממנו עצמו],\u0006 \u0003ושרצים דאתו מעלמא\u0004 \u0005[שבאו מבחוץ]\u0006 \u0003כתרתי לריעותא דמי\u0004 \u0005[כשני\u0006 דברים \u0005להרע\u0006 הם \u0005נחשבים],\u0006 ובכגון זה אפילו שמאי מודה שהריהי מטמאה למפרע. עד כאן סברה אחת.","ועוד בהסבר שיטת שמאי. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003שמאי\u0004 שאינו מטמאה למפרע: \u0003הואיל ו\u0004כרגיל \u0003אשה מרגשת בעצמה\u0004 שהדם יוצא ממנה, ומאחר שלא הרגישה, ודאי לא ראתה דם עד לשעה שמצאתו בבדיקה. \u0003והלל,\u0004 מה טעמו? — לדעתו האשה באמת הרגישה, אלא \u0003כסבורה\u0004 ש\u0003הרגשת מי רגלים היא\u0004 שיוצאים ממנה, ולא חשבה שדם הוא.","ושואלים: \u0003ולשמאי, האיכא\u0004 \u0005[הרי יש]\u0006 אופן שיוצא ממנה הדם כשהיא \u0003ישנה\u0004 ואינה מרגישה! ומשיבים: \u0003ישנה נמי\u0004 \u0005[גם כן],\u0006 \u0003אגב\u0004 (מתוך) \u0003צערה\u0004 שיוצא ממנה הריהי \u0003מיתערא\u0004 \u0005[מתעוררת],\u0006 \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 \u0003הרגשת מי רגלים\u0004 שהאשה מתעוררת כשמרגישה בכך.","ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003שוטה\u0004 שאף שהיא מרגישה, אינה מבינה שזו ראיית דם! ומשיבים: \u0003מודה שמאי בשוטה\u0004 שהיא אכן מטמאה למפרע. ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"כל הנשים\u0004 דיין שעתן\" \u0003קתני\u0004 \u0005[שנה]\u0006 ובכלל זה שוטה! ומשיבים: \u0003\"כל הנשים\"\u0004 שאמר, כוונתו לנשים ה\u0003פקחות.\u0004","ושואלים: אם כן מדוע אמר בלשון \"כל הנשים\", \u0003וליתני\u0004 \u0005[ושישנה]\u0006 רק \u0003\"נשים\"\u0004 ונבין שיש יוצאים מן הכלל! ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' אליעזר,\u0004 ש\u0003אמר ר'\u0004 \u0003אליעזר\u0004 (להלן ז,א): \u0003\"ארבע נשים\u0004 דיין שעתן\", ומשמע מדבריו: \u0003ותו\u0004 \u0005[ועוד]\u0006 \u0003לא,\u0004 שרק בהן אין לחשוש לטומאה למפרע, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שכך הדין ב\u0003כל הנשים\u0004 (הפיקחות).","ואומרים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 את דין \u0003כתמים\u0004 של דם. שכאשר האשה מוצאת כתם דם בבגדה, הריהי טמאה למפרע עד לשעה שנתכבס הבגד, או נבדק ולא נמצא בו כתם, ואין אומרים הואיל ולא הרגישה, לא ממנה בא הדם. ואם כן, \u0003לימא תנן\u0004 \u0005[האם נאמר\u0006 שכל מקום ש\u0005שנינו\u0006 במשנתנו\u0005]\u0006 לענין טומאת \u0003כתמים\u0004 הרי זה ש\u0003לא כ\u0004שיטת \u0003שמאי! אמר אביי: מודה שמאי בכתמים\u0004 שהם מטמאים למפרע, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? שהרי אם \u0003ב\u0004שחיטת \u0003צפור לא נתעסקה,\u0004 ו\u0003בשוק של טבחים\u0004 שניתז בו דם \u0003לא עברה,\u0004 אם כן \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003דם\u0004 שנמצא בכתם \u0003מהיכא אתי\u0004 \u0005[מהיכן בא]?\u0006 וודאי ממנה בא, אף שלא הרגישה ביציאתו!","ועוד בהסבר שיטת שמאי. \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כי \u0003היינו טעמיה\u0004 \u0005[זהו טעמו]\u0006 של \u0003שמאי\u0004 שאינה מטמאה למפרע, ש\u0003אם איתא דהוה\u0004 \u0005[יש\u0006 מקום לומר \u0005שהיה]\u0006 \u0003דם\u0004 מתחילה, כלומר, שיצא ממנה קודם הבדיקה — \u0003מעיקרא הוה אתי\u0004 \u0005[מתחילה היה בא,\u0006 נראה\u0005],\u0006 ומאחר שלא יצא אלא עתה, משמע שלא יצא קודם לכן. \u0003והלל,\u0004 מה טעמו? — לדעתו \u0003כותלי בית הרחם העמידוהו,\u0004 ולכן לא יצא הדם, אבל כבר נטמאה קודם לכן. \u0003ושמאי,\u0004 מה הוא סבור? — ש\u0003כותלי בית הרחם לא מוקמי\u0004 \u0005[אינם מעמידים]\u0006 את ה\u0003דם\u0004 אלא מזמן שנעקר מגופה הריהו יוצא החוצה מיד.","ושואלים: אשה ש\u0003משמשת במוך\u0004 הנתון בתוך הנרתיק שלה למניעת הריון, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי בכגון זה אין הדם יכול לצאת! \u0003אמר אביי: מודה שמאי במשמשת במוך\u0004 שמטמאה למפרע.","\u0003רבא אמר:\u0004 אין צורך לומר כך, כי \u0003מוך נמי\u0004 \u0005[גם כן],\u0006 \u0003אגב זיעה\u0004 שהיא מזיעה, הוא \u0003מכויץ כויץ\u0004 \u0005[מתכווץ],\u0006 ולכן יש מקום לדם לצאת. \u0003ומודה רבא במוך דחוק,\u0004 שאם היה המוך דחוק, בוודאי אין הדם יכול לצאת.","ושואלים: \u0003ומאי איכא\u0004 \u0005[ומה,\u0006 איזה הבדל \u0005יש]\u0006 \u0003בין הני לישני\u0004 \u0005[הלשונות הללו]\u0006 שלמדנו בהסבר שיטת שמאי (\"אשה מרגשת\", \"מעיקרא הוה אתי\") \u0003להאיך לישנא\u0004 \u0005[לאותו לשון]\u0006 שאמרנו \"העמד אשה על חזקתה\"?"],["ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לענין \u0003למרמי\u0004 \u0005[להקשות]\u0006 על שיטת שמאי מדינה של ה\u0003חבית ו\u0004מדינו של ה\u0003מקוה ו\u0004מדינו של ה\u0003מבוי,\u0004 שבכל אלה חוששים למפרע. ומפרטים: \u0003להאיך לישנא\u0004 \u0005[לאותה לשון]\u0006 שהוא משום שמעמידים את האשה על חזקתה — \u0003איכא למרמינהו\u0004 \u0005[יש\u0006 מקום \u0005להטיל אותם,\u0006 להראות סתירה מתוכם\u0005]\u0006 לדין האשה. ואולם \u0003להני לישני\u0004 \u0005[ללשונות הללו],\u0006 לשני ההסברים האחרונים, שאשה מרגשת ביציאת דם וכן שאין כותלי בית הרחם מחזיקים את הדם, הרי אלו טעמים מיוחדים הקיימים רק באשה, ולכן \u0003ליכא למרמי\u0004 \u0005[אין\u0006 מקום \u0005להטיל,\u0006 להראות סתירה\u0005]\u0006 מדינם של החבית, המקוה והמבוי.","ומבררים עוד: \u0003ומאי איכא\u0004 \u0005[ומה,\u0006 ואיזה הבדל \u0005יש]\u0006 \u0003בין האי לישנא\u0004 \u0005[הלשון הזו]\u0006 בהסבר שיטת שמאי, שאם היה זה דם, היה יוצא מיד, \u0003להאיך לישנא\u0004 \u0005[ללשון הזו]\u0006 בהסבר שיטתו, שאשה מרגשת ביציאת הדם? ומשיבים: \u0003ל\u0004דעת אביי הסבור שמודה שמאי במשמשת במוך שטמאה למפרע, \u0003איכא\u0004 \u0005[יש\u0006 הבדל\u0005]\u0006 בין שיטות ההסבר הללו לענין המשמשת ב\u0003מוך,\u0004 שלפי ההסבר שאשה מרגשת — אף אשה זו מרגשת ביציאת דם, וכיון שלא הרגישה ודאי לא ראתה מקודם. ואילו לפי ההסבר שאין הדם משתהה מלצאת במשמשת במוך, אפשר שהמוך עצר בעד הדם מלצאת, ויתכן שראתה קודם לכן.","ואף \u0003ל\u0004דעתו של \u0003רבא\u0004 הסבור שגם בשימוש במוך יכול הדם לצאת, \u0003איכא\u0004 \u0005[יש\u0006 הבדל\u0005]\u0006 בין שתי שיטות ההסבר הללו בדעת שמאי, בענין האשה המשמשת ב\u0003מוך דחוק\u0004 (הדוק ביותר), שאין הדם עובר בעדו.","ומעירים: \u0003תניא כי האי לישנא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כמו לשון זו],\u0006 ש\u0003אם איתא דהוה\u0004 \u0005[אמנם שהיה]\u0006 \u0003דם, מעיקרא הוה אתי\u0004 \u0005[מתחילה היה בא],\u0006 שכך שנינו, \u0003אמר לו הלל לשמאי: אי\u0004 (אין) \u0003אתה מודה\u0004 \u0003ב\u0004מקרה זה של \u0003קופה\u0004 (סל) \u0003שנשתמשו\u0004 \u0003בה\u0004 ב\u0003טהרות בזוית זו\u0004 של הקופה, \u0003ו\u0004לאחר מכן \u0003נמצא שרץ בזוית אחרת\u0004 שלה — \u0003ש\u0004ה\u0003טהרות הראשונות\u0004 שהיו בצד זה של הקופה \u0003טמאות?\u0004 ואף שנמצא בה השרץ לאחר שכבר הוצאו ממנה הטהרות הללו — טמאות הן, מחשש שמא היה השרץ מצוי בקופה בזמן שהן היו בה, ונטמאו בו. ואין אנו מעמידים את הטהרות על חזקת טהרתן לומר שהשרץ נפל לקופה רק לאחר שהוצאו ממנה. אם כן אף באשה הרואה דם, יש לטמאה למפרע מפני החשש שיצא הדם קודם לראייתה! \u0003אמר לו\u0004 שמאי להלל בתשובה: \u0003אבל\u0004 (נכון) שכך הוא הדין בקופה, ואולם שונה דין הקופה מדין האשה.","\u0003ומה הפרש\u0004 (הבדל) יש \u0003בין זו לזו? לזו\u0004 לקופה — \u0003יש לה שולים\u0004 (בסיס מתחתיה שיושבת עליו), ויש לחשוש שמא היה מונח שם השרץ בשעה שהיו הטהרות בתוכה, אלא שלא ראוהו. ואילו \u0003לזו\u0004 לאשה — \u0003אין לה שולים,\u0004 שאין מקום בגופה בו מונח הדם ואינו יוצא החוצה, ומכיון שלא יצא אין לחשוש שהיה בה דם מקודם. הרי איפוא משמע מברייתא זו שזהו הסבר שיטתו של שמאי.","\u0003רבא אמר: טעמא\u0004 \u0005[הטעם]\u0006 של \u0003שמאי\u0004 שהרואה דם דייה שעתה הוא \u0003משום בטול\u0004 מצוות \u0003פריה ורביה.\u0004 שכן אם תטמא טהרות למפרע, יירתעו אנשים מלשמש עם נשיהם מחשש שמא כבר יצא דם, אלא שעדיין לא נראה. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא מפורשת \u0005גם כן כך,\u0006 כהסברו זה של רבא\u0005],\u0006 \u0003אמר לו שמאי להלל: אם כן,\u0004 כשיטתך שיש לטמא את הרואה דם למפרע, \u0003בטלת בנות ישראל מ\u0004קיום מצוות \u0003פריה ורביה.\u0004","ושואלים מעתה: \u0003ומאן דתני האי לישנא\u0004 \u0005[ומי ששונה לשון זו,\u0006 הסבר זה\u0005]\u0006 שטעמו של שמאי הוא משום ביטול פריה ורביה, רבא, ו\u0003הא תניא כי האיך לישנא\u0004 \u0005[הרי שנויה\u0006 הברייתא המובאת קודם, ממנה נלמד \u0005כמו לשון זו,\u0006 האחרת\u0005]\u0006 שהטעם הוא משום ש\u0003אם איתא דהוה\u0004 \u0005[אמנם שהיה]\u0006 \u0003דם, מעיקרא הוה אתי\u0004 \u0005[מתחילה היה בא]!\u0006 ומשיבים: \u0003התם\u0004 \u0005[שם,\u0006 בברייתא ההיא\u0005]\u0006 \u0003הלל הוא דקטעי\u0004 \u0005[שטעה]\u0006 בהבנת שיטת שמאי. ש\u0003הוא סבר\u0004 כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003שמאי\u0004 הוא משום ש\u0003אם איתא דהוה\u0004 \u0005[אמנם שהיה]\u0006 \u0003דם, מעיקרא הוה אתי\u0004 \u0005[מתחילה היה בא],\u0006 \u0003ו\u0004משום כך \u0003קא מקשי ליה\u0004 \u0005[הוא מקשה לו]\u0006 מדין הטהרות ב\u0003קופה.\u0004","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003שמאי\u0004 בתשובה: אין הדבר קשה לשיטתי, שכן \u0003טעמא דידי\u0004 \u0005[הטעם שלי]\u0006 הוא אחר, \u0003משום בטול פריה ורביה.\u0004 \u0003ו\u0004אולם אף \u0003למאי דקטעית נמי דקמקשית\u0004 \u0005[למה שטעית\u0006 בהבנת שיטתי, גם כן, שאתה מקשה] מדין ה\u0003קופה\u0004 — גם לכך יש תשובה, שכן יש להבחין בין קופה לאשה, שהרי \u0003לזו יש לה שולים, ולזו אין לה שולים.\u0004","ושואלים לצד ההפוך: \u0003ולמאן דתני האי לישנא\u0004 \u0005[ולמי ששונה לשון זו],\u0006 שטעמו של שמאי הוא משום שאם היה דם, היה הוא צריך לצאת קודם, \u0003הא תניא כי האיך לישנא\u0004 \u0005[הרי שנויה\u0006 ברייתא \u0005כמו הלשון האחרת]\u0006 שטעמו של שמאי הוא \u0003משום בטול פריה ורביה!\u0004","ומשיבים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 \u0003הלל לשמאי\u0004 בברייתא זו: \u0003אין\u0004 \u0005[\u0006אמנם \u0005כן],\u0006 \u0003טעמא קאמרת\u0004 \u0005[טעם\u0006 שיש בו ממש אתה אומר] לנימוק שיטתך שאינה מטמאה למפרע, והוא משום ש\u0003אם איתא דהוה\u0004 \u0005[אמנם שהיה]\u0006 \u0003דם, מעיקרא הוה אתי\u0004 \u0005[מתחילה היה בא],\u0006 \u0003ומיהו\u0004 \u0005[ואולם],\u0006 למרות טעם זה, \u0003עשה סייג\u0004 (גדר) \u0003לדבריך,\u0004 וטמא את האשה למפרע, \u0003דמאי שנא\u0004 \u0005[ש\u0006כן \u0005מה שונה]\u0006 דבר זה \u0003מכל\u0004 מצוות \u0003התורה כולה דעבדינן\u0004 \u0005[שאנו עושים]\u0006 בהן \u0003סייג?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 שמאי להלל: אף אין לעשות כך, ש\u0003אם כן,\u0004 נמצא שבכך \u0003בטלת בנות ישראל מפריה ורביה! והלל\u0004 משיב על כך: וכי \u0003מפריה ורביה מי קאמינא\u0004 \u0005[האם אני אומר]\u0006 שייחשבו לטמאות לבעליהן? רק \u0003ל\u0004ענין שיטמאו למפרע את ה\u0003טהרות הוא דקאמינא\u0004 \u0005[שאני אומר].\u0006","\u0003ושמאי\u0004 משיב על טענה זו: לגזור טומאה למפרע \u0003לטהרות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 ראוי לעשות, משום ש\u0003אם כן\u0004 יהא הדין, יהא \u0003לבו\u0004 של הבעל \u0003נוקפו\u0004 (מכהו) שמא אשתו טמאה, \u0003ו\u0004יהא \u0003פורש\u0004 ממנה שלא כדין, ומבטל מצוות פריה ורביה.","המלים הבאות: \u0003שולים, בדוקין, מכוסין בזוית,\u0004 הם \u0003סימן\u0004 לזכרון העניינים שיידונו בסוגיה הבאה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 בברייתא: \u0003קופה\u0004 (סל) \u0003שנשתמשו בה\u0004 והניחו \u0003טהרות בזוית זו\u0004 של הקופה, \u0003ו\u0004לאחר שהוציאו ממנה את הטהרות \u0003נמצא\u0004 \u0003שרץ בזוית אחרת\u0004 של הקופה, מה דין הטהרות? \u0003חזקיה אמר:\u0004 ה\u0003טהרות הראשונות,\u0004 אלה שהוצאו מן הקופה קודם למציאת השרץ — \u0003טהורות,\u0004 ואלה שהוצאו מן הקופה לאחר מציאת השרץ — טמאות. שמא נגע השרץ בטהרות. ואילו \u0003ר' יוחנן אמר:\u0004 אף ה\u0003טהרות הראשונות טמאות.\u0004 ומקשים לשיטת חזקיה המטהר את הטהרות הראשונות: \u0003והא\u0004 \u0005[והרי]\u0006 שנינו ש\u0003שמאי והלל\u0004 \u0003מודו\u0004 \u0005[מודים,\u0006 מסכימים\u0005]\u0006 \u0003בקופה\u0004 שנמצא בה שרץ שה\u0003טהרות הראשונות טמאות!\u0004","ומשיבים: \u0003כי מודו\u0004 \u0005[כאשר מודים]\u0006 \u0003שמאי והלל\u0004 הרי זה דווקא \u0003בקופה שיש לה שולים\u0004 (תחתית) והיא ניצבת על תחתיתה, וכשמוציאים דברים מהקופה, מוציאים מחלקה העליון, ואין השרץ הנמצא בחלקה התחתון של הקופה נראה. ואילו \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 \u0003חזקיה ור' יוחנן,\u0004 הרי זה \u0003בקופה שאין לה שולים,\u0004 שכשמוציאים דברים ממנה, מגביהים אחד מצדיה, וכל מה שנמצא בה יוצא אל מחוצה לה. ולכן לדעת חזקיה הטהרות הראשונות טהורות, שכן אילו היה שרץ מצוי בקופה, היו רואים אותו.","ושואלים: אם מחלוקתם היא בקופה ש\u0003אין לה שולים,\u0004 אם כן \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מטמא \u0003ר' יוחנן\u0004 אף את הראשונות, והרי אילו היה בה שרץ היו רואים אותו בשעת ההוצאה! ומשיבים: מדובר בקופה שאמנם \u0003אין לה שולים,\u0004 אבל \u0003יש לה אוגנים\u0004 (שפה כפופה פנימה), ושמא בשעת ההוצאה עצרו האוגנים את השרץ, ולכן לא ראוהו אז. וחזקיה סבור כי אף שיש לה אוגנים, אילו היה בה שרץ, היו רואים אותו בהוצאות הקודמות. ומתוך שלא ראוהו, ודאי לא היה שם.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003המדלה\u0004 (שואב בדלי מים מן הבור, ושופכם לכלי קיבול) בדלי אחד מלוא \u0003עשרה דליים מים בזה אחר זה, ונמצא שרץ באחד מהן\u0004 — \u0003הוא,\u0004 הדלי והמים שנשאבו בשאיבה שבה נמצא השרץ — \u0003טמא, וכולן,\u0004 כל שאר המים שנשאבו בשאיבות האחרות — \u0003טהורין,\u0004 שמניחים אנו שהשרץ נפל רק עתה לדלי הזה. \u0003ואמר ריש לקיש\u0004 בפירושה של ברייתא זו \u0003משום\u0004 (בשם) \u0003ר' ינאי: לא שנו\u0004 הלכה זו שהשאר טהורים \u0003אלא\u0004 בדלי \u0003שאין לה אוגנים,\u0004 שבכגון זה ברור שלא היה השרץ בדלי בשאיבות הקודמות, \u0003אבל\u0004 בדלי ש\u0003יש לה אוגנים\u0004 שיתכן שעיכבו את השרץ מלצאת — \u0003כולן,\u0004 אף כל המים שבשאר השאיבות, \u0003טמאין.\u0004","ודנים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003חזקיה\u0004 הסבור שאף שיש לה אוגנים, הטהרות הראשונות טהורות, \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 כדברי \u0003ר' ינאי?\u0004 ומשיבים: אין לדמות בין המקרים, שכן תכונתם של \u0003מיא\u0004 \u0005[מים]\u0006 שהם \u0003שרקי\u0004 \u0005[מחליקים,\u0006 ניגרים\u0005],\u0006 ולכן די בהטייה קלה של הדלי כדי שיישפכו החוצה, ובכגון זה יש חשש (לדעת ר' ינאי) שמא נשאר השרץ בתוך הדלי ולא יצא החוצה, ואולם \u0003פירי\u0004 \u0005[פירות]\u0006 תכונתם שהם \u0003לא שרקי\u0004 \u0005[מחליקים]\u0006 מן הכלי שבו הם נמצאים, וכדי להוציאם מהקופה יש להפוך אותה לגמרי על פניה, ואילו היה השרץ בתוכה, בודאי היה נופל אז החוצה, למרות האוגנים. ולכן אם נמצא בה שרץ, מניחים אנו שלא היה השרץ בתוכה קודם.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 הבדל נוסף: ב\u0003מיא\u0004 \u0005[מים]\u0006 אם נשארו מעט מים בכלי — אדם \u0003לא קפיד עלייהו\u0004 \u0005[מקפיד עליהם]\u0006 על המים ולכן אין דולה המים מדייק לערות כל מה שבדלי, ויש לחשוש בדלי שיש לו אוגנים, שמא נמצא שרץ בתוכו כבר אז ולא יצא באחד מהעירויים הקודמים. ואולם ב\u0003פירי\u0004 \u0005[פירות]\u0006 — אדם \u0003קפיד עלייהו\u0004 \u0005[מקפיד עליהם,\u0006 על הפירות הנשארים בכלי\u0005],\u0006 ולכן ברור שיצאו מהכלי כל הפירות שבתוכו, אף שיש לו אוגנים, ואם היה בתוכו גם שרץ היה יוצא עמהם.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003כי מודו\u0004 \u0005[כאשר מסכימים]\u0006 \u0003שמאי והלל\u0004 שיש להעמיד את הטהרות הראשונות בחזקת טמאות, הרי זה מדובר דווקא \u0003בקופה שאינה בדוקה,\u0004 שלא נבדקה בזמן שניתנו בתוכה הטהרות, ולכן אין לה חזקת טהרה."],["ואילו \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 \u0003חזקיה ור' יוחנן\u0004 הרי זה \u0003בקופה בדוקה,\u0004 שנבדקה לפני שהניחו בה את הטהרות, ולא נמצא בה שרץ. ובכך נחלקו: ש\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חזקיה, \u0005סבור]\u0006 שאין לטמא את הטהרות הראשונות, שכן \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בדקה\u0004 ומסתבר שרק לאחר שהוצאו ממנה הטהרות הללו הגיע לתוכה השרץ. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי שמא \u0003אימור\u0004 \u0005[אמור]\u0006 שמיד \u0003עם סילוק ידו\u0004 לאחר הבדיקה, \u0003נפל\u0004 השרץ לקופה.","ומקשים: ומדוע נעמיד את מחלוקת שמאי הלל דווקא בקופה שאינה בדוקה, \u0003והא\u0004 \u0005[והרי]\u0006 שיטותיהם בדין הקופה \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003אשה\u0004 שראתה דם \u0003קתני\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 בה נידונים דבריהם, \u0003ואשה\u0004 הרי \u0003בדוקה היא,\u0004 שכן בודקת עצמה בשחרית ובערבית (כדלהלן). ובוודאי גם בקופה מדובר בבדוקה! ומשיבים: \u0003כיון דשכיחי\u0004 \u0005[שמצויים]\u0006 \u0003בה\u0004 באשה \u0003דמים\u0004 — \u0003כ\u0004מי \u0003שאינה בדוקה דמיא\u0004 \u0005[נחשבת].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הבדל אחר: \u0003כי מודו\u0004 \u0005[כאשר מודים]\u0006 \u0003שמאי והלל\u0004 שהטהרות הראשונות שבקופה טמאות, הרי זה \u0003בקופה שאינה מכוסה\u0004 ויתכן שעם סילוק ידיו ממנה נפל השרץ לתוכה. ואולם \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 \u0003חזקיה ור' יוחנן\u0004 הרי זה \u0003בקופה מכוסה,\u0004 ולכן טיהרם חזקיה. ותוהים: אם \u0003מכוסה\u0004 היא \u0003היכי\u0004 \u0005[כיצד]\u0006 \u0003נפל\u0004 בתוכה השרץ? ומשיבים: \u0003כגון שתשמישה על ידי\u0004 הסרת ה\u0003כסוי.\u0004 שחזקיה סבור שכל זמן שהטהרות בתוכה הריהו נזהר, ובוודאי לא נכנס אז השרץ בתוכה. ור' יוחנן סבור שחוששים שמא בשעה שגילה את הכיסוי, נפל לתוכה השרץ וטימא את הפירות.","ומקשים לחזקיה: \u0003והא דומיא\u0004 \u0005[והרי בדומה]\u0006 ל\u0003אשה קתני\u0004 \u0005[שנה],\u0006 \u0003ואשה\u0004 כ\u0003מכוסה היא,\u0004 שהרי אין דם מבחוץ יכול להיכנס לתוכה, ובדומה לקופה, ובכל זאת היא טמאה! ומשיבים: \u0003כיון דשכיחי\u0004 \u0005[שמצויים]\u0006 \u0003בה דמים\u0004 — \u0003כ\u0004מי \u0003שאין מכוסה\u0004 היא \u0003דמיא\u0004 \u0005[נחשבת].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 יש הבדל אחר, \u0003כי מודו\u0004 \u0005[כאשר מודים]\u0006 \u0003שמאי והלל\u0004 שהטהרות הראשונות שבקופה טמאות, הרי זה כשהן מונחות \u0003בזוית קופה.\u0004 ואולם \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 \u0003חזקיה ור' יוחנן\u0004 היה זה \u0003בזוית בית.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"קופה\" קאמר\u0004 \u0005[אמר]\u0006 ולא בית!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003קופה שנשתמשו בה טהרות בזוית בית זו, וטלטלוה\u0004 והניחוה \u0003בזוית אחרת, ונמצא שרץ\u0004 כשהוא \u0003בזוית\u0004 ה\u0003אחרת.\u0004 ובכך נחלקו: \u0003חזקיה סבר: לא מחזקינן\u0004 \u0005[אין אנו מחזיקים]\u0006 \u0003טומאה ממקום למקום,\u0004 שאף שנמצאה בה טומאה במקום אחד, אין אומרים שהיתה בה הטומאה קודם לכן במקום אחר, ולכן הטהרות שהיו בה בראשונה — טהורות. \u0003ו\u0004אילו \u0003ר' יוחנן סבר: מחזקינן\u0004 \u0005[מחזיקים אנו],\u0006 ולכן אף הראשונות טמאות.","ושואלים: \u0003ומי מחזקינן\u0004 \u0005[והאם מחזיקים אנו]\u0006 טומאה ממקום למקום? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה במסכת טהרות\u0005]:\u0006 \u0003נגע באחד בלילה, ואינו יודע אם\u0004 האדם שנגע בו \u0003חי אם מת, ולמחר השכים ומצאו\u0004 שהוא \u0003מת\u0004 — \u0003ר' מאיר מטהר\u0004 את הנוגע,","\u0003וחכמים מטמאין,\u0004 וטעמם: \u0003שכל הטמאות כשעת מציאתן,\u0004 וכיון שמצא בבוקר שהוא מת, יש להניח שכבר היה מת גם בלילה.","\u0003ותני עלה\u0004 \u0005[ושנה\u0006 בברייתא \u0005עליה]:\u0006 \u0003כשעת מציאתן, ובמקום מציאתן,\u0004 שרק אם מצאו מת באותו מקום הריהו טמא, ואולם אם מצאו במקום אחר — הריהו טהור.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 שאם נמצא מת במקום אחר — הנוגע טהור, אין זו טהרה מוחלטת, ואמרו כן רק לענין שלא \u0003לשרוף\u0004 את התרומה על מגע כזה, \u0003אבל\u0004 לענין \u0003לתלות\u0004 (לא להשתמש בה ולא לשורפה) — \u0003תלינן\u0004 \u0005[תולים אנו]?!\u0006 \u0003ומי תלינן\u0004 \u0005[והאם אנו תולים]?\u0006","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה שם\u0005]:\u0006 \u0003מחט\u0004 טמאה \u0003שנמצאת\u0004 מונחת על גבי תרומה והיא \u0003מלאה חלודה או שבורה\u0004 — כיון שמחט זו כמות שהיא עכשיו הריהי טהורה, אף התרומה \u0003טהורה.\u0004 ואין חוששים שמא כשהונחה עליהם היתה שלמה וטימאתם ורק אחר כך נשברה. שכן כלל הוא \u0003שכל הטמאות כשעת מציאתן,\u0004 ומעתה יש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 כך הדין? \u0003לימא\u0004 \u0005[נאמר]\u0006 כי \u0003האי מעיקרא\u0004 \u0005[זו\u0006 המחט \u0005מתחילתה]\u0006 \u0003מחט מעלייתא\u0004 \u0005[מעולה]\u0006 \u0003היא, והשתא\u0004 \u0005[ו\u0006רק \u0005עכשיו]\u0006 \u0003הוא דהעלה\u0004 \u0005[שהעלתה]\u0006 \u0003חלודה,\u0004 ולכל הפחות יהא דין הטהרות הללו לתלות. אלא מכאן שאין חוששים לכך, ואין תולים!","\u0003ועוד,\u0004 הלא \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה שם\u0005]:\u0006 \u0003מצא שרץ שרוף\u0004 (שכיון שנשרף שוב אינו מטמא) \u0003על גבי הזיתים\u0004 של תרומה, \u0003וכן מטלית\u0004 של זב \u0003המהומהם\u0004 (בלוי), (שכיון שהתבלתה, נטהרה בכך) — הרי זה \u0003טהור.\u0004 ואין חוששים שמא הונח השרץ על הזיתים קודם שנשרף, או המטלית של הזב קודם שהתבלתה, וטימאום. שכן כלל הוא, \u0003שכל הטמאות כשעת מציאתן!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שנוהגים בהם \u0003כשעת מציאתן בין לקולא\u0004 \u0005[להקל],\u0006 כמו בדין המחט עצמה, שרואים אותם כמי שנגעה בהם המחט רק משנשברה או משהחלידה, ולכן הם טהורים. \u0003בין לחומרא\u0004 \u0005[להחמיר],\u0006 וכמו זה שנמצא בבוקר מת, שמטמאים את זה שנגע בו בלילה. \u0003ו\u0004כל זה הוא רק \u0003במקום מציאתן, אבל שלא במקום מציאתן\u0004 — אף על פי ש\u0003משרף לא שרפינן\u0004 \u0005[אין אנו שורפים]\u0006 עליהם, בכל זאת \u0003מתלא תלינן\u0004 \u0005[לתלות תולים אנו],\u0006","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 בתוספתא טהרות\u0005]:\u0006 \u0003ככר\u0004 טהורה שהיתה מונחת \u0003על גבי הדף\u0004 (לוח עץ הקבוע בקיר, כמדף), \u0003ומדף טמא\u0004 (כגון בגד של זב) \u0003מונח תחתיו.\u0004 \u0003אף על פי שאם נפלה\u0004 הכיכר \u0003אי אפשר\u0004 שתיפול \u0003אלא אם כן נגעה\u0004 במדף טמא זה — אם נמצאה על הארץ באופן שאינה נוגעת במדף — \u0003טהורה\u0004 היא. \u0003שאני אומר:\u0004 לא נפלה, אלא \u0003אדם טהור נכנס לשם ונטלה\u0004 מן הדף, והניחה על הארץ.","\u0003עד שיאמר: ברי\u0004 (ודאי) \u0003לי שלא נכנס אדם שם.\u0004 \u0003ואמר ר'\u0004 \u0003אלעזר: לא נצרכה\u0004 להיאמר סברה זו, \u0003אלא\u0004 אפילו כאשר לוח העץ עליו היא מונחת הוא \u0003מקום מדרון\u0004 (שיפוע), שמסתבר שתיפול הכיכר מאליה על הבגד הטמא, הרי שאין מחזיקים טומאה ממקום למקום, ואפילו לענין לתלות!","ומשיבים: \u0003התם כדקתני טעמא\u0004 \u0005[שם כמו ששנה\u0006 את \u0005הטעם],\u0006"],["\u0003שאני אומר\u0004 (מניח) כי \u0003אדם טהור נכנס לשם ונטלה,\u0004 והניח אותה במקום זה. וכיון שיש במה לתלות, אין אנו מחזיקים טומאה.","ושואלים: \u0003הכא נמי\u0004 \u0005[כאן\u0006 בקופה \u0005גם כן]\u0006 לגבי השרץ \u0003נימא\u0004 \u0005[נאמר]\u0006 שלא היה השרץ בקופה בתחילה, ו\u0003עורב אתא\u0004 \u0005[בא]\u0006 \u0003ושדא\u0004 \u0005[וזרק]\u0006 את השרץ הזה לתוכה! ומשיבים: \u0003אדם\u0004 שמעשיו נעשים \u0003בכונה,\u0004 לשם תכלית מסויימת — \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 שנטל את הככר, כדי למנוע ממנה טומאה. ואילו \u0003עורב\u0004 שמעשיו \u0003שלא בכונה\u0004 — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 בו שכך עשה. ומבררים דין זה של הככר שהיה על הדף.","ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 ספיקו של \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003ככר, ספק טומאה ברשות היחיד הוא, ו\u0004כלל הוא ש\u0003כל ספק טומאה ברשות היחיד\u0004 — \u0003ספקה טמא,\u0004 ומדוע מקילים לומר שאדם טהור נטלה? ומשיבים: \u0003משום דהוי\u0004 \u0005[ש\u0006ככר זו \u0005הריהי]\u0006 בגדר \u0003דבר שאין בו דעת לישאל,\u0004 שהרי הככר שיש בה ספק אינה בת שאלה, \u0003ו\u0004כלל הוא ש\u0003כל\u0004 ספק טומאה של \u0003דבר שאין בו דעת לישאל, בין\u0004 שספק טומאה זה הינו \u0003ברשות הרבים\u0004 ו\u0003בין\u0004 שהוא \u0003ברשות היחיד\u0004 — \u0003ספקו טהור.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003בטומאה דרבנן\u0004 \u0005[מדברי חכמים],\u0006 ובטומאה זו מקילים בספקה, אף ברשות היחיד. ומוסיפים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 שבטומאה מדברי חכמים אנו עוסקים כאן, \u0003דקתני\u0004 \u0005[ש\u0006כן שנה] בדין זה של הככר שהיה \u0003\"מדף\u0004 טמא תחתיו\", ולשון \"מדף\" מורה על טומאה קלה, שאין היא חמורה כטומאת התורה אלא מדברי חכמים בלבד. ומנין שלשון זו מורה על דבר קל — \u0003כדכתיב\u0004 \u0005[כמו שנאמר]: \"\u0006\u0003עלה נדף\"\u0004 (ויקרא כו, לו), ומובן לשון זו: דבר קל.","\u0003ו\u0004עוד שנינו במשנתנו בדין אשה שאין לה וסת וראתה דם, כי \u0003חכמים אומרים\u0004 ביחס לשיטותיהם של שמאי והלל: הדין \u0003לא כדברי זה\u0004 (שמאי), ולא כדברי זה (הלל). ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003וחכמים אומרים: לא כדברי זה ולא כדברי זה, לא כדברי שמאי\u0004 — \u0003שלא עשה סייג\u0004 (גבול) \u0003לדבריו\u0004 אלא היקל הרבה, \u0003ולא כדברי הלל\u0004 — \u0003שהפריז\u0004 (פרץ גבול) \u0003על מדותיו\u0004 והחמיר הרבה.","\u0003אלא\u0004 תקופת הזמן של \u0003מעת לעת ממעטת על יד\u0004 מתקופת הזמן של \u0003מפקידה לפקידה\u0004 (מבדיקה לבדיקה), \u0003ו\u0004תקופת הזמן של \u0003מפקידה לפקידה ממעטת על יד\u0004 מזמן של \u0003מעת לעת.\u0004","ומסבירים: \u0003מעת לעת ממעטת על יד מפקידה לפקידה,\u0004 \u0003כיצד?\u0004 — \u0003בדקה עצמה ב\u0004יום \u0003אחד בשבת\u0004 (ראשון בשבוע), \u0003ומצאת\u0004 (מצאה) עצמה שהיא \u0003טהורה, וישבה\u0004 יום \u0003שני ו\u0004יום \u0003שלישי\u0004 בשבוע, \u0003ולא בדקה\u0004 עצמה, \u0003ול\u0004יום \u0003רביעי\u0004 בשבוע \u0003בדקה\u0004 עצמה \u0003ומצאה\u0004 שהיא \u0003טמאה\u0004 — \u0003אין אומרים\u0004 במקרה זה ש\u0003תטמא\u0004 למפרע את כל הטהרות שעסקה בהן \u0003מ\u0004ה\u0003פקידה\u0004 ביום רביעי \u0003לפקידה\u0004 ביום ראשון, \u0003אלא\u0004 הריהי מטמאת למפרע \u0003מעת לעת\u0004 בלבד.","\u0003ו\u0004מצד שני, \u0003מפקידה לפקידה ממעטת על יד מעת לעת, כיצד?\u0004 — \u0003בדקה עצמה בשעה ראשונה\u0004 ביום, \u0003ומצאת\u0004 שהיא \u0003טהורה, וישבה לה\u0004 בשעה ה\u0003שניה ו\u0004ה\u0003שלישית ולא בדקה, ול\u0004שעה ה\u0003רביעית בדקה ומצאה\u0004 שהיא \u0003טמאה\u0004 — \u0003אין אומרים\u0004 במקרה זה ש\u0003תטמא\u0004 למפרע כל ה\u0003מעת לעת,\u0004 משעה ראשונה של יום אתמול, \u0003אלא\u0004 הריהי מטמאת למפרע רק \u0003מ\u0004ה\u0003פקידה\u0004 בשעה הראשונה \u0003לפקידה\u0004 בשעה הרביעית.","על כך שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא, שהרי \u0003כיון\u0004 ש\u0003בדקה עצמה בשעה ראשונה ומצאת\u0004 עצמה שהיא \u0003טהורה\u0004 — \u0003לא מטמינן לה\u0004 \u0005[אין אנו מטמאים אותה]\u0006 \u0003מעת לעת,\u0004 שהרי בדוקה היתה, ואין צורך להשמיענו דבר זה! ומשיבים: \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 שתקופת הזמן של \u0003מעת לעת ממעטת על יד מפקידה לפקידה, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 שתקופת הזמן של \u0003מפקידה לפקידה ממעטת על יד מעת לעת.\u0004","ובהסבר שיטת חכמים, \u0003אמר רבה: מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 שאם משך הזמן בין הבדיקות היה כמה ימים שאין האשה מטמאת למפרע אלא מעת לעת, אף שיתכן שראתה קודם?! \u0003אשה מרגשת בעצמה\u0004 בצאת הדם, ומאחר ולא הרגישה ודאי לא ראתה, ואין לחשוש לכך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אם כן, תהא\u0004 ההלכה לשיטת חכמים באשה הרואה, ולא הרגישה מקודם, ש\u0003דיה שעתה\u0004 בלבד, ולא תטמא למפרע כלל, וכשיטת שמאי! \u0003ו\u0004משיבים: הסבר זה שאמר \u0003רבה\u0004 בשיטת חכמים, לא התכוון לומר אותו להלכה, אלא רק כדי \u0003לחדודי\u0004 \u0005[לחדד]\u0006 את \u0003אביי\u0004 תלמידו \u0003הוא דבעי\u0004 \u0005[שרצה],\u0006 לראות אם יעמוד אביי על הקושי שבדבר, ואכן שאל אביי אותו על כך. ושואלים: \u0003אלא\u0004 אם כן, \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה\u0006 אכן \u0005טעמם של חכמים]? ומשיבים:\u0006","\u0003כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר רב יהודה, אמר שמואל: חכמים תקנו להן לבנות ישראל\u0004 העוסקות בטהרות \u0003שיהו בודקות עצמן\u0004 בכל יום ויום ב\u0003שחרית ו\u0004ב\u0003ערבית.\u0004 בדיקת \u0003שחרית\u0004 — כדי \u0003להכשיר\u0004 על ידה (אם תימצא בבדיקה שהיא טהורה) את ה\u0003טהרות של\u0004 ה\u0003לילה\u0004 הקודם שנגעה בהן, \u0003ו\u0004בדיקת \u0003ערבית\u0004 — כדי \u0003להכשיר טהרות של\u0004 ה\u0003יום\u0004 הקודם,","\u0003וזו הואיל\u0004 ועברה על תקנת חכמים, \u0003ולא בדקה\u0004 עצמה — קנסוה חכמים ש\u0003הפסידה\u0004 (קלקלה) טהרות של \u0003עונה\u0004 (אחת מיחידות הזמן שביממה, יום או לילה). ומסבירים את דברי שמואל: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005],\u0006 מדוע אחז לשון \u0003\"עונה\",\u0004 אף שדינה שהיא מטמאת מעת לעת, שהן שתי עונות — הכוונה היא שהפסידה \u0003עונה יתירה\u0004 (נוספת), שאילו קיימה תקנת חכמים ובדקה עצמה שחרית וערבית קודם שעסקה בטהרות — לא היתה נטמאת אלא עונה אחת בלבד (שבין הבדיקה הקודמת, שנמצאה בה טהורה, לבדיקה שנמצאה בה טמאה). וזו שלא עשתה כן, הריהי מטמאת שתי עונות, שהן \"מעת לעת\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא\u0004 בשאלה על הסבר זה של שמואל: \u0003והא זימנין משכחת לה\u0004 \u0005[והרי פעמים אתה מוצא]\u0006 אפשרות ל\u0003שלש עונות במעת לעת\u0004 אחד (עשרים וארבע שעות), וכגון שלא בדקה עצמה כמה יממות, ובדקה עצמה בצהרי יממה זו ומצאה טמאה, שהרי היא מטמאה את כל הטהרות שעסקה בהן למפרע מעת לעת עד לצהרי יממת אתמול, והרי בכלל עשרים וארבע שעות אלו, ישנן שלוש עונות (יום אתמול שביממה הקודמת, ולילה ויום שביממה זו), והרי זה איפוא יותר מאשר תוספת קנס של עונה אחת! השיב לו רבא לרב פפא: \u0003השוו חכמים מדותיהן\u0004 (קביעותיהם) שתהיינה כולן בהגדרה אחת, \u0003שלא תחלוק\u0004 (תבדיל) \u0003במעת לעת\u0004 זה ואחר.","ו\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר לשאלתך: הטעם שמטמאה עד לצהרי היממה של אתמול הוא משום \u0003שלא יהא חוטא נשכר.\u0004 שכן אילו היתה בודקת שחרית ומצאה עצמה טמאה, היתה מטמאת למפרע מעת לעת. וזו שנהגה שלא כראוי ודחתה בדיקתה עד לצהריים, אין סברה לטמאה רק עונה אחת נוספת מעבר לאותו היום.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל להלכה \u0005ביניהם\u0006 בין שני התירוצים הללו\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל להלכה\u0005]\u0006 במקרה \u0003דאתניסה\u0004 \u0005[שנאנסה,\u0006 במקרה של כורח\u0005]\u0006 \u0003ו\u0004כתוצאה מכך, \u0003לא בדקה\u0004 בשחרית. שלפי הטעם שלא יהא חוטא נשכר — אינה מטמאה למפרע מעת לעת, משום שאין היא בגדר חוטא, ואולם לפי הטעם שחכמים השוו מידותיהם — אף במקרה זה הריהי מטמאה מעת לעת בלבד.","שנינו במשנתנו כי \u0003כל אשה שיש לה וסת\u0004 קבוע שלוש פעמים, וראתה, דייה שעתה. ושואלים: \u0003לימא מתניתין\u0004 \u0005[האם נאמר\u0006 ש\u0005משנתנו] כשיטת\u0006 \u0003ר' דוסא היא ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: ארבע נשים,\u0004 אם ראו דם, \u0003דיין שעתן,\u0004 שכן הריהן בחזקת שאינן רואות דם, ואלו הן: ה\u0003בתולה,\u0004 שעדיין לא ראתה דם מעולם, וזו לה הראיה הראשונה, וה\u0003מעוברת\u0004 שהוכר עוברה, וה\u0003מניקה, ו\u0004ה\u0003זקנה.\u0004 \u0003ר'\u0004 \u0003דוסא אומר: כל אשה שיש לה וסת דיה שעתה,\u0004 ובניגוד לדעת חכמים הסבורים שרק אותן ארבע דיין שעתן!","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 החולקים על ר' דוסא, ואולם \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חלקו חכמים עליו]\u0006 על \u0003ר' דוסא אלא\u0004 כשראתה האשה שיש לה וסת \u0003שלא בשעת וסתה,\u0004 שסבורים חכמים כי מכיון שבא הדם שלא בזמנו, יש לחשוש בו שכבר יצא קודם לכן, והיא לא חשה בו, \u0003אבל\u0004 כשראתה \u0003בשעת וסתה מודו ליה\u0004 \u0005[מודים\u0006 חכמים \u0005לו\u0006 לר' דוסא\u0005]\u0006 שדייה שעתה, \u0003ומתניתין\u0004 \u0005[ומשנתנו]\u0006 מדברת באופן שראתה \u0003בשעת וסתה, ו\u0004כ\u0003דברי הכל\u0004 היא משנתנו.","ושואלים: \u0003מכלל\u0004 זה אתה למד ש\u0003ר' דוסא אפילו\u0004 בראתה \u0003שלא בשעת וסתה אמר\u0004 שדייה שעתה. אם כן \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי\u0006 החכם ש\u0005שנה את\u0006 הברייתא \u0005הזו ששנו חכמים]:\u0006 \u0003אשה שיש לה וסת\u0004 ומצאה כתם דם בבגדה שלא בשעת וסתה — \u0003כתמה טמא\u0004 ומטמאה למפרע, עד שעת בדיקת הבגד או כיבוסו. וסיבת הדבר: \u0003ש\u0004כן \u0003אם תראה\u0004 אשה שיש לה וסת, דם \u0003שלא בשעת וסתה\u0004 — הריהי \u0003מטמאה\u0004 למפרע \u0003מעת לעת.\u0004","האם \u0003נימא\u0004 \u0005[נאמר]\u0006 ששיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, ולא\u0004 שיטת \u0003ר' דוסא?\u0004 ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא שיטת \u0003ר' דוסא, עד כאן לא\u0004 שמענו כי \u0003פליג\u0004 \u0005[חלק]\u0006 \u0003ר' דוסא עלייהו דרבנן\u0004 \u0005[עליהם, על חכמים]\u0006 \u0003אלא\u0004 כשראתה \u0003בשעת וסתה, אבל\u0004 ראתה \u0003שלא בשעת וסתה מודי להו\u0004 \u0005[מודה להם]\u0006 שמטמאה למפרע. \u0003ומתניתין\u0004 \u0005[ומשנתנו]\u0006 מדברת \u0003בשעת וסתה, ו\u0004שיטת \u0003ר' דוסא היא,\u0004"],["\u0003ו\u0004אילו שיטת ה\u0003ברייתא\u0004 שכתם באשה שיש לה וסת ונמצא שלא בעת וסתה מטמא למפרע — הריהי כ\u0003דברי הכל,\u0004 שאף ר' דוסא סבור שהאשה שיש לה וסת הרואה שלא בשעת וסתה, שמטמאה למפרע.","ושואלים: מדוע מעמידים את משנתנו כשיטת ר' דוסא, שהוא דעת יחיד, כדי שתוסבר הברייתא לשיטות הכל, \u0003ולוקמא איפכא\u0004 \u0005[ושיעמיד אותה להיפך],\u0006 שהמשנה היא לכל הדעות, וברייתא זו היא לשיטת חכמים בלבד, וכמו שהסברנו קודם?!","ומשיבים: \u0003כיון דאיכא לאוקומי\u0004 \u0005[שאפשר להעמיד]\u0006 את השיטה המוסכמת על הכל (\"דברי הכל\") באופנים שונים: האחד, \u0003לקולא\u0004 \u0005[להקל],\u0006 שהרואה בשעת וסתה מוסכם על הכל שדיה שעתה, ונחלקו רק שלא בשעת וסתה. והשני, \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 שכאשר רואה שלא בשעת וסתה, מוסכם על הכל שמטמאה למפרע, וחכמים סבורים שאף בשעת וסתה יש להחמיר בה. ובמקרה שניתן בו לפרש להקל או להחמיר — \u0003לחומרא מוקמינן\u0004 \u0005[להחמיר אנו מעמידים,\u0006 מסכימים\u0005].\u0006","בברייתא שהובאה מקודם \u0003קתני\u0004 \u0005[שונה\u0006 התנא\u0005]\u0006 כי האשה הרואה כתם מטמאת למפרע, \u0003שאם תראה\u0004 האשה דם \u0003שלא בשעת וסתה\u0004 הריהי \u0003מטמאה מעת לעת.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[\u0006מתוך \u0005הטעם]\u0006 הזה נלמד, שדווקא בדינה של \u0003אשה שיש לה וסת הוא, דפליגי רבנן\u0004 \u0005[שמחלקים חכמים]\u0006 \u0003בין כתמה,\u0004 שמטמא למפרע, \u0003לראייתה\u0004 בשעת הוסת, שאינה מטמאה למפרע.","ומכאן נסיק: \u0003הא\u0004 \u0005[הרי,\u0006 אבל\u0005]\u0006 \u0003שאר נשים\u0004 כגון אלו שהן בחזקת מסולקות דמים, \u0003שאמרו\u0004 בהן \u0003חכמים\u0004 ש\u0003דיין שעתן,\u0004 ואינן מטמאות למפרע — אף דין \u0003כתמן\u0004 של אלו \u0003כ\u0004דין \u0003ראייתן.\u0004","ומעתה יש לברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? כשיטת \u0003ר' חנינא בן אנטיגנוס היא,\u0004 ש\u0003אמר רב יהודה, אמר שמואל משום\u0004 (בשם) \u0003ר' חנינא בן אנטיגנוס: כל הנשים\u0004 — \u0003כתמן טמא למפרע.\u0004 \u0003ו\u0004אותן \u0003נשים שאמרו\u0004 בהן \u0003חכמים\u0004 שאם ראו \u0003דיין שעתן\u0004 — דין \u0003כתמן\u0004 \u0003כ\u0004דין \u0003ראייתן,\u0004 ואינו מטמא אלא מכאן ולהבא. \u0003חוץ מתינוקת ש\u0004עדיין \u0003לא הגיע זמנה לראות, שאפילו\u0004 היו \u0003סדינין שלה מלוכלכין בדם,\u0004 ואינה יודעת אם בא דם זה לסדיניה מגופה או ממקום אחר — \u0003אין חוששין\u0004 (מחמירים מן הספק) \u0003לה\u0004 (עליה) לטמאה אף לא מכאן ולהבא.","ושואלים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו]\u0006 \u0003לר' חנינא\u0004 דין זה של טומאת ה\u0003כתם כלל\u0004 בנשים שהן מסולקות דמים? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל הנשים\u0004 שראו כתם — \u0003כתמן טמא.\u0004 \u0003ו\u0004אף ה\u0003נשים שאמרו\u0004 בהן \u0003חכמים\u0004 שאם ראו דם, ש\u0003דיין שעתן\u0004 — \u0003כתמן טמא.\u0004 \u0003ר'\u0004 \u0003חנינא בן אנטיגנוס אומר:\u0004 אותן ה\u0003נשים שאמרו\u0004 בהן \u0003חכמים דיין שעתן\u0004 — \u0003אין להן\u0004 דין \u0003כתם\u0004 המטמא. ויש לדייק: \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ש\u0003אין להן\u0004 דין טומאת \u0003כתם כלל,\u0004 ואף לא מכאן ולהבא! ומשיבים: \u0003לא,\u0004 כוונת ר' חנינא בן אנטיגנוס ש\u0003אין להן\u0004 דין \u0003כתם\u0004 לטמא \u0003למפרע,\u0004 \u0003אבל יש להן\u0004 דין טומאת \u0003כתם\u0004 לטמא \u0003מכאן ולהבא.\u0004","ושואלים: אם כן, \u0003מכלל\u0004 זה נסיק ש\u0003תנא קמא\u0004 \u0005[הראשון,\u0006 החולק על ר' חנינא בן אנטיגנוס\u0005]\u0006 ואמר שהנשים שאמרו דיין שעתן כתמן מטמא, \u0003סבר\u0004 \u0005[סבור]\u0006 ש\u0003אפילו למפרע\u0004 הוא מטמא, והרי אף אם הנשים הללו רואות דם מגופן אין הן טמאות למפרע! ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 כך היא שיטתו של תנא זה, וכשיטת \u0003ר' מאיר היא,\u0004 ש\u0003מחמיר גבי\u0004 \u0005[אצל]\u0006 דין ה\u0003כתמים.\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל הנשים\u0004 — \u0003כתמן טמא למפרע.\u0004 \u0003ו\u0004אף אותן \u0003נשים שאמרו\u0004 בהן \u0003חכמים\u0004 שאם ראו דם, ש\u0003דיין שעתן\u0004 לטמא, ואין הן מטמאות למפרע — \u0003כתמן טמא למפרע,\u0004 אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004","\u0003ר'\u0004 \u0003חנינא בן אנטיגנוס אומר:\u0004 אותן \u0003נשים שאמרו\u0004 בהן \u0003חכמים\u0004 שאם ראו דם ש\u0003דיין שעתן\u0004 ואינן מטמאות למפרע — אף דין \u0003כתמן כ\u0004דין \u0003ראייתן,\u0004 שאינו מטמא אלא מכאן ולהבא. \u0003ו\u0004בדין כתם התינוקת, יש להבחין: \u0003תינוקת שהגיע זמנה לראות\u0004 דם, ומצאה כתם על בגדה — \u0003יש לה\u0004 דין טומאת \u0003כתם,\u0004 \u0003ו\u0004זו \u0003שלא הגיע\u0004 עדיין \u0003זמנה לראות\u0004 — \u0003אין לה\u0004 דין טומאת \u0003כתם.\u0004 \u0003ואימתי\u0004 הוא זמן זה המכונה \"\u0003הגיע זמנה לראות\"?\u0004 — \u0003משהגיעו ימי הנעורים,\u0004 שהביאה שתי שערות, או שהיא בת שתים עשרה שנה ויום אחד.","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003המשמשת בעדים\u0004 — הרי זו כבדיקה גמורה (\"פקידה\"), ואם לא מצאה דם בבדיקה זו, הריהי ממעטת את תקופת הזמן של מעת לעת ושל מפקידה לפקידה, ואין הטהרות שנגעה בהן קודם בדיקה זו טמאים. ובענין זה \u0003אמר רב יהודה, אמר שמואל:\u0004 הלכה זו שבדיקת עד של תשמיש ממעטת הריהי דווקא בבדיקת עד שלאחר התשמיש, ואולם בדיקת \u0003עד שלפני תשמיש\u0004 — \u0003אינו ממעט כפקידה.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רב קטינא: מתוך ש\u0004האשה \u0003מהומה\u0004 (נרגשת ונחפזת) \u0003ל\u0004קראת \u0003ביתה\u0004 (התשמיש הקרב), אין היא בודקת כראוי. ושואלים: \u0003ו\u0004אף \u0003כי\u0004 \u0005[כאשר]\u0006 היא \u0003מהומה לביתה מאי הוי\u0004 \u0005[מה נהיה,\u0006 מה בכך\u0005]?\u0006 והרי בסופו של דבר בדקה עצמה, ואם יש דם תראה אותו על העד! ומשיבים: \u0003מתוך שמהומה לביתה\u0004 — \u0003אינה מכנסת\u0004 את העד פנימה \u0003לחורין ולסדקין,\u0004 כפי שיש לעשות לבדיקת טהרות, ויש לחשוש שמא היה שם דם, ולא הגיע אליו העד.","ושואלים על דברי שמואל: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003המשמשת בעדים\u0004 — \u0003הרי זו כפקידה.\u0004 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 לשון רבים \"בעדים\" שאחז בה התנא מתייחסת לשני עדים, \u0003חד\u0004 \u0005[אחד]\u0006 ש\u0003לפני תשמיש, וחד\u0004 \u0005[ואחד]\u0006 ש\u0003לאחר תשמיש,\u0004 הרי שבדיקת עד לפני תשמיש, אף היא כפקידה, וממעטת כמותה, ושלא כדברי שמואל! ודוחים: \u0003לא, אידי ואידי\u0004 \u0005[זה וזה,\u0006 שני ה\"עדים\" שבמשנתנו\u0005]\u0006 הכוונה לבדיקה ש\u0003לאחר תשמיש, ו\u0004שניים אלה הם: \u0003אחד לו\u0004 — לבעל, המקנח בעד את בשרו לאחר התשמיש, ובודק אם נמצא בו דם. \u0003ואחד לה\u0004 — לאשה הבודקת עצמה. ו\u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה בתחילת הפרק הבא\u0005]:\u0006 \u0003דרך בנות ישראל\u0004 שהן \u0003משמשות\u0004 עם בעליהן \u0003בשני עדים, אחד לו ואחד לה.\u0004","ומקשים על תשובה זו: \u0003האי מאי\u0004 \u0005[זה מה הוא],\u0006 מה טענה היא זו?! שהרי \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שכוונת המשנה בלשון \"משמשת בעדים\" היא ל\u0003חד\u0004 \u0005[אחד]\u0006 ש\u0003לפני תשמיש וחד\u0004 \u0005[ואחד]\u0006 ש\u0003לאחר תשמיש\u0004 — \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, שהרי \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 ש\u0003מתוך שמהומה לביתה\u0004 ו\u0003לא בדקה שפיר\u0004 \u0005[יפה],\u0006 אין בעד שלפני התשמיש כדי להוכיח, ולכן \u0003קא משמע לן\u0004 \u0005[משמיעה לנו]\u0006 המשנה שאף בדיקה שלפני התשמיש \u0003הרי זו כפקידה.\u0004 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 שני עדים אלו הם לבדיקה \u0003לאחר תשמיש\u0004 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שבדיקה שלאחר התשמיש הריהי בדיקה לכל דבר, וממעטת מעת לעת ומפקידה לפקידה!","ומשיבים: חידוש יש בדבר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שיש לחשוש \u0003שמא תראה טפת דם\u0004 קטנה \u0003כ\u0004גרגיר זרע ה\u0003חרדל, ותחפנה\u0004 (תכסנה) \u0003שכבת זרע\u0004 ולא ייראה הדם מחמת כן, ולא תהא הבדיקה שלאחר תשמיש נחשבת, לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא שאין חוששים לזה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאכן לשון \"עדים\" באה ללמדנו ש\u0003שתי בדיקות אצרכוה רבנן\u0004 \u0005[הצריכוה חכמים],\u0006 \u0003חד\u0004 \u0005[אחת]\u0006 \u0003לפני תשמיש, וחד\u0004 \u0005[ואחת]\u0006 \u0003לאחר תשמיש,\u0004 ולכך כיוונה המשנה בדבריה כשאמרה \"משמשת בעדים\" — שכך ראוי לעשות, \u0003ו\u0004אולם \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 במשנה בהמשך הדברים \u0003\"הרי זו כפקידה\"\u0004 — הכוונה רק לבדיקה ש\u0003לאחר תשמיש,\u0004 וזו שלפניו אינה כפקידה, וכדברי שמואל. ושואלים: ואיך למד אתה ממשמעות דברי המשנה שצריכה האשה לבדוק עצמה לפני ולאחרי התשמיש, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"המשמשת\" קתני\u0004 \u0005[שנינו]\u0006 במשנה, ומשמע לשון זו שכך עשתה, ולא שמחוייבת היא בכך! ומציעים: \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003\"ומשמשת\u0004 בעדים\", שכך היא צריכה לעשות.","שנינו במשנתנו כי המשמשת בעדים ומצאה טהורה הריהי \u0003ממעטת על יד מעת לעת\u0004 ועל יד מפקידה לפקידה. ושואלים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 לאחר שכבר שנינו כי \u0003מעת לעת\u0004 היא \u0003ממעטת,\u0004"],["שממעטת בדיקה זו \u0003מפקידה לפקידה\u0004 אם היתה זו בתוך פרק הזמן של מעת לעת \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 והרי הוא זמן קצר יותר!","ומשיבים: יש מקום להשמיענו שממעטת אף מפקידה לפקידה, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 לתקופת זמן ארוכה זו של \u0003מעת לעת\u0004 — \u0003חשו\u0004 \u0005[חששו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים]\u0006 \u0003לפסידא\u0004 \u0005[להפסד]\u0006 של ה\u0003טהרות\u0004 שעסקה בהן באותו זמן, \u0003אבל\u0004 לתקופת זמן קצרה זו של \u0003מפקידה לפקידה\u0004 — \u0003לא\u0004 חששו, ולא נסמוך על בדיקה זו למעט אף מפקידה לפקידה, ועל כן תיטמאנה הטהרות שעסקה בהן, לכן \u0003קא משמע לן\u0004 \u0005[משמיעה לנו]\u0006 משנתנו שאף מפקידה לפקידה, ממעטת בדיקה זו.","שנינו במשנתנו: כיצד מתקיימת ההלכה ש\u0003דיה שעתה\u0004 באשה שיש לה וסת? — היתה האשה יושבת במיטה ועסוקה בטהרות, ופרשה (קמה) ממיטתה, וראתה דם — היא טמאה בטומאת נדה, ככל אשה הרואה דם. ואילו כולן (המיטה והטהרות שעסקה בהן) טהורות. ושואלים על לשון המשנה: \u0003למה לי למיתני\u0004 \u0005[לשנות]\u0006 \u0003\"היתה יושבת במטה ועסקה בטהרות\u0004 ופרשה וראתה\"? \u0003ליתני\u0004 \u0005[שישנה]\u0006 את עיקר הענין: \u0003\"היתה עסוקה בטהרות ופרשה וראתה\"\u0004 בלא לציין שהיתה יושבת במיטה כשעסקה בטהרות!","ומשיבים: בכוונה הזכיר התנא שיושבת על המיטה, ו\u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]:\u0006 \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שכולן טהורות, הוא משום שכיון שיש לה וסת קבוע \u0003דיה שעתה\u0004 לטמא מכאן והלאה בלבד. \u0003הא\u0004 \u0005[הרי]\u0006 מכאן שלפי חכמים שמטמאה למפרע \u0003מעת לעת,\u0004 לא רק שמטמאה את הטהרות, אלא ה\u0003מטה\u0004 שעליה ישבה \u0003נמי מטמיא\u0004 \u0005[גם כן מטמאה]. ומעירים: דבר זה\u0006 \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004חכם \u0003זעירי,\u0004 שכן \u0003אמר זעירי:\u0004 טומאת \u0003מעת לעת\u0004 למפרע \u0003שבנדה, עושה\u0004 גם טומאת \u0003משכב ומושב,\u0004 שאף המשכב עליו שכבה והמושב עליו ישבה במשך תקופה זו טמאים בדרגת טומאה כזו שיש בה \u0003לטמא אדם\u0004 הנוגע בהם, ו\u0003לטמא בגדים\u0004 שעליו.","ושואלים: \u0003מכדי\u0004 \u0005[מתוך]\u0006 ש\u0003האי\u0004 \u0005[זו]\u0006 ה\u0003מטה\u0004 הרי בגדר \u0003דבר שאין בו דעת לישאל הוא,\u0004 שהרי אי אפשר לשאול את המיטה עצמה כיצד היו הדברים, \u0003ו\u0004כלל הוא בדיני ספקות הטומאה ש\u0003כל דבר שאין בו דעת לישאל\u0004 — \u0003ספקו טהור\u0004 אף ברשות היחיד, ואף מטה זו לא תטמא למפרע, שהרי ספק הוא אם ראתה האשה קודם לכן, ויהא ספקה טהור! ומשיבים: \u0003תרגמה\u0004 \u0005[תרגם,\u0006 פירש \u0005אותה]\u0006 \u0003זעירי\u0004 שמדובר \u0003כשחברותיה\u0004 של נדה זו היו \u0003נושאות אותה במטה\u0004 בתוך מעת לעת קודם לראייתה, \u0003דהויא ליה\u0004 \u0005[שנהיית,\u0006 נחשבת \u0005היא\u0006 המיטה\u0005]\u0006 בכך כעין \u0003יד\u0004 מורחבת של \u0003חברותיה,\u0004 ונחשבת כדבר שיש בו דעת להישאל, וספקה טמא.","ומוסיפים עוד, \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 לאחר ש\u0003אמר ר'\u0004 \u0003יוחנן\u0004 שכל \u0003ספק טומאה הבאה בידי אדם\u0004 ביחס לכלי מסויים — הריהי כספק טומאה ש\u0003נשאלין עליה,\u0004 וספקה טמא, ו\u0003אפילו בכלי\u0004 ה\u0003מונח על גבי קרקע\u0004 — הריהו נחשב \u0003כמי שיש בו דעת לישאל,\u0004 נוכל לתרץ את שיטת זעירי, ש\u0003אף על פי שאין חברותיה נושאות אותה במטה\u0004 כיון שספק טומאת המיטה נובע מספק טומאת האשה ששכבה עליו, הריהי נחשבת כדבר שיש בו דעת להישאל, וכיון שהוא ספק ברשות היחיד — הריהי טמאה.","מתוך שהובאו דברי ר' יוחנן להסבר שיטת זעירי, דנים עתה בהלכה זו \u0003גופא\u0004 \u0005[לגופה,\u0006 כשלעצמה\u0005].\u0006 \u0003אמר ר'\u0004 \u0003יוחנן: ספק טומאה הבאה בידי אדם\u0004 — \u0003נשאלים עליה,\u0004 וספיקה ברשות היחיד טמא, ו\u0003אפילו בכלי המונח על גבי קרקע כמי שיש בו דעת לישאל\u0004 הוא נחשב.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בתוספתא: \u0003היה\u0004 איש טמא \u0003מתעטף בטליתו,\u0004 שאף היא טמאה ממגעו, \u0003ו\u0004היו חפצי \u0003טהרות\u0004 בצידו, וספק הוא אם תוך כדי עיטופו נגעה טליתו בהם וטימאתם, ספק לא נגעה. \u0003ו\u0004כן אם היו \u0003טומאות\u0004 כגון שרץ, \u0003בצדו,\u0004 והוא וטליתו טהורים, וספק אם נגעה בהן טליתו ונטמאה, או לא נגעה. \u0003ו\u0004כמו כן אם היו \u0003טהרות וטומאות למעלה מראשו,\u0004 ו\u0003ספק\u0004 אם \u0003נגע\u0004 הטלית בטומאות תוך כדי התעטפותו ולאחר מכן נגעה בטהרות, \u0003ספק לא נגע\u0004 — הטלית \u0003טהור.\u0004 \u0003ואם אי אפשר\u0004 שיתעטף בטליתו \u0003אלא אם כן נגע\u0004 בטומאות — הרי זה \u0003טמא.\u0004","\u0003רבן שמעון בן גמליאל אומר: אומרים לו: שנה,\u0004 כלומר, התעטף פעם שניה בטלית, כדרך שהתעטפת לפני כן, \u0003ושונה,\u0004 עושה כן פעם שנית, ורואים אם הוא נוגע בטומאות או לא. \u0003אמרו לו\u0004 חכמים לרבן שמעון בן גמליאל: \u0003אין שונים בטהרות,\u0004 כלומר, אין סומכים על עשייה פעם שניה בטהרות, משום שייתכן שהפעם השניה לא היתה בדיוק כמו הראשונה.","ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 לשיטת חכמים, בספק נגע בטומאות בשעת התעטפותו בטלית הריהו טהור? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ספק טומאה הבאה בידי אדם הוא,\u0004 ולשיטת ר' יוחנן הרי זה כדבר שיש בו דעת להישאל, וספיקו טמא!","ודוחים: \u0003בר מיניה דההיא\u0004 \u0005[חוץ ממנה מאותה\u0006 ברייתא\u0005],\u0006 כלומר, אין להקשות מברייתא זו, \u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003רב הושעיא\u0004 על מקרה זה: כל ספק טומאה, כאשר הוא \u0003ברשות היחיד\u0004 — \u0003ספקו טמא, ברשות הרבים\u0004 — ספקו \u0003טהור,\u0004 ודברי הברייתא נשנו ברשות הרבים, ואילו ברשות היחיד יהיה ספקו טמא, כשאר דבר שיש בו דעת להישאל.","למעלה הובאו דברי זעירי ונידונו דבריו. ומעתה דנים בהלכה זו \u0003גופא\u0004 \u0005[לגופה,\u0006 כשלעצמה\u0005].\u0006 \u0003אמר זעירי:\u0004 טומאה זו בכל \u0003מעת לעת\u0004 למפרע \u0003שבנדה\u0004 — הריהי טומאה חמורה, והנדה אף \u0003עושה\u0004 (מטמאה) \u0003משכב ומושב\u0004 ששכבה או שישבה עליהם באותו זמן \u0003לטמא אדם\u0004 הנוגע בהם \u0003לטמא בגדים\u0004 שעליו.","ותוהים על כך: \u0003איני\u0004 \u0005[כן הוא],\u0006 \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 החכם \u0003אבימי מבי חוזאי, אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא ברייתא בידו],\u0006 ובה שנינו כי \u0003מעת לעת שבנדה\u0004 — דין \u0003משכבה ומושבה\u0004 \u0003כ\u0004דין \u0003מגעה.\u0004 ויש לדון: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה לומר: \u0003מה מגעה\u0004 של נדה בדבר (שנעשה \"ראשון לטומאה\") \u0003לא\u0004 עושה שיהא אותו דבר \u0003מטמא אדם,\u0004 אף שמטמא אוכלים, \u0003אף משכבה\u0004 או מושבה של הנדה במשך מעת לעת שקודם לראייתה, \u0003לא מטמא אדם\u0004 לטמא בגדים, ושלא כדעת זעירי!","\u0003אמר רבא: ותסברא\u0004 \u0005[ו\u0006כי יכול אתה לומר כן]? והרי \u0003קל וחומר הוא: ומה כלי חרס המוקף צמיד פתיל\u0004 (חתום במגופה על פיו), שהוא וכל דבר טהור שנמצא בתוכו \u0003ניצול\u0004 מלהיטמא \u0003באהל המת,\u0004 למרות שכל מה שבאוהל נטמא, ובכל זאת כלי חרס זה \u0003אינו ניצול\u0004 מלהיטמא \u0003ב\u0004טומאת \u0003מעת לעת שבנדה,\u0004 שאם הסיטה אותו בפרק זמן זה הריהו טמא. \u0003משכבות ומושבות, שאינן ניצולין באהל המת,\u0004 אלא טמאים בו — \u0003אינו דין שאין ניצולין במעת לעת שבנדה,\u0004 וכשיטת זעירי.","ומקשים: ובכל זאת, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אבימי מבי חוזאי מתניתא קאמר\u0004 \u0005[ברייתא אמר],\u0006 כדי להוכיח את דבריו! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 ופרש כך את דברי הברייתא: \u0003משכבה ומושבה\u0004"],["דינם \u0003כמגע\u0004 בנדה \u0003עצמה,\u0004 ולא ככלי שנגעה בו הנדה. וכך היא השוואה זו: \u0003מה מגע עצמה\u0004 של הנדה — \u0003מטמא אדם לטמא בגדים,\u0004 שאם נגע אדם בנדה, הריהו טמא לטמא בגדים שעליו, \u0003אף\u0004 דין \u0003משכבה ומושבה\u0004 — \u0003מטמא אדם לטמא בגדים\u0004 למפרע מעת לעת.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא,\u0004 ששנינו: האשה \u0003הרואה דם\u0004 — \u0003מטמאה\u0004 למפרע \u0003מעת לעת,\u0004 מחשש שמא ראתה קודם לכן. \u0003ומה היא מטמאה?\u0004 — \u0003משכבות ומושבות, אוכלין ומשקין, וכלי חרס\u0004 אף זה \u0003המוקף צמיד פתיל\u0004 אם הסיטתו. \u0003ו\u0004אולם אף שהיא מטמאה למפרע מעת לעת, \u0003אינה מקולקלת למנינה\u0004 (מחזור ספירת הימים), שאין אומרים מפני חשש זה שתתחיל למנות את ימי נידותה וזיבתה מאתמול אלא מיום שראתה בלבד. \u0003ואינה מטמאה את\u0004 ה\u0003בועלה\u0004 בתוך מעת לעת \u0003למפרע\u0004 בטומאת שבעה כשאר בועלי נדה, אף שהיא מטמאה משכב ומושב. \u0003ר' עקיבא אומר:\u0004 אף \u0003מטמא\u0004 ה\u0003את\u0004 ה\u0003בועלה.\u0004 \u0003ו\u0004אולם \u0003אינה מונה\u0004 שבעת ימי נדה \u0003אלא משעה שראתה\u0004 את הדם בפועל.","ואולם \u0003הרואה כתם,\u0004 כלומר, מצאה כתם של דם בבגדיה, ומסתבר שהוא דם נדה — הרי זו \u0003מטמאה למפרע\u0004 עד לשעת כיבוסו. \u0003ומה היא מטמאה?\u0004 — \u0003אוכלין ומשקין, משכבות ומושבות, וכלי חרס\u0004 אף שהוא \u0003מוקף צמיד פתיל\u0004 אם הסיטה אותו. \u0003ו\u0004הרואה כתם הריהי \u0003מקולקלת למנינה,\u0004 שהרי אין אנו יודעים מתי היה הדבר, \u0003ומטמאה את\u0004 הבועלה למפרע משעת כיבוס הבגד בטומאת שבעה, \u0003ואינה מונה\u0004 לימי נדתה \u0003אלא משעה שראתה.\u0004","\u0003ו\u0004דין אחד הוא לטומאת מעת לעת של \u0003זה\u0004 (הרואה דם) \u0003וזה\u0004 (הרואה כתם) שאת כל הטהרות שנגעו בהן בפרק זמן זה \u0003תולין\u0004 (מסתפקים בהם), ולכן \u0003לא אוכלין\u0004 אותם שמא טמאים הם, \u0003ו\u0004אולם גם \u0003לא שורפין\u0004 אותן (כשאר טהרות שנטמאו בוודאי), אלא ממתינים עד שיטמאו טומאה אחרת, או שיתקלקלו, ואז ישרפו אותם.","ושואלים: \u0003ורבא, אי שמיע ליה מתניתא\u0004 \u0005[אם נשמעה,\u0006 היתה ידועה \u0005לו הברייתא\u0006 הזו\u0005]\u0006 שממנה עולה כשיטתו — \u0003לימא מתניתא\u0004 \u0005[שיאמר\u0006 את דברי \u0005הברייתא]\u0006 כמו שהן וכהלכה פסוקה, בלא להזדקק לקל וחומר! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא שמיע ליה מתניתא\u0004 \u0005[לא נשמעה,\u0006 היתה ידועה \u0005לו הברייתא],\u0006 אם כן \u0003קל וחומר\u0004 זה שמטמאה דבר הניצול בצמיד פתיל \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006","ומשיבים: \u0003לעולם שמיע ליה מתניתא\u0004 \u0005[שמע את הברייתא\u0006 הזו\u0005],\u0006 \u0003ו\u0004אולם הוא לא השמיענו הלכה זו מן הברייתא כשלעצמה, כי \u0003אי ממתניתא\u0004 \u0005[אם מן הברייתא]\u0006 יילמד הדין, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שכוונת הברייתא היא שהרואה דם מטמאים משכבה או מושבה למפרע \u0003או אדם או בגדים\u0004 שנגעו בהם, \u0003אבל\u0004 שיטמאו למפרע אף \u0003אדם\u0004 לטמא \u0003בגדים\u0004 שעליו, אף שהבגדים לא נגעו בטומאה — \u0003לא.\u0004 \u0003משום הכי קאמר\u0004 \u0005[כך אמר]\u0006 רבא \u0003קל וחומר\u0004 זה מדין כלי חרס המוקף צמיד פתיל, ללמדנו שמטמאה אף אדם לטמא בגדים שעליו.","ועוד בענין טומאה למפרע, \u0003אמר רב הונא:\u0004 מה שאמרו שאשה שאין לה וסת מטמאה למפרע \u0003מעת לעת\u0004 או מפקידה לפקידה \u0003שבנדה\u0004 — הרי זה דווקא \u0003ל\u0004ענין \u0003קדש, אבל לא ל\u0004ענין \u0003תרומה,\u0004 שהתרומות שנגעה בהן בפרק זמן זה אינן טמאות. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שלענין זה חמור דין הקדשים מדין התרומה, אם כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 התנא אף חומרה זו \u0003גבי\u0004 \u0005[אצל,\u0006 יחד עם\u0005]\u0006 שאר ה\u0003מעלות\u0004 שיש בקודש על התרומה המנויות במסכת חגיגה! ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 התנא במסכת חגיגה את המעלות שיש לקודש על התרומה, לא שנה אלא \u0003היכא\u0004 \u0005[היכן,\u0006 בדבר\u0005]\u0006 \u0003דאית ליה דררא\u0004 \u0005[שיש לו צד]\u0006 של \u0003טומאה\u0004 מן התורה, \u0003אבל היכא דלית ליה דררא\u0004 \u0005[היכן שאין לו צד]\u0006 של \u0003טומאה\u0004 מן התורה, וכל עיקרו הריהו גזירת חכמים — \u0003לא קתני\u0004 \u0005[אין\u0006 התנא \u0005שונה].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על דברי רב הונא ממה ששנינו בברייתא שהובאה למעלה, בדין טומאת מעת לעת: \u0003מה היא,\u0004 האשה שראתה דם, \u0003מטמאה?\u0004 — \u0003אוכלין ומשקין.\u0004 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מתוך שלא חילק התנא, הכוונה היא לכל האוכלים והמשקים, \u0003בין\u0004 של \u0003קדש, בין\u0004 של \u0003תרומה,\u0004 והרי שאין הבחנה לענין זה בין קודש לתרומה, שלא כדברי רב הונא! ודוחים: \u0003לא,\u0004 כוונת הברייתא שמטמאה אוכלים ומשקים של \u0003קדש\u0004 ולא של תרומה.","ומביאים ראיה לענין זה של טומאת מעת לעת בתרומה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ממה ששנינו במשנה בסוף פרקנו בדין הנשים הכהנות שצריכות לבדוק עצמן אם הן טהורות כשבאות לאכול בתרומה, \u0003ר' יהודה אומר: אף בשעת עברתן\u0004 (פרישתן), בשעה שהן מסיימות \u0003מלאכול בתרומה\u0004 הריהן צריכות לבדוק עצמן. \u0003והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה\u0004 בהלכה זו של ר' יהודה, ונשאלה השאלה: מדוע צריכות הכהנות לבדוק עצמן לאחר שכבר אכלו מן התרומה, והרי \u0003מאי דהוה הוה\u0004 \u0005[מה שהיה היה],\u0006 ומה תועלת יש בבדיקה זו?","\u0003אמר רב חסדא: לא נצרכה\u0004 בדיקה זו \u0003אלא\u0004 כדי \u0003לתקן שירים\u0004 (שאריות התרומה) \u0003ש\u0004נגעה בהן באכילתה והן כעת \u0003בפניה\u0004 (לפניה). שאם תראה אחר כך דם — אין שאריות התרומה הללו טמאות למפרע כיון שבדקה לאחר שנגעה בהן, וראויות הן לאכילה. שאלמלא בדיקה זו שלאחר האכילה, היו נטמאות התרומות למפרע, ושלא כדברי רב הונא!","ומתרצים: \u0003רב הונא מתני\u0004 \u0005[היה שונה]\u0006 בהסבר שיטת ר' יהודה זו שמטרת הבדיקה שלאחר האכילה היא להביא \u0003לישרוף\u0004 את ה\u0003שירים\u0004 של התרומה \u0003ש\u0004היו \u0003בידיה\u0004 בסמוך לבדיקה. \u0003ש\u0004כן כאשר הכהנת האוכלת בתרומה \u0003בדקה עצמה\u0004 מיד לאחר האכילה, בתוך פרק זמן המוגדר \u0003כשיעור וסת,\u0004 ומצאה שהיא טמאה, ודאי הוא שאף בזמן שנגעה בתרומה היתה טמאה, ולכן יש לשרוף את התרומה כדין תרומה שנטמאה בוודאות. אבל לענין הכשר השיריים לאכילה, אכן הוא כדברי רב הונא שאינה מטמאה את התרומה למפרע מפני הספק אם לא בדקה.","ומביאים עוד ראיה לענין זה של טומאת מעת לעת בתרומה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע], ממה ששנינו \u0003מעשה\u0004 אירע באשה שלא ראתה דם במשך שלוש עונות רצופות (של מחזור הוסת), ולאחר מכן ראתה, \u0003ועשה\u0004 (ופסק הלכה למעשה) \u0003רבי כ\u0004שיטת \u0003ר' אליעזר\u0004 שבמקרה זה דייה שעתה, ומטמאה רק מכאן ואילך, ולא למפרע.","\u0003לאחר שנזכר\u0004 רבי שפסק זה אינו כשיטת חכמים החולקים על ר' אליעזר וסבורים שלא נאמר דין זה אלא בסמוך לזקנתה בלבד, ואילו שאר הנשים במקרה זה מטמאות למפרע, \u0003אמר: כדי\u0004 (כדאי, ראוי) \u0003הוא ר'\u0004 \u0003אליעזר לסמוך עליו\u0004"],["\u0003בשעת הדחק.\u0004 \u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 שאלנו\u0005]\u0006 \u0003בה\u0004 בברייתא זו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הלשון \u0003\"לאחר שנזכר\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא: \u0003לאחר שנזכר\u0004 רבי ש\u0003אין הלכה כר'\u0004 \u0003אליעזר אלא כרבנן\u0004 \u0005[כחכמים],\u0006 אם כן אף \u0003בשעת הדחק היכי עביד כותיה\u0004 \u0005[כיצד עשה כמותו],\u0006 והרי אין זה כהלכה?","\u0003אלא\u0004 האם \u0003(לאו\u0004 \u0005[לא]\u0006\u0003)\u0004 לומר שכיון ש\u0003לא איתמר הלכתא\u0004 \u0005[נאמרה,\u0006 נקבעה \u0005הלכה]\u0006 \u0003לא כמר\u0004 \u0005[כחכם זה]\u0006 \u0003ולא כמר\u0004 \u0005[כחכם זה],\u0006 \u0003וכיון שנזכר\u0004 רבי, שאף \u0003דלאו\u0004 \u0005[שלא]\u0006 חכם \u0003יחיד\u0004 הוא ש\u0003פליג עליה\u0004 \u0005[חולק עליו]\u0006 על ר' אליעזר, \u0003אלא רבים פליגי עליה\u0004 \u0005[חלוקים עליו],\u0006 והיה לכאורה מקום לפסוק כמותם, הוא פסק כר' אליעזר אף שהוא יחיד, שכן \u0003אמר: \"כדי\u0004 (כדאי) \u0003הוא ר'\u0004 \u0003אליעזר לסמוך עליו בשעת הדחק\".\u0004","ומעתה נדון בדבר, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שמחלוקת חכמים ור' אליעזר היא אף \u0003ל\u0004ענין טומאת ה\u0003תרומה\u0004 שנגעה בה אשה זו, \u0003היינו\u0004 \u0005[זהו]\u0006 שיש מקום לשאלה זו הלכה למעשה שנדרש לה רבי, משום \u0003דהואי\u0004 \u0005[שהיתה]\u0006 \u0003תרומה בימי רבי.\u0004 \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 ששאלה זו היתה \u0003ל\u0004ענין טומאת \u0003קדש,\u0004 הרי זה תמוה: וכי \u0003קדש בימי רבי\u0004 שחי שנים רבות לאחר חורבן בית המקדש \u0003מי הואי\u0004 \u0005[האם היה]?\u0006 אלא ודאי דין טומאת מעת לעת נוהג אף בתרומה, שלא כשיטת רב הונא!","ומשיבים: הלכה זו שפסק רבי עניינה בקודש ולא בתרומה, שאף בימיו של רבי היו שנהגו במאכלם דיני טהרה כבקודש, \u0003כ\u0004עדותו של \u0003עולא,\u0004 שכן \u0003אמר עולא: חבריא\u0004 \u0005[החברים,\u0006 תלמידי החכמים\u0005]\u0006 היו \u0003מדכן\u0004 \u0005[מטהרים]\u0006 יינם ושמנם בטהרת הקודש \u0003בגלילא\u0004 \u0005[בגליל].\u0006 הרי שאף שנים רבות אחר חורבן בית המקדש היו שנהגו לענין טומאה כקדשים במאכלם, \u0003הכא נמי\u0004 \u0005[כאן\u0006 מעשה זה \u0005גם כן]\u0006 שהיה \u0003בימי רבי\u0004 היה בנוהגים כן, ואין זה אם כן ראיה כנגד שיטת רב הונא.","ומביאים עוד ראיה בענין זה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ממה ששנינו: \u0003מעשה בשפחתו של רבן גמליאל שהיתה אופה ככרות\u0004 לחם \u0003של תרומה, ובין כל אחת ואחת\u0004 היתה \u0003מדיחה\u0004 (רוחצת) \u0003ידה במים\u0004 כדי להסיר מהן שאריות לכלוך \u0003ובודקת\u0004 את עצמה אם ראתה דם ונטמאה. \u0003ב\u0004זמן אפיית הכיכר ה\u0003אחרונה בדקה\u0004 עצמה \u0003ומצאה\u0004 שהיא \u0003טמאה, ובאת\u0004 (ובאה) \u0003ושאלה את רבן גמליאל\u0004 מה דין הככרות, \u0003ואמר לה: כולן טמאות.\u0004 לפי שהנדה מטמאה למפרע מעת לעת. \u0003אמרה לו: רבי, והלא בדיקה היתה לי בין כל אחת ואחת! אמר לה: אם כן, היא\u0004 הככר האחרונה \u0003טמאה וכולן\u0004 כל השאר \u0003טהורות.\u0004 שהיא מטמאה למפרע מפקידה לפקידה.","ומעתה יש לדון בדבר, \u0003קתני מיהת\u0004 \u0005[שנה על כל פנים]\u0006 בברייתא זו: \u0003ככרות של תרומה,\u0004 משמע איפוא שבכלל טומאה למפרע שגזרו חכמים אף התרומה, ולא רק הקודש, שלא כשיטת רב הונא! ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \"ככרות \u0003תרומה\"?\u0004 — הכוונה היא לככרות \u0003תרומת לחמי תודה\u0004 הבאות עם קרבן התודה וניתנות לכהן, שהן קודש ולא תרומה. ותוהים: הלא במעשה של שפחת רבן גמליאל מדובר במהלך האפיה, ו\u0003תרומת לחמי תודה,\u0004 כבר \u0003באפיה מאי בעיא\u0004 \u0005[מה\u0006 היא \u0005עושה],\u0006 שהרי בתחילה נאפים ארבעים לחמים (הבאים מארבעה סוגים), ורק אחר כך ניטלות מתוכם ארבע ככרות כתרומת לחמי תודה?","ומשיבים: מדובר כאן בכגון \u0003דאפרשינהו בלישייהו\u0004 \u0005[שהפריש אותם,\u0006 את תרומת לחמי התודה עוד \u0005ב\u0006זמן \u0005לישתם].\u0006 \u0003וכי הא\u0004 \u0005[וכמו זו]\u0006 ש\u0003אמר רב טובי בר רב קטינא: לחמי תודה שאפאן\u0004 לא ארבעים חלות כדינן, אלא \u0003ארבע חלות\u0004 — \u0003יצא\u0004 בהם. \u0003והוינן\u0004 \u0005[והיינו עסוקים,\u0006 ושאלנו\u0005]\u0006 \u0003בה\u0004 בהלכה זו: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיהיו \u0003ארבעים\u0004 חלות, שהם ארבעה סוגים (שלושה מיני מצה: חלות, רקיקין, ורבוכה, ועוד חלת חמץ) ובכל סוג עשר חלות! והשבנו על כך כי ארבעים שנאמרו הם \u0003למצוה\u0004 לכתחילה, אבל אם עשה ארבע, אחת מכל סוג — יצא.","וחזרנו ושאלנו על כך: \u0003והא בעינן אפרושי\u0004 \u0005[והרי צריך להפריש]\u0006 \u0003תרומה מינייהו\u0004 \u0005[מהם],\u0006 מן הלחמים הללו, שיש לתת אחד מכל עשרה לכהן! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהוא \u0003מפריש פרוסה מכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מארבעת הלחמים הללו, אולם בדין לחמי תודה \"והקריב ממנו \u0003אחד\u0004 מכל קרבן תרומה לה' לכהן... יהיה\" (ויקרא ז, יד) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ולשון \"אחד\" באה להורות שתהא זו חלה שלימה, \u0003שלא יטול פרוסה! ואמרינן\u0004 \u0005[ואמרנו]\u0006 בתשובה לדבר, שמדובר בכגון \u0003דאפרשינהו בלישייהו\u0004 \u0005[שהפריש אותם בלישתם],\u0006 כלומר, בשעת הלישה עשה חלה גדולה מכל אחד מארבעת הסוגים לעצמו, והפריש ממנה בזמן הלישה חלה קטנה כדי עשירית, והיא התרומה לכהן. \u0003הכא נמי\u0004 \u0005[כאן\u0006 במקרה זה שבא לפני רבי \u0005גם כן]\u0006 מדובר בכגון \u0003דאפרשינהו בלישייהו\u0004 \u0005[שהפריש אותם בלישתם],\u0006 ואין איפוא ראיה כנגד שיטת רב הונא שלא נאמרה טומאת מעת לעת בתרומה אלא בקודש בלבד.","ומציעים עוד ראיה בענין זה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ממה ששנינו: \u0003שוב\u0004 (ועוד) \u0003מעשה\u0004 שאירע \u0003בשפחה של רבן גמליאל שהיתה גפה\u0004 (סותמת במגופה) \u0003חביות של יין, ובין\u0004 סתימת \u0003כל אחת ואחת\u0004 מהחביות, היתה \u0003מדיחה\u0004 (שוטפת) את \u0003ידיה במים, ו\u0004לאחר מכן היתה \u0003בודקת\u0004 את עצמה אם ראתה דם. \u0003וב\u0004חבית ה\u0003אחרונה בדקה\u0004 את עצמה שוב, \u0003ומצאה\u0004 אז שהיא \u0003טמאה.\u0004 \u0003ובאת\u0004 (ובאה) \u0003ושאלה לרבן גמליאל\u0004 מה דין החביות הללו, \u0003ואמר לה: כולן טמאות.\u0004 שכן מטמאה היא למפרע מעת לעת. \u0003אמרה לו: והלא בדיקה היתה לי בין כל אחת ואחת! אמר לה: אם כן, היא,\u0004 החבית האחרונה — \u0003טמאה, וכולן,\u0004 כל החביות הקודמות — \u0003טהורות.\u0004","\u0003ולענייננו,\u0004 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שלא כשיטת רב הונא, שהלכה זו של טומאת מעת לעת נוהגת בין בקודש בין בתרומה, אפשר לומר ששני המקרים הללו בשפחתו של רבן גמליאל, בככרות הלחם ובחביות היין, שונים זה מזה. שכן \u0003חדא\u0004 \u0005[אחד]\u0006 של \u0003קדש\u0004 הוא, \u0003וחדא\u0004 \u0005[ואחד]\u0006 של \u0003תרומה היא.\u0004 ו\u0003היינו\u0004 \u0005[זהו]\u0006 ההסבר לכך \u0003דהדרה ושיילה\u0004 \u0005[\u0006\u0005ש\u0006השפחה \u0005חזרה ושאלה]\u0006 את רבן גמליאל אותה שאלה ששאלה כבר. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 כשיטת רב הונא שהלכה זו נוהגת רק בקודש ולא בתרומה, ולפיכך \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 שני המקרים הללו היו בשל \u0003קדש,\u0004 אם כן, \u0003למה לה למהדר ולשייליה\u0004 \u0005[לחזור ולשאול אותו]\u0006 את רבן גמליאל אותה שאלה, לאחר שכבר הורה לה בראשונה כיצד לנהוג. ומשיבים: בשני המקרים מדובר בשל קודש, אלא ש\u0003מעשה שהיה, בשתי שפחות היה.\u0004","ומביאים: \u0003לישנא אחרינא אמרי לה\u0004 \u0005[\u0006ב\u0005לשון,\u0006 נוסח \u0005אחר אומרים אותה]\u0006 את שיטת רב הונא. ובאופן זה, \u0003אמר רב הונא:\u0004 טומאה זו שגזרו חכמים למפרע \u0003מעת לעת שבנדה\u0004 — הריהי \u0003מטמאה בין לקדש ובין לתרומה.\u0004 \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח זאת? — \u0003מ\u0004תוך כך ש\u0003לא קתני לה\u0004 \u0005[לא שנה אותה]\u0006 התנא במשנה במסכת חגיגה שנוהגת טומאה זו רק בקודש ולא בתרומה \u0003גבי\u0004 \u0005[אצל]\u0006 שאר ה\u0003מעלות\u0004 שיש בקודש על תרומה, משמע שנוהגת היא בשניהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן\u0004 לרב הונא: \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 ה\u0003תנא\u0004 בדין טומאת מעת לעת כי נוהגת היא \u0003ל\u0004ענין \u0003קדש אבל לא ל\u0004ענין \u0003תרומה!\u0004","ואומרים: \u0003קבלה\u0004 את פירוש הברייתא שלהלן \u0003מיניה\u0004 \u0005[ממנו,\u0006 מרב נחמן\u0005]\u0006 \u0003רב שמואל בר רב יצחק,\u0004 והסביר כי כוונת הברייתא לומר שאף \u0003בחולין שנעשו על טהרת קדש\u0004 (שהתעסקו בהם תוך שמירתם מטומאה כמו בקדשים) גזרו חכמים שתהא נוהגת טומאה זו, \u0003ו\u0004אולם \u0003לא\u0004 גזרו כן גם \u0003בחולין שנעשו על טהרת תרומה,\u0004 אבל בתרומה עצמה ודאי נוהגת טומאה זו. ואין איפוא ראיה כנגד שיטת רב הונא.","ובענין הלכה זו שנוהגת טומאת למפרע מעת לעת אף בחולין שנעשו על טהרת הקודש, מציעים: \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במסכת חלה\u0005]:\u0006 \u0003נולד\u0004 (נגרם) \u0003לה\u0004 לעיסה \u0003ספק טומאה,\u0004 אם נגרם ספק זה \u0003עד שלא\u0004 (בטרם) \u0003גלגלה\u0004 אותה (לשה היטב את תערובת המים והקמח) — עדיין לא נגמרה מלאכתה לחיוב חלה, ולכן יכולה העיסה ש\u0003תעשה\u0004 מכאן והלאה אף \u0003בטומאה\u0004 ודאית, שכן משעה שנגרם לה ספק הטומאה שוב אין הכהן רשאי לאכול את החלה המופרשת ממנה. ואין הפסד לכהן בטומאתה הודאית. ואולם אם אירע ספק הטומאה לעיסת הבצק \u0003משגלגלה\u0004 אותה כבר האשה, והתחייבה העיסה בהפרשת חלה — \u0003תעשה בטהרה\u0004 בלבד.","ומסבירים: אם נגרם ספק הטומאה \u0003עד שלא גלגלה\u0004 — \u0003תעשה בטומאה,\u0004 מפני שעדיין \u0003חולין נינהו\u0004 \u0005[הם],\u0006 \u0003ומותר לגרום טומאה לחולין שבארץ ישראל.\u0004 ואולם אם נגרם ספק הטומאה \u0003משגלגלה\u0004 — \u0003תעשה\u0004 רק \u0003בטהרה,\u0004 כי \u0003חולין הטבולין,\u0004 כלומר, שהם כבר בגדר טבל שצריך \u0003ל\u0004הפריש מהם \u0003חלה\u0004 — \u0003כחלה דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 \u0003ו\u0004דין הוא ש\u0003אסור לגרום טומאה לחלה.\u0004","ועוד בדין זה \u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006"],["\u0003וחלתה\u0004 שהופרשה מעיסה זו הריהי \u0003תלויה\u0004 (מסופקת), ולכן \u0003לא אוכלין\u0004 אותה הכהנים, שמא טמאה היא, \u0003ו\u0004אולם גם \u0003לא שורפין\u0004 אותה שמא טהורה היא. \u0003באיזה ספק אמרו\u0004 הלכה זו שהיא תלויה? — \u0003בספק חלה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה בביטוי \u0003\"ספק חלה\"\u0004 שמשמעו ספק טומאה המיוחד דווקא לחלה?","\u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 בפירוש הדברים: ללמדנו \u0003שלא תאמר\u0004 שדווקא \u0003ב\u0004ספק טומאה המבוסס על \u0003הוכחות\u0004 (ראיות, כלומר, ספק מוצק שצדדיו שקולים) \u0003שנינו\u0004 הלכה זו, ו\u0003כמו\u0004 הספק הידוע ממקום אחר באדם שהלך באחד מ\u0003שני שבילין,\u0004 שבאחד מהם מצויה טומאה, והשני טהור, ואינו יודע באיזה שביל הלך. \u0003דהתם\u0004 \u0005[ש\u0006כן \u0005שם]\u0006 בספק כזה, \u0003חולין גרידא נמי מטמו\u0004 \u0005[חולין סתם\u0006 שנגע בהם גם כן נטמאים], ולא רק חלה.","\u0003אלא\u0004 אף \u0003ב\u0004\"ספק \u0003נשען\",\u0004 שהריהו מעין ספק רחוק, אף בו נוהגים בעיסת החלה כבדין ספק טמאה. ומהו ספק זה? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת זבים\u0005]\u0006 בדין שני בני אדם, האחד טמא טומאת \u0003זב ו\u0004השני \u0003טהור, שהיו פורקין\u0004 משא \u0003מן החמור או טוענין\u0004 (מעמיסים) משא על החמור. \u0003בזמן שמשאן\u0004 זה הריהו \u0003כבד\u0004 — \u0003טמא\u0004 האדם הטהור, שחוששים שמא מתוך כובד המשא נשען הזב על הטהור, ובכך נגרם שהאדם הטהור הסיטו או ניסט על ידו, ונטמא בכך. ואם היה \u0003משאן קל\u0004 — נשאר הטהור \u0003טהור.\u0004 \u0003וכולן\u0004 (בין במשא כבד, בין במשא קל) — הריהם נחשבים \u0003טהורין לבני הכנסת\u0004 האוכלים חוליהם בטהרה, שכן אין זה נחשב היסט גמור. \u0003ו\u0004אולם הם נחשבים \u0003טמאין ל\u0004ענין ה\u0003תרומה\u0004 מדברי סופרים, מחמת הספק.","ומקשים על כך: \u0003ו\u0004כי \u0003חולין הטבולין לחלה\u0004 — \u0003כחלה דמו\u0004 \u0005[נחשבים]\u0006 שייטמאו אף בספק רחוק כגון \"ספק נשען\", \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 במשנה במסכת טבול יום\u0005]:\u0006 ה\u0003אשה שהיא טבולת יום\u0004 (שנטמאה וטבלה לטהרתה, ואולם עדיין לא העריב שמשה, והריהי נחשבת כשניה לטומאה, ופוסלת במגעה את התרומה ואת החלה להיות שלישי לטומאה), \u0003לשה את העיסה, וקוצה\u0004 (חותכת) \u0003הימנה\u0004 (ממנה) חתיכת בצק לשם \u0003חלתה,\u0004 בלא שתקרא לה עדיין שם \"חלה\" (שהרי אם תחול עליה שם חלה, הריהי נטמאת על ידה), \u0003ומניחתה\u0004 לחתיכה זו \u0003בכפישה\u0004 (כלי נצרים) \u0003או באנחותא\u0004 (לוח עץ), שהם כלים שאינם מקבלים טומאה, \u0003ומקפת\u0004 (מקרבת) את חתיכת הבצק שקצתה מונחת בכלי לשאר עיסת הבצק, \u0003וקורא לה שם\u0004 \"חלה\".","והריהי מותרת לעשות כן — \u0003מפני שהוא,\u0004 בצק העיסה שנגעה בו האשה, נחשב בכך ל\u0003שלישי\u0004 לטומאה, \u0003ושלישי\u0004 לטומאה הריהו \u0003טהור בחולין.\u0004 וכיון שלא קראה לה שם חלה, עדיין היא חולין וטהורה. \u0003ו\u0004מעתה יש לדון בדבר, \u0003אי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003חולין הטבולין לחלה כחלה דמו\u0004 \u0005[נחשבים],\u0006 \u0003הא טמיתנהו\u0004 \u0005[הרי טימאה אותם]\u0006 האשה בנגיעתה, כדרך שמטמאה היא את החלה!","\u0003אמר אביי\u0004 בתשובה לכך: אין להשוות דין זה של טבולת יום לדין \"ספק נשען\", שכן כלל הוא, ש\u0003כל\u0004 דבר \u0003שודאי מטמא\u0004 אפילו \u0003חולין\u0004 — \u0003גזרו\u0004 חכמים \u0003על ספקו משום חולין הטבולין לחלה.\u0004 \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זה]\u0006 \u0003טבול יום, כיון\u0004 ש\u0003לא מטמא ודאי חולין\u0004 — \u0003לא גזרו עליו משום חולין הטבולין לחלה.\u0004","ומקשים על כך: \u0005[והרי]\u0006 טומאת \u0003מעת לעת\u0004 למפרע \u0003שבנדה,\u0004 שבה \u0003ודאי\u0004 (נדה ודאית) \u0003מטמא חולין, ו\u0004מכל מקום \u0003לא גזרו\u0004 חכמים \u0003על ספקה\u0004 שתטמא למפרע, ואפילו לא \u0003משום חולין הטבולין לחלה.\u0004","שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003קבלה\u0004 רב שמואל בר רב יצחק \u0003מיניה\u0004 \u0005[ממנו,\u0006 מרב נחמן\u0005],\u0006 ומכוחה הסביר \u0003רב שמואל בר רב יצחק\u0004 את פירוש הברייתא שדווקא \u0003בחולין שנעשו על טהרת קדש\u0004 גזרו על טומאה זו, \u0003ולא בחולין שנעשו על טהרת תרומה,\u0004 וחולין הטבולים לחלה הריהם כחולין שנעשו על טהרת תרומה!","ומשיבים: אין לדמות את הדברים, שכן \u0003התם\u0004 \u0005[שם,\u0006 בחולין שנעשו על טהרת תרומה\u0005]\u0006 \u0003לא פתיכא בהו\u0004 \u0005[מעורבת בהם]\u0006 \u0005תרומה, ולכן לא גזרו בהם חכמים טומאה זו.\u0006 \u0005ואילו\u0006 \u0003הכא\u0004 \u0005[כאן,\u0006 בחולין הטבולים לחלה\u0005]\u0006 הרי \u0003פתיכא בהו\u0004 \u0005[מעורבת בהם]\u0006 חלה העתידה להינטל מהם, שהיא כעין \u0003תרומה.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תשובה אחרת: \u0003הנח\u0004 מלהשוות לטומאת \u0003מעת לעת\u0004 שבנדה, שהיא \u0003דרבנן\u0004 \u0005[ש\u0006מדברי \u0005חכמים]\u0006 ולכן לא גזרו בה על ספיקו משום ודאו.","\u0003ר' אליעזר אומר:\u0004 שלא כנשים ששנינו שמטמאות למפרע, \u0003ארבע נשים\u0004 אלו שראו דם — \u0003דיין שעתן,\u0004 שמטמאות רק משעה שראו. ואלו הן: ה\u0003בתולה,\u0004 וה\u0003מעוברת,\u0004 וה\u0003מניקה, ו\u0004ה\u0003זקינה.\u0004 \u0003אמר\u0004 לו \u0003ר' יהושע: אני לא שמעתי\u0004 (קבלתי) מרבותי שנוהג דין זה, \u0003אלא\u0004 ב\u0003בתולה\u0004 בלבד."],["\u0003אבל הלכה כר'\u0004 \u0003אליעזר.\u0004","\u0003איזו\u0004 (מי) \u0003היא\u0004 המוגדרת כ\u0003בתולה\u0004 לענין זה — \u0003כל שלא ראתה דם\u0004 נדות \u0003מימיה, אף על פי שנשואה\u0004 וכבר ראתה דם מביאת נישואיה (דם בתולים). ומי היא המוגדרת כ\u0003מעוברת\u0004 לענין זה? — הרי זו \u0003מ\u0004השלב בזמן ההריון \u0003ש\u0004בו כבר \u0003יודע עוברה\u0004 (ניכר הריונה לכול). והמוגדרת כ\u0003מניקה\u0004 לענין זה — משנולד \u0003עד שתגמול\u0004 (תפריש מלהניק) \u0003את בנה.\u0004 ואם פסקה מלהניק, וכגון ש\u0003נתנה\u0004 את \u0003בנה למניקה\u0004 שתניקהו, והיא עצמה אינה מניקתו, או ש\u0003גמלתו\u0004 מיניקה בכלל, \u0003או\u0004 ש\u0003מת\u0004 הבן, בכל אלו אם ראתה דם, \u0003ר' מאיר אומר:\u0004 הריהי \u0003מטמאה מעת לעת\u0004 ומפקידה לפקידה. \u0003וחכמים אומרים:\u0004 אף במקרים אלו, אם ראתה — \u0003דיה שעתה\u0004 ואינה מטמאה אלא מזמן ראייתה.","\u0003איזוהי\u0004 (מיהי) המוגדרת כ\u0003זקנה\u0004 לענין זה שאם ראתה דיה שעתה? — \u0003כל\u0004 אשה \u0003שעברו עליה שלש עונות\u0004 (תקופות) ממוצעות של ווסת שהן כל אחת בת שלושים יום, בשלב החיים שב\u0003סמוך לזקנתה,\u0004 ולא ראתה במשך כל הזמן הזה. \u0003ר' אליעזר אומר: כל אשה,\u0004 ואפילו אין היא זקנה, \u0003שעברו עליה שלש עונות\u0004 ולא ראתה בהן דם — דינה הוא שאם ראתה לאחר מכן \u0003דיה שעתה.\u0004 \u0003ר'\u0004 \u0003יוסי אומר:\u0004 ה\u0003מעוברת\u0004 \u0003ו\u0004כן ה\u0003מניקה שעברו עליהן שלש עונות\u0004 ולא ראו בהן דם — \u0003דיין שעתן\u0004 אם ראו לאחר מכן.","\u0003ו\u0004עוד בדינן של ארבע נשים אלו, \u0003במה אמר\u0004 התנא שאם ראתה \u0003דיה שעתה?\u0004 דווקא \u0003בראייה ראשונה, אבל ב\u0004ראיה \u0003שניה\u0004 שראתה — הריהי כשאר הנשים ו\u0003מטמאה מעת לעת\u0004 או מפקידה לפקידה. \u0003ו\u0004אולם \u0003אם ראתה\u0004 את הראייה \u0003הראשונה\u0004 כתוצאה \u0003מ\u0004אירוע שב\u0003אונס\u0004 ולא כדרכה — \u0003אף\u0004 בראייה \u0003השניה\u0004 — \u0003דיה שעתה.\u0004","שנינו במשנתנו שאמר ר' אליעזר כי ארבע נשים הן שאם ראו דיין שעתן, ואילו ר' יהושע אמר לו שלא שמע שנוהג דין זה אלא בבתולה בלבד. ובעניין זה עוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר לו ר' אליעזר לר' יהושע\u0004 כתשובה לדבריו, \u0003אתה\u0004 אמנם \u0003לא שמעת\u0004 מרבותיך הלכה זו אלא לענין בתולה בלבד, ואולם \u0003אני שמעתי\u0004 מרבותי שנוהגת היא אף שלא בבתולה. ולא עוד אלא ש\u0003אתה לא שמעת אלא\u0004 בדינה של אשה \u0003אחת, ו\u0004אילו \u0003אני שמעתי\u0004 בדינן של נשים \u0003הרבה.\u0004","ואמר לו, כדרך הפתגם: \u0003אין\u0004 בית הדין \u0003אומרים למי שלא ראה את החדש\u0004 (מולד הירח) ש\u0003יבא ויעיד\u0004 על המולד, \u0003אלא\u0004 אומרים כן רק \u0003למי שראהו.\u0004 וכיון שאני שמעתי כן מרבותי לגבי ארבע הנשים הללו, אני רשאי להעיד, ואתה שלא שמעת אינך יכול להכחישני. ונמסר כי \u0003כל ימיו של ר'\u0004 \u0003אליעזר, היו עושין\u0004 (נוהגים) בהלכה זו \u0003כר' יהושע,\u0004 ואולם \u0003לאחר פטירתו של ר'\u0004 \u0003אליעזר, החזיר ר'\u0004 \u0003יהושע את הדבר ליושנו, כ\u0004פי קבלת","\u0003ר' אליעזר\u0004 מרבותיו, שבכל אלו ארבע הנשים שראו דם, דיין שעתן. ושואלים: \u0003בחייו\u0004 של ר' אליעזר \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 עשו כשיטתו, והרי סבר ר' יהושע שהוא צודק? ומשיבים: \u0003משום\u0004 ש\u0003ר' אליעזר שמותי הוא,\u0004 שהיה נוטה לדעת בית שמאי, \u0003וסבר\u0004 ר' יהושע: \u0003אי עבדינן כוותיה בחדא\u0004 \u0005[אם נעשה כמותו ב\u0006דבר \u0005אחד],\u0006 יביא הדבר שמתוך טעות אף \u0003עבדינן כוותיה באחרנייתא\u0004 \u0005[נעשה כמותו\u0006 אף בהלכות \u0005אחרות],\u0006 שבהן אין הלכה כמותו.","\u0003ומשום כבודו\u0004 של \u0003ר' אליעזר\u0004 שכך היא שיטתו, \u0003לא מצינן מחינן בהו\u0004 \u0005[אין אנו יכולים למחות בהם],\u0006 בנוהגים כך בשאר ההלכות. אבל \u0003לאחר פטירתו של ר'\u0004 \u0003אליעזר, דמצינו מחינן בהו\u0004 \u0005[שאנו יכולים למחות בהם]\u0006 לבל ינהגו כמותו בדברים אחרים, אפשר להתיר להם לנהוג כר' אליעזר בהלכה זו, ועמד ו\u0003החזיר את הדבר ליושנו,\u0004 כפי ששמע ר' אליעזר מרבותיו.","כיון שנאמרו אודות פסיקת הלכה כר' אליעזר מביאים עוד מה ש\u0003אמר רב יהודה, אמר שמואל\u0004 בענין זה: \u0003הלכה כר'\u0004 \u0003אליעזר בארבע\u0004 מחלוקות שנחלק עם חכמים. ואלו הן: \u0003חדא\u0004 \u0005[אחת],\u0006 זו \u0003דאמרן\u0004 \u0005[שאמרנו]\u0006 עתה, שנחלק עם ר' יהושע בענין ארבע נשים.","\u0003ואידך\u0004 \u0005[ו\u0006ההלכה האחרת], בדין האשה \u0003המקשה\u0004 ללדת, ואגב כך זב ממנה דם (\"דם קישוי\"), \u0003כמה\u0004 זמן \u0003תשפה\u0004 (תנוח, תפסיק מקישוי הלידה) לפני לידתה \u0003ותהא\u0004 נחשבת \u0003זבה\u0004 אם תראה דם, ולא נאמר שהדם הזה הוא מחמת הלידה הקרובה? — אם היא נחה מקישוי \u0003מעת לעת\u0004 (עשרים וארבע שעות), אלו \u0003דברי ר'\u0004 \u0003אליעזר.\u0004 ואילו ר' יהושע סבור שרק אם נחה מקישוי הלידה לילה שלם והיום שלאחריו, אז נחשבת היא כזבה. \u0003ו\u0004נפסקה \u0003הלכה כדבריו\u0004 של ר' אליעזר במחלוקתו זו.","\u0003ואידך\u0004 \u0005[ו\u0006ההלכה \u0005האחרת]\u0006 שבה נחלק ר' אליעזר והלכה כמותו, היא בדין \u0003הזב והזבה ש\u0004צריכים לספור שבעה ימים נקיים (בלא ראייה), וצריכים לבדוק בכל יום מהימים הללו שהם נקיים, ואלה \u0003בדקו עצמן\u0004 ב\u0003יום\u0004 ה\u0003ראשון\u0004 משבעת הימים הללו, לאחר שנפסק הזוב, \u0003ומצאו\u0004 שמקורם \u0003טהור\u0004 (נקי), וכן בדקו עצמם ב\u0003יום\u0004 ה\u0003שביעי ומצאו טהור, ו\u0004אולם ב\u0003שאר הימים\u0004 שבאמצע \u0003לא בדקו\u0004 עצמם, מה דינם? \u0003ר' אליעזר אומר:\u0004 כיון שבדקו עצמם ומצאו שהם נקיים, \u0003הרי אלו בחזקת טהרה\u0004 אף לימים שלא בדקו בהם. ואילו \u0003ר' יהושע אומר: אין\u0004 נחשב \u0003להן\u0004 למנין שבעת ימי נקיות \u0003אלא\u0004 שני ימים שבהם בדקו עצמם, \u0003יום הראשון ויום השביעי בלבד.\u0004 ועליהם להשלים חמישה ימים של נקיות, שבהם יבדקו עצמם בכל יום.","ואילו \u0003ר' עקיבא אומר\u0004 שבמקרה זה \u0003אין להם\u0004 לזב או לזבה \u0003אלא יום שביעי בלבד,\u0004 שהרי יש לחשוש שמא לאחר שבדקו עצמם ביום הראשון, חזרו וראו זיבה (והתבטלה בכך ספירת יום הראשון), ויש לספור שבעה ימים מחדש. \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 המכריעה להלכה בין שלש דעות אלו, ר' שמעון ור' יוסי אומרים: נראין דברי ר' \u0003אליעזר\u0004 יותר \u0003מדברי ר'\u0004 \u0003יהושע, ו\u0004אף כי נראים \u0003דברי ר'\u0004 \u0003עקיבא מדברי כולן, אבל הלכה כר'\u0004 \u0003אליעזר.\u0004","\u0003ואידך\u0004 \u0005[ו\u0006ההלכה \u0005האחרת]\u0006 שבה נחלק ר' אליעזר עם חכמים והלכה כמותו, היא זו \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה במסכת טהרות\u0005]\u0006 לענין טומאת החלקים השונים שבכלים: \u0003אחורי\u0004 (צידם החיצוני של) \u0003כלים שנטמאו ב\u0004נגיעת \u0003משקין\u0004 שנטמאו בשרץ באחוריהם, \u0003ר' אליעזר אומר:\u0004 אחוריים אלה טמאים לענין ש\u0003מטמאין את\u0004 כל \u0003המשקין\u0004 שיגעו בהם, \u0003ו\u0004אולם \u0003אין\u0004 הם \u0003פוסלין\u0004 מאכילה \u0003את האוכלין.\u0004 ומוסיפים בהסבר שיטת ר' אליעזר וביתר דיוק, מה שנאמר שאחוריים אלה \u0003מטמאין את המשקין,\u0004 הכוונה היא: \u0003ואפילו\u0004 היו משקים אלו של \u0003חולין.\u0004 \u0003ו\u0004מה שנאמר ש\u0003אין\u0004 אחוריים אלה \u0003פוסלין את האוכלין,\u0004 הכוונה היא: \u0003ואפילו\u0004 שהיו אוכלים אלה של \u0003תרומה.\u0004 ואילו \u0003ר' יהושע\u0004 נחלק עליו ו\u0003אומר\u0004 שאחוריים אלה \u0003מטמאין את\u0004 כל \u0003המשקין ו\u0004גם \u0003פוסלין את האוכלין\u0004 של תרומה.","ו\u0003אמר ר'\u0004 \u0003יהושע\u0004 בטעם שיטתו זו: \u0003קל וחומר\u0004 הוא מדינו של טבול יום (טמא שטבל לטהרתו, וממתין להערב שמש), ובאופן זה: \u0003ומה טבול יום ש\u0004אינו אלא שני לטומאה ו\u0003אין\u0004 הוא \u0003מטמא משקה חולין,\u0004 שהרי טומאת משקים משני לטומאה מדברי חכמים היא, ולא גזרו חכמים בטבול יום טומאה זו, ובכל זאת הוא \u0003פוסל\u0004 במגעו \u0003אוכלי\u0004 (מאכלי) \u0003תרומה,\u0004 שמשנגע בהם אסורים הם באכילה, \u0003אחורי כלים ש\u0004דינם חמור, שהרי \u0003מטמא\u0004 מקום האחוריים כל \u0003משקה\u0004 ואפילו הוא של \u0003חולין, אינו דין ש\u0004יהא גם \u0003פוסל אוכלי תרומה?\u0004","ושואלים: \u0003ור' אליעזר,\u0004 הסבור שאין אחורי הכלי פוסל את האוכלים, מה הוא משיב על קל וחומר זה? — לדעתו אין לדון בזה במידת קל וחומר, שכן טומאת \u0003אחורי כלים\u0004 הריהי \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003ו\u0004אילו טומאת \u0003טבול יום\u0004 הריהי \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ו\u0004כלל הוא כי על \u0003רבנן מדאורייתא לא עבדינן\u0004 \u0005[דברי חכמים מדברי תורה אין עושים]\u0006 \u0003קל וחומר.\u0004 שכן שונים הם בגדרי דיניהם. \u0003דמדאורייתא\u0004 \u0005[ש\u0006כן \u0005מן התורה]\u0006 \u0003אין אוכל מטמא כלי, ו\u0004כן \u0003אין משקה מטמא כלי,\u0004","\u0003ורבנן הוא דגזור\u0004 \u0005[וחכמים הם שגזרו]\u0006 טומאה על אחורי הכלים שנטמאו במגע משקים טמאים, וטעם ל\u0003גזרה\u0004 זו הוא \u0003משום\u0004 שמצאנו שמן התורה \u0003משקין\u0004 (הנוזלים) של \u0003זב וזבה\u0004 (רוקם ומי רגליהם) טמאים בגדר אב הטומאה, ומטמאים כלים, ולכן גזרו חכמים שגם שאר מיני משקים טמאים יטמאו כלים. ואולם \u0003משקין,\u0004 שהם \u0003עלולין\u0004 (מסוגלים ביותר) \u0003לקבל טומאה —\u0004 \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 שייטמאו, ואילו \u0003אוכלין\u0004 ש\u0003אין עלולין לקבל טומאה\u0004 בקלות (שהם צריכים הכשר לקבל טומאה) — \u0003לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים].\u0006","\u0003ומאי שנא\u0004 \u0005[ומה שונה,\u0006 במה מיוחד\u0005]\u0006 הוא דינם של \u0003אחורי כלים דנקט\u0004 \u0005[שקבע]\u0006 בהם שיטמאו, ולא נגזר כן בענין תוך הכלים, שאם יגעו משקים טמאים בתוכו יטמאו מדברי חכמים? \u0003משום דקילי\u0004 \u0005[ש\u0006אחורי כלים הם \u0005קלים יותר]\u0006 בדין טומאתם מטומאת החלקים שבתוך הכלים, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כלי שנטמא מאחוריו במשקין, אחוריו\u0004 — \u0003טמא,\u0004 אבל כל חלקי הכלי שב\u0003תוכו,\u0004 וכן \u0003אזנו\u0004 (המשמשת לאחיזה ולנשיאה), ו\u0003אוגנו\u0004 (שפת הכלי הבולטת), ו\u0003ידיו\u0004 (ידיתו) — \u0003טהורין\u0004 הם. ואולם אם \u0003נטמא תוכו\u0004 של הכלי — \u0003כולו טמא.\u0004 וכיון שדין תוכו חמור יותר, יודה ר' אליעזר שאף יפסול את האוכלים, ולכן דובר רק באחוריו. ואף במחלוקת חכמים זו נפסקה הלכה כר' אליעזר.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 \u0003שמואל\u0004 במה שאמר שבארבעת עניינים אלה הלכה כר' אליעזר? והרי \u0003בכולהו תנן הלכתא\u0004 \u0005[בכולם שנינו\u0006 במפורש שכך היא \u0005הלכה]!\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שלענין מחלוקת ר' אליעזר וחכמים בדין \u0003אחורי כלים קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמואל שהלכה כר' אליעזר, שכן דבר זה \u0003לא תנן\u0004 \u0005[שנינו]\u0006 במפורש, אם כן, אם רק זה הוא החידוש שבדבריו, \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 רק ש\u0003הלכה כר' אליעזר ב\u0004דין \u0003אחורי כלים! אלא הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 שמואל, שכלל הוא \u0003שאין למדין הלכה מפי תלמוד\u0004 (לימודם של התנאים במשנה ובברייתא) שאף שאמרו במפורש שכך היא ההלכה, מכל מקום אין למדים מהם הלכה למעשה, אלא אם כן נפסק הדבר על ידי האמוראים.","ושואלים: \u0003ותו ליכא\u0004 \u0005[ואין עוד]\u0006 עניינים, מלבד ארבעה אלו, שבהם ההלכה היא כר' אליעזר במחלוקותיו עם חכמים? \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 הלכה זו \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה במסכת יבמות], \u0003ר' אליעזר אומר:\u0004"],["במקרה בו שני אחים היו נשואים לשתי אחיות יתומות, האחת גדולה והאחת קטנה, ומת בעלה של הגדולה בלא בנים, והרי איפוא האחות הגדולה זקוקה ליבום על ידי בעל הקטנה, ואולם היא אחות אשתו, ואסורה עליו. כיצד יש לנהוג? \u0003מלמדין\u0004 בית דין \u0003את\u0004 האחות \u0003הקטנה\u0004 (שנישאה על ידי אחיה ואמה, שאין נישואיה חלים אלא מדברי חכמים), \u0003שתמאן בו\u0004 (שתכריז על אי הסכמתה לנישואיה אלה), ובכך נעקרים הנישואין לגמרי. ויוכל איפוא בעלה שהוא אחי הנפטר, לקיים באחות הגדולה מצות ייבום שהיא מן התורה. \u0003ואמר רב יהודה, אמר שמואל: הלכה כר' אליעזר\u0004 במחלוקת זו! ומשיבים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר שמואל\u0004 ש\u0003הלכה כר' אליעזר בארבעה\u0004 דברים שנחלק עם חכמים, הכוונה היתה לנושאים ש\u0003בסדר טהרות\u0004 בלבד, \u0003אבל ב\u0004מחלוקות ר' אליעזר וחכמים ב\u0003שאר\u0004 ה\u0003סדרים\u0004 שבמשנה, \u0003איכא טובא\u0004 \u0005[יש הרבה]\u0006 מהן שהלכה בהן כר' אליעזר.","ומוסיפים: \u0003והכי נמי מסתברא\u0004 \u0005[וכך גם כן מסתבר\u0006 לומר\u0005],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה]: חכמים סבורים שאם עשה אדם מספר עיסות בצק, שכל אחת מהן אין בה כשיעור המחייב הפרשת חלה, אפילו נגעו העיסות זו בזו — אינן מצטרפות, אלא אם נגיעתן כה הדוקה, שאם תופרדנה זו מזו, ייתלש חלק מהן. ורק אז (\"שישוכו\") מצטרפות העיסות לשיעור חלה. ואילו \u0003ר' אליעזר אומר: אף הרודה\u0004 (המוציא לחם מן התנור לאחר שנאפה) \u0003ונותן לסל\u0004 שבו יש ככרות לחם אחרים שעדיין לא הופרשה מהן חלה, ובין כולן יש שיעור המחייב בהפרשת חלה — \u0003הסל\u0004 שבו נמצאים ככרות הלחם הריהו \u0003מצרפן ל\u0004שיעור חיוב הפרשת \u0003חלה.\u0004 \u0003ואמר רב יהודה, אמר שמואל: הלכה כר' אליעזר.\u0004 הרי שבשאר סדרי המשנה ישנן מחלוקות נוספות, כדוגמת זו, שהלכה בהן כר' אליעזר, נוסף לארבע שבסדר טהרות. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא.","ושואלים: \u0003ומאי אולמיה דהאי מהאי\u0004 \u0005[ומה\u0006 הוא תוקפו של ענין \u0005זה\u0006 שבדין צירוף לשיעור חלה \u0005מ\u0006ענין \u0005זה\u0006 שבדין מיאון קטנה\u0005]?\u0006 מדוע יש להביא אסמכתא לקביעה שיש מחלוקות מחוץ לסדר טהרות שהלכה בהן כר' אליעזר, מכך שנפסקה הלכה כמוהו בדין חלה, ובמה הוא ראיה חזקה יותר ממה שנפסקה הלכה כר' אליעזר בדין מיאון קטנה? ומשיבים: מדין זה כשלעצמו של מיאון קטנה אין להוכיח שנפסקה הלכה כר' אליעזר במחלוקות נוספות מחוץ לסדר טהרות, שכן אפשר לומר שנפסקה הלכה כן במיאון קטנה \u0003משום דקאי\u0004 \u0005[שעומד]\u0006 התנא \u0003ר' אלעזר\u0004 בן שמוע \u0003כותיה\u0004 \u0005[כשיטתו]\u0006 של ר' אליעזר (בן הורקנוס),","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת יבמות\u0005]:\u0006 כשהיו לאח שמת שתי נשים שאינן אחיות, האחת גדולה והאחת קטנה, ובא היבם תחילה על הקטנה וחזר ובא על הגדולה, לדעת חכמים פסל בכך את הקטנה (שספק אם קניינה נחשב קנין), ונאסרו שתיהן עליו. ואילו \u0003ר' אלעזר אומר:\u0004 בית דין \u0003מלמדין את הקטנה שתמאן בו\u0004 ביבם, ויוכל לקיים מצות ייבום בגדולה. ולכן הראיה ממסכת חלה, שבה דעת ר' אליעזר היא דעת יחיד, היא ראיה חזקה יותר.","ושואלים על כך: \u0003ומי קאי\u0004 \u0005[והאם עומד]\u0006 ר' אלעזר בשיטתו של ר' אליעזר? \u0003והא\u0004 \u0005[והרי]\u0006 בתלמוד שם (יבמות קיא,ב) \u0003אצרכו מצרכינן להו\u0004 \u0005[מצריכים אנו אותן,\u0006 את שתי ההלכות הללו, של ר' אליעזר ושל ר' אלעזר, \u0003ו\u0004מראים ש\u0003לא דמיין להדדי\u0004 \u0005[דומות זו לזו]!\u0006 \u0003אלא\u0004 יש לומר הסבר אחר, שאין הראיה מדין זה של מיאון קטנה, שהלכה כר' אליעזר במחלוקות מחוץ לסדר טהרות תקיפה דיה, אלא מה שפסק שמואל בדין זה כר' אליעזר הוא \u0003משום דקאי\u0004 \u0005[שעומד]\u0006 \u0003ר' יהודה בן בבא כותיה\u0004 \u0005[כשיטתו]\u0006 של ר' אליעזר בענין זה,","\u0003דתניא\u0004 \u0005[ש\u0006כן שנויה ברייתא\u0005],\u0006 \u0003ר' יהודה בן בבא העיד\u0004 שכך נוהגים למעשה ב\u0003חמשה דברים\u0004 אלו: \u0003שממאנים את הקטנות,\u0004 שפעמים מורים בית דין לקטנות שתמאנה בנישואיהם, ותפקענה אותם בכך.","\u0003ושמשיאין\u0004 (מורים בית הדין להתיר נישואין) \u0003את האשה\u0004 שנעלם בעלה \u0003על פי\u0004 (על סמך) עדותו של \u0003עד אחד\u0004 בלבד שמעיד שמת בעלה, ואין צריכים לשם כך שני עדים כבשאר עדויות שבתורה. \u0003ו\u0004עוד העיד ר' יהודה בן בבא \u0003ש\u0004מעשה היה ו\u0003נסקל תרנגול בירושלים על שהרג את הנפש,\u0004 אף על פי שבתורה נאמר דין זה בפירוש רק בשור שהרג את הנפש, וללמדנו שאף שאר בעלי חיים שהרגו בכלל זה. \u0003ועל יין בן ארבעים יום שנתנסך על גבי המזבח\u0004 בבית המקדש, ואין אומרים בו שעדיין הוא בכלל \"יין מגתו\" שאינו ראוי לניסוך. \u0003ו\u0004עוד העיד \u0003על\u0004 קרבן ה\u0003תמיד של שחר ש\u0004אירע ו\u0003קרב בארבע שעות\u0004 (בשעה הרביעית ביום), אף על פי שכרגיל מקריבים אותו הרבה יותר מוקדם.","ויש לפרש בפשטות כי \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה בביטוי \u0003\"קטנות\"\u0004 בלשון רבים, שהזכיר ר' יהודה בן בבא? \u0003לאו\u0004 \u0005[האם לא]\u0006 לשני מקרים שבהם בית דין מלמד את הקטנה שתמאן לצורך קיום מצות ייבום, והם: \u0003חדא\u0004 \u0005[אחת],\u0006 זו שאמר \u0003ר' אלעזר, וחד\u0004 \u0005[ואחת],\u0006 זו שאמר \u0003ר' אליעזר.\u0004 הרי שר' יהודה בן בבא פוסק כר' אליעזר! ודוחים: \u0003לא, מאי\u0004 \u0005[מה]\u0006 הכוונה בביטוי \u0003\"קטנות\"\u0004 בלשון רבים? — \u0003קטנות דעלמא\u0004 \u0005[בכלל],\u0006 והכוונה רק לדין של ר' אליעזר בלבד.","ושואלים על כך: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאחז ר' יהודה בן בבא לשון רבים (\"קטנות\") כלשון כוללת, אף שכוונתו למקרה אחד, אם כן \u0003גבי\u0004 \u0005[אצל]\u0006 עדותו השניה ביחס ל\u0003אשה\u0004 הנישאת על פי עד אחד \u0003נמי\u0004 \u0005[גם כן],\u0006 במקום שישנה \"משיאין את האשה\" \u0003נתני [שישנה]\u0004 \"משיאין את ה\u0003נשים\",\u0004 \u0003ונימא\u0004 \u0005[ונאמר]\u0006 שהכוונה ל\u0003נשים דעלמא\u0004 \u0005[בכלל]!\u0006 \u0003אלא, מדהכא קתני\u0004 \u0005[מ\u0006תוך \u0005שכאן\u0006 בענין נישואין \u0005שנה]\u0006 \u0003\"אשה\",\u0004 בלשון יחיד, \u0003ו\u0004אילו \u0003הכא קתני\u0004 \u0005[כאן\u0006 בענין מיאון \u0005שנה]\u0006 \u0003\"קטנות\",\u0004 בלשון רבים, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003דוקא\u0004 (מדויק) \u0003קתני\u0004 \u0005[שנה],\u0006 וכוונתו לשתי קטנות, זו שדיבר עליה ר' אלעזר וזו שדיבר עליה ר' אליעזר, ומכאן שעומד ר' יהודה בן בבא כשיטת ר' אליעזר. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא.","\u0003ו\u0004בדומה לשמואל \u0003כן אמר\u0004 האמורא \u0003ר' אלעזר\u0004 בן פדת: \u0003הלכה כר' אליעזר\u0004 במחלוקותיו עם חכמים \u0003בארבעה\u0004 דברים. ושואלים: \u0003ותו ליכא\u0004 \u0005[ויותר\u0006 מארבעה דינים \u0005אין]\u0006 הלכה כר' אליעזר? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה במסכת יבמות\u0005]\u0006 ש\u0003ר' אליעזר אומר\u0004 ש\u0003מלמדין את הקטנה שתמאן בו\u0004 לצורך קיום מצות עשה של ייבום שמן התורה. \u0003ו\u0004אף בזו \u0003אמר ר'\u0004 \u0003אלעזר\u0004 בן פדת ש\u0003הלכה כר' אליעזר,\u0004 הרי שיש עוד דברים שבהם הלכה כר' אליעזר, לשיטת ר' אלעזר בן פדת! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר'\u0004 \u0003אלעזר\u0004 בן פדת ש\u0003הלכה כר' אליעזר בארבעה,\u0004 כוונתו היתה רק לדינים ש\u0003בסדר טהרות, אבל\u0004 \u0003בשאר סדרי\u0004 המשנה \u0003איכא\u0004 \u0005[יש]\u0006 עוד מחלוקות של ר' אליעזר וחכמים שבהן הלכה כמותו. \u0003ו\u0004אולם יש לדחות, שכן \u0003מי איכא\u0004 \u0005[האם\u0006 אכן \u0005יש]\u0006 עוד מחלוקות שבהן הלכה כמותו?","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה במסכת שביעית\u0005]\u0006 בדין קדושת שביעית בצמחים של בושם: \u0003הורד, והכופר, והלטום, והקטף\u0004 — אף שאינם מיועדים לאכילה וכל שימושם הוא הפרחים או השרף היוצא מהם, ולצורך הריח שבהם, \u0003יש להן\u0004 (נוהגים בהם) דיני \u0003שביעית,\u0004 שנחשבים כפירות, \u0003ו\u0004כן גם \u0003לדמיהן,\u0004 שאף למה שקנו בהם יש דין \u0003שביעית.\u0004 ומוסיפים שלפיכך \u0003יש להן ביעור,\u0004 כלומר, חלה עליהם חובת ביעור שיש בפירות שביעית, \u0003ו\u0004גם \u0003לדמיהן\u0004 שגם מה שקנו בהם גם כן חייב \u0003ביעור.\u0004 ואילו ר' שמעון סבור הוא שאין הצמח הנקטף אלא לשם פרחיו או השרף הריחני שבו, דוגמת צמחי בושם אלה, נחשב כפרי, ואין חלים עליו דיני השביעית כפירות. \u0003ואמר\u0004 על כך \u0003ר' פדת\u0004 בנו של ר' אלעזר בן פדת: \u0003מאן תנא\u0004 \u0005[מיהו\u0006 החכם ש\u0005שנה\u0006 במשנה\u0005]\u0006 ש\u0003קטפא פירא\u0004 \u0005[קטף\u0006 נחשב כ\u0005פרי]\u0006 אף שהוא רק שרף היוצא מן העץ? — \u0003ר' אליעזר\u0004 הוא.","\u0003ואמר ר'\u0004 \u0003זירא\u0004 לר' פדת בנו של ר' אלעזר בן פדת: \u0003חזי\u0004 \u0005[ראה,\u0006 שים לב\u0005]\u0006 למשמעות ההלכתית הנובעת מתוך דבריך אלו, \u0003דמינך ומאבוך קשריתו קטפא לעלמא\u0004 \u0005[ש\u0006כן \u0005ממך,\u0006 מתוך דבריך אלו, \u0005ומ\u0006תוך דברי \u0005אביך, הרי אתם מתירים\u0006 בשביעית את ה\u0005קטף לכל]!\u0006 שהרי \u0003את אמרת מאן תנא קטפא פירא\u0004 \u0005[אתה אומר\u0006 ש\u0005מיהו\u0006 החכם ש\u0005שנה\u0006 ש\u0005קטף\u0006 הוא \u0005פרי],\u0006 ואסור בכל איסורי שביעית — \u0003ר' אליעזר, ואבוך\u0004 \u0005[ואביך]\u0006 \u0003אמר\u0004 ש\u0003הלכה כר' אליעזר בארבעה\u0004 דברים בלבד. ולפי זה אף כאן אין הלכה כמותו, ונמצא שבכך אתה מתיר את הקטף בשביעית.","\u0003ו\u0004נלמד מכאן לענייננו, ש\u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לתירוץ זה שמה שאמרו הלכה כר' אליעזר בארבעה דברים הרי זה בסדר טהרות בלבד, אבל לא בשאר סדרים, \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 ר' פדת לר' זירא באותו האופן: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר אבא\u0004 ר' אלעזר בן פדת ש\u0003הלכה כר' אליעזר בארבעה\u0004 דברים בלבד — הרי זה \u0003בסדר טהרות, אבל בשאר סדרי\u0004 המשנה — \u0003איכא\u0004 \u0005[יש]\u0006 עוד מחלוקות שהלכה כמותו. ומתוך שלא השיב לו כן ר' פדת לר' זירא, הגם שידע מה היתה כוונת אביו, נסיק שכוונת דברי ר' אלעזר היא שהלכה כר' אליעזר בכל ששה סדרי המשנה.","ושואלים: \u0003אלא\u0004 מעתה, שנדחה ההסבר שהצענו בדברי ר' אלעזר, אם כן שוב \u0003קשיא ההיא\u0004 \u0005[קשה אותה]\u0006 שאלה ששאלנו, שהרי יש עוד ענין (בדין מיאון הקטנה) שבו פסק ר' אלעזר כדעת ר' אליעזר! ומשיבים: בענין זה של מיאון פסק כן האמורא ר' אלעזר בן פדת \u0003משום דקאי\u0004 \u0005[שעומד]\u0006 התנא \u0003ר' אלעזר\u0004 בן שמוע \u0003כותיה\u0004 \u0005[כמותו,\u0006 כשיטת ר' אליעזר\u0005].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת יבמות\u0005],\u0006 במקרה שבו היו לאח שמת שתי נשים, האחת גדולה והאחת קטנה, ובא היבם תחילה על הקטנה וחזר ובא על הגדולה, שלדעת חכמים פסל את הקטנה, ונאסרו שתיהן עליו, ואילו \u0003ר' אלעזר אומר\u0004 כי במקרה זה \u0003מלמדים את הקטנה שתמאן בו,\u0004 וכדברי ר' אליעזר.","ושואלים: \u0003ומי קאי\u0004 \u0005[והאם\u0006 אכן \u0005עומד]\u0006 ר' אלעזר בשיטת ר' אליעזר? \u0003והא\u0004 \u0005[והרי]\u0006 בתלמוד שם (יבמות קיא,ב) \u0003אצרוכי מצרכינן להו\u0004 \u0005[מצריכים אנו אותן],\u0006 את שתי ההלכות הללו של ר' אליעזר ושל ר' אלעזר, \u0003ו\u0004מראים ש\u0003לא דמיין להדדי\u0004 \u0005[לא דומות\u0006 הן \u0005זו לזו]!\u0006 \u0003אלא\u0004 יש לומר \u0003משום דקאי\u0004 \u0005[שעומד]\u0006 \u0003ר' יהודה בן בבא כוותיה\u0004 \u0005[כמותו,\u0006 כשיטתו\u0005],\u0006 שהעיד ר' יהודה בן בבא שבית דין ממאנים את הקטנה.","ושואלים עוד: \u0003ותו ליכא\u0004 \u0005[ועוד\u0006 עניינים שבהם הלכה כר' אליעזר \u0005אין],\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שנחלקו חכמים במקומה של אמירת ההבדלה בתפילת ערבית במוצאי שבת, שלדעת התנא הראשון אומרים אותה בברכת \"חונן הדעת\", ו\u0003ר' עקיבא אומר: אומרה\u0004 להבדלה כ\u0003ברכה רביעית בפני עצמה.\u0004 ואילו \u0003ר' אליעזר אומר: אומרה ב\u0004ברכת ה\u0003הודאה\u0004 (\"מודים\"). \u0003ואמר\u0004 על כך האמורא \u0003ר' אלעזר\u0004 בן פדת: \u0003הלכה\u0004 בדין זה \u0003כר' אליעזר.\u0004 הרי שלשיטת ר' אלעזר יש עוד מקום שנחלק ר' אליעזר עם חכמים והלכה כמותו!","\u0003אמר ר'\u0004 \u0003אבא: ההוא\u0004 \u0005[אותו]\u0006 דין ש\u0003אומר\u0004 ר' אליעזר במשנה זו, לא בשם עצמו הוא אלא \u0003משום\u0004 (בשם) ר' חנינא בן גמליאל. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדין זה של אמירת ההבדלה: ר' עקיבא אומר: אומרה ברכה רביעית בפני עצמה, ר' \u0003חנינא בן גמליאל אומר: אומרה בהודאה,\u0004 ולפיכך לא כר' אליעזר פסק ר' אלעזר בן פדת אלא כר' חנינא בן גמליאל."],["ודוחים תירוץ זה: \u0003והא\u0004 \u0005[והרי]\u0006 ר' אליעזר הריהו \u0003קשיש מיניה\u0004 \u0005[זקן ממנו]\u0006 מר' חנינא בן גמליאל \u0003טובא\u0004 \u0005[הרבה],\u0006 ואין לומר איפוא שדברי ר' אליעזר שבמשנה הם משם ר' חנינא בן גמליאל! \u0003אלא\u0004 יש לתרץ באופן שונה: מה שפסק ר' אלעזר בן פדת בדין זה כר' אליעזר, אינו אלא \u0003משום דקאי\u0004 \u0005[שעומד]\u0006 \u0003ר' חנינא בן גמליאל בשיטתיה\u0004 \u0005[בשיטתו]\u0006 זו של ר' אליעזר.","ושואלים על כך: \u0003ומי קאי\u0004 \u0005[והאם\u0006 אכן \u0005עומד]\u0006 ר' חנינא בן גמליאל בשיטתו זו של ר' אליעזר? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בסדר התפילות והוידויים הנאמרים ביום הכיפורים: \u0003אור\u0004 (ליל) \u0003יום הכפורים\u0004 בתפילת ערבית — \u0003מתפלל שבע\u0004 ברכות בתפילת עמידה, \u0003ומתודה\u0004 (אומר סדר הוידוי) לאחריהן. בתפילת \u0003שחרית\u0004 — \u0003מתפלל שבע\u0004 ברכות, \u0003ומתודה\u0004 שוב. בתפילת \u0003מוסף\u0004 — \u0003מתפלל שבע, ומתודה.\u0004 בתפילת \u0003מנחה\u0004 — \u0003מתפלל שבע, ומתודה.\u0004 \u0003וב\u0004תפילת \u0003נעילה\u0004 — \u0003מתפלל שבע, ומתודה.\u0004 \u0003ב\u0004תפילת \u0003ערבית\u0004 של מוצאי יום הכיפורים — \u0003מתפלל שבע\u0004 ברכות שיש בהן \u0003מעין שמנה עשרה\u0004 הברכות שבתפילת עמידה של חול.","\u0003ר' חנינא בן גמליאל משום\u0004 (בשם) \u0003אבותיו אומר:\u0004 בתפילת ערבית של מוצאי יום הכיפורים \u0003מתפלל שמנה עשרה\u0004 ברכות שלמות, \u0003מפני שצריך לומר הבדלה ב\u0004ברכת \u0003\"חונן הדעת\".\u0004 משמע איפוא שר' חנינא בן גמליאל סבור שמקום אמירת ההבדלה הוא ב\"חונן הדעת\", ולא ב\"מודים\" כשיטת ר' אליעזר! \u0003אמר רב נחמן בר יצחק\u0004 בתשובה לכך: \u0003איהו\u0004 \u0005[הוא]\u0006 ר' חנינא בן גמליאל \u0003אמר\u0004 שצריך לומר הבדלה ב\"חונן הדעת\" \u0003משום\u0004 (בשם) \u0003אבותיו, ו\u0004אולם \u0003ליה\u0004 \u0005[לו]\u0006 עצמו \u0003לא סבירא ליה\u0004 \u0005[מסתבר לו]\u0006 לומר כן, ולדעתו יש לומר הבדלה ב\"מודים\".","לעיל שנינו שאמר ר' זירא שדעת ר' פדת בן ר' אליעזר בן פדת שההלכה שקטף דינו בשביעית כפרי שיטת ר' אליעזר היא, ומשמע שדעת ר' זירא עצמו אינה כן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: ואת לא תסברא\u0004 \u0005[ואתה אינך סבור]\u0006 \u0003דמאן תנא קטפא פירא\u0004 \u0005[שמי\u0006 ש\u0005שנה\u0006 ש\u0005קטף\u0006 הוא \u0005פרי]\u0006 \u0003ר' אליעזר הוא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה במסכת ערלה\u0005],\u0006 \u0003ר' אליעזר אומר: המעמיד\u0004 גבינה \u0003בשרף ערלה\u0004 — \u0003אסור\u0004 מפני שהשרף הריהו כפרי האילן, ובכלל איסור ערלה הוא. הרי שדעת ר' אליעזר שהשרף אף הוא כפרי!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כדברי \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' אליעזר, שכן יש לומר ש\u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[נחלקו חכמים עליו]\u0006 על \u0003ר' אליעזר\u0004 ודעתם שהשרף אינו כפרי \u0003אלא\u0004 דווקא \u0003בקטפא דגווזא\u0004 \u0005[בשרף הענף,\u0006 העץ] עצמו, \u0003אבל בקטפא דפירא\u0004 \u0005[בשרף הפרי]\u0006 — \u0003מודו ליה\u0004 \u0005[מודים לו]\u0006 שהוא נחשב כפרי. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה שם\u0005],\u0006 \u0003אמר ר'\u0004 \u0003יהושע: שמעתי\u0004 מרבותי \u0003בפירוש ש\u0004כך היא ההלכה בדין הערלה כי \u0003המעמיד\u0004 גבינה \u0003בשרף העלין\u0004 או \u0003בשרף העיקרין\u0004 (השורשים) של עץ האסור בערלה — \u0003מותר,\u0004 ואין בו איסור ערלה, אבל המעמיד \u0003בשרף הפגין\u0004 (תאנים שלא בשלו עדיין כל צורכן) — \u0003אסור, מפני שהוא\u0004 נחשב \u0003פרי.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003כי פליגי רבנן עליה\u0004 \u0005[כאשר נחלקו חכמים עליו]\u0006 על \u0003ר' אליעזר\u0004 ואמרו שאין שרף העץ נחשב כפריו — הרי זה דווקא \u0003באילן העושה פירות, אבל באילן שאינו עושה פירות\u0004 — \u0003מודו\u0004 \u0005[מודים]\u0006 חכמים ש\u0003קטפו\u0004 (שרפו) \u0003זהו פריו.\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת שביעית\u0005],\u0006 \u0003ר' שמעון אומר: אין לקטף\u0004 דיני \u0003שביעית,\u0004 משום שאינו נחשב פרי. \u0003וחכמים אומרים: יש לקטף\u0004 דיני \u0003שביעית, מפני שקטפו\u0004 של עץ בושם \u0003זהו פריו.\u0004","ויש לברר, \u0003מאן\u0004 \u0005[מיהם]\u0006 \u0003חכמים\u0004 אלה? \u0003לאו רבנן דפליגי עליה\u0004 \u0005[האם אין\u0006 אלה \u0005חכמים החולקים עליו]\u0006 על \u0003ר' אליעזר\u0004 וסבורים כי שרף העץ אינו נחשב כפריו, הרי שבעץ שאינו עושה פרי נחשב השרף לפריו, וחלים עליו דיני שביעית! \u0003אמר ליה ההוא סבא\u0004 \u0005[לו זקן אחד]:\u0006 אין זו ראייה, שכן \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר'\u0004 \u0003יוחנן: מאן\u0004 \u0005[מיהם]\u0006 \u0003חכמים\u0004 אלה החולקים על ר' שמעון במשנה זו שבמסכת שביעית? — \u0003ר' אליעזר\u0004 הוא, ש\u0003אמר: קטפו זהו פריו.\u0004","ושואלים על ר' יוחנן: \u0003אי\u0004 \u0005[אם]\u0006 דברי חכמים שבמשנה זו הם דברי \u0003ר' אליעזר, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע שנינו במשנה זו דווקא\u0005]\u0006 ב\u0003אילן שאינו עושה פרי,\u0004 והרי לשיטת ר' אליעזר \u0003אפילו\u0004 ב\u0003אילן העושה פרי\u0004 — \u0003קטפו זהו פריו!\u0004 ומשיבים: \u0003לדבריהם דרבנן קאמר להו\u0004 \u0005[של חכמים אמר להם],\u0006 וכך צריך להבין את דבריו: \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 — \u0003אפילו אילן העו‍שה פירות נמי\u0004 \u0005[גם כן]\u0006 \u0003קטפו זהו פריו,\u0004 ואולם \u0003לדידכו\u0004 \u0005[לשיטתכם]\u0006 — \u0003אודו\u0004 \u0005[הודו]\u0006 \u0003לי מיהת\u0004 \u0005[לפחות]\u0006 \u0003באילן שאינו עושה פירות\u0004 ש\u0003קטפו זהו פריו.\u0004 \u0003ורבנן אמרי ליה\u0004 \u0005[וחכמים אומרים לו]\u0006 ש\u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 בדינו עץ פרי מעץ שאינו עץ פרי, ובשניהם אין השרף נחשב כפרי.","ושבים לדון במה ששנינו במשנתנו: \u0003איזו היא בתולה\u0004 שאם ראתה דם דיה שעתה — \u0003כל שלא ראתה\u0004 דם מימיה. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מי שלא ראתה דם מימיה, אם \u0003נשאת וראתה\u0004 לראשונה \u0003דם מחמת\u0004 ביאת ה\u0003נישואין\u0004 שהוא דם בתולים. וכן מי ש\u0003ילדה\u0004 ולד \u0003וראתה\u0004 לראשונה \u0003דם מחמת לידה, עדיין אני קורא לה \"בתולה\"\u0004 לענין שבמשנתנו, שאם תראה דם נידות דייה שעתה. והטעם שאף אלו בכלל בתולה: \u0003שהרי \"בתולה\" שאמרו\u0004 במשנתנו — הכוונה היא ל\u0003בתולת דמים\u0004 (שלא ראתה עד כה דם נדות, אף שנבעלה כבר), \u0003ולא\u0004 ל\u0003בתולת בתולים\u0004 (שלא נבעלה עדיין).","ומקשים: \u0003איני\u0004 \u0005[כך הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב כהנא, תנא\u0004 \u0005[שנה\u0006 החכם\u0005],\u0006 \u0003שלש בתולות הן:\u0004 באדם — \u0003בתולת אדם,\u0004 ובעולם — \u0003בתולת קרקע,\u0004 ובצומח — \u0003בתולת שקמה.\u0004 ומפרטים: מי היא הנקראת \u0003בתולת אדם\u0004 — האשה \u0003כל זמן שלא נבעלה,\u0004 ויש \u0003נפקא מינה\u0004 \u0005[תוצאה\u0006 להלכה ממנה, מהגדרה זו\u0005]\u0006 \u0003ל\u0004דינו של \u0003כהן גדול\u0004 המצווה לשאת בתולה דווקא, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003ל\u0004עניין סכום \u0003כתובתה\u0004 שהוא \u0003מאתים\u0004 זוז.","ומי היא הנקראת \u0003בתולת קרקע?\u0004 — \u0003כל זמן שלא נעבדה\u0004 בעבודה חקלאית. ויש \u0003נפקא מינה\u0004 \u0005[תוצאה\u0006 להלכה ממנה, מהגדרה זו\u0005]\u0006 \u0003ל\u0004ענין \u0003נחל איתן\u0004 בו עורפים את העגלה, ככפרה על הרוג שנמצא ואין יודעים מי הרגו. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003ל\u0004ענין \u0003מקח וממכר\u0004 שזו ההגדרה התופסת לעניין מכירה וקניה של \"קרקע בתולה\".","ומי היא הנקראת \u0003בתולת שקמה?\u0004 — \u0003כל זמן שלא נקצצה,\u0004 ויש \u0003נפקא מינה\u0004 \u0005[תוצאה\u0006 להלכה ממנה, מהגדרה זו\u0005]\u0006 \u0003ל\u0004ענין \u0003מקח וממכר,\u0004 שזו ההגדרה התופסת לעניין מכירה וקניה של \"בתולת השקמה\". \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003ל\u0004ענין \u0003מקצצה\u0004 \u0005[קציצתה]\u0006 \u0003ב\u0004שנה ה\u0003שביעית\u0004 (שמיטה). \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה במסכת שביעית\u0005]:\u0006 \u0003אין קוצצין בתולת שקמה בשביעית, מפני שהיא\u0004 נקראת \u0003עבודה\u0004 האסורה בשביעית. \u0003ו\u0004מעתה יש לשאול: \u0003אם איתא\u0004 \u0005[יש]\u0006 מקום להלכה זו ששנינו, שאשה הרואה דם מביאת נישואין או כתוצאה מלידה, נקראת \"בתולת דמים\", \u0003ליתני נמי הא\u0004 \u0005[שישנה גם כן\u0006 את \u0005זו\u0006 בנוסף לשלש המנויות\u0005]!\u0006","\u0003אמר רב נחמן בר יצחק: כי קתני\u0004 \u0005[כאשר שנה]\u0006 התנא שלוש בתולות אלה, לא שנה אלא \u0003מידי דלית ליה\u0004 \u0005[דבר שאין לו]\u0006 \u0003שם לווי\u0004 (לוואי), כלומר, \"בתולה\" באדם, \"בתולה\" בקרקע, ו\"בתולה\" בשקמה, \u0003אבל מידי דאית ליה\u0004 \u0005[דבר שיש לו]\u0006 \u0003שם לווי\u0004 כמו \"בתולת דמים\" — \u0003לא קתני\u0004 \u0005[אינו שונה].\u0006 \u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר\u0004 הסבר אחר: \u0003כי קתני\u0004 \u0005[כאשר שנה],\u0006 הרי שנה \u0003מידי דתלי\u0004 \u0005[דבר שתלוי]\u0006 \u0003במעשה\u0004 שטרם נעשה, ולכשייעשה הריהו מפסיק את שם ה\"בתולה\", שבתולת אדם שמפסיקה להיקרא כן כשהיא נבעלת, וכן בתולת הקרקע משנעבדת ובתולת השקמה משנקצצת, אבל \u0003מידי\u0004 \u0005[דבר]\u0006 ש\u0003לא תלי\u0004 \u0005[תלוי]\u0006 \u0003במעשה,\u0004 כגון ראייה ראשונה של דם נדה, הבא מעצמה — \u0003לא קתני\u0004 \u0005[אינו שונה].\u0006","\u0003ר' חנינא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר\u0004 הסבר אחר: \u0003כי קתני\u0004 \u0005[כאשר שנה],\u0006 הרי שנה דווקא \u0003מידי\u0004 \u0005[דבר]\u0006 ש\u0003לא הדר\u0004 \u0005[חוזר]\u0006 שוב \u0003לברייתו,\u0004 שמכאן והלאה נשאר לעולם באותה הגדרה, וכגון בתולה באדם, שמשעה שנבעלה שוב אינה נקראת \"בתולה\" לעולם. אבל \u0003מידי דהדר\u0004 \u0005[דבר שחוזר]\u0006 \u0003לברייתו לא קתני\u0004 \u0005[אינו שונה],\u0006 ובתולת דמים אף משרואה דם נדות, עתידה היא לשוב לאותו מצב לכשתזקין ולא תראה שוב דם נדות. ו\u0003רבינא אמר\u0004 תירוץ אחר: \u0003כי קתני\u0004 \u0005[כאשר שנה],\u0006 הרי שנה דווקא \u0003מידי דקפיד עליה זבינא\u0004 \u0005[דבר שמקפיד עליו הקונה],\u0006 שיהיה כך ולא אחר, וכגון המקדש אשה בידיעה שהיא בתולה ומקפיד על כך, אבל ב\u0003מידי דלא קפיד עליה זבינא\u0004 \u0005[דבר שאין מקפיד עליו הקונה],\u0006 וכגון דמים באשה, שאין בדבר הקפדה אצל הבריות, \u0003לא קתני\u0004 \u0005[אינו שונה].\u0006","ושואלים על הסבר זה של רבינא: \u0003ולא קפדי\u0004 \u0005[ואין\u0006 בני אדם מקפידים] בענין הזה אם ראתה דם או לא? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' חייא אומר: כשם שהשאור\u0004 (הבצק החמוץ הניתן בעיסה) \u0003יפה\u0004 (מועיל) \u0003לעיסה\u0004 להתפחה, \u0003כך\u0004 הם ה\u0003דמים יפין\u0004 (מועילים) \u0003לאשה.\u0004 ובוודאי שחשוב לבעל, שאשתו תראה דמי נדות! \u0003ותניא\u0004 \u0005[ושנויה\u0006 עוד ברייתא\u0005]\u0006 \u0003משום\u0004 (בשם) \u0003ר' מאיר\u0004 בענין זה של התועלת שבאשה הרואה דמי נדות: \u0003כל אשה שדמיה מרובין\u0004 — \u0003בניה מרובין! אלא\u0004 כך צריך לומר בתירוצו של רבינא, \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 לא שנה אלא \u0003מידי דקפיץ עליה זבינא\u0004 \u0005[דבר שקופצים עליו הקונים],\u0006 אבל \u0003מידי דלא קפיץ עליה זבינא, לא קתני\u0004 \u0005[דבר שאין קופצים עליו הקונים, אינו שונה],\u0006 ו\"בתולת דמים\", כלומר, מי שלא ראתה עדיין דם נדות, אינה בגדר דבר שקופצים עליו.","ועוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזוהי\u0004 קרקע הנקראת \u0003\"בתולת קרקע\"?\u0004 — \u0003כל\u0004 קרקע \u0003ש\u0004בשעה שהיא נחרשת הריהי \u0003מעלה רשושין\u0004 (רגבים קשים), \u0003ואין עפרה תיחוח\u0004 (מפורר), אלא גושי וקשה לעבודה. ואולם אם \u0003נמצא בה\u0004 בקרקע זו שברי כלי \u0003חרס\u0004 — \u0003בידוע שנעבדה\u0004 פעם, שהרי אין כלי חרס נמצא אלא במקום שכבר נעבד. ועוד, נמצא בה \u0003צונמא\u0004 \u0005[סלע]\u0006 באותה הקרקע, שוודאי לא עיבדוהו — \u0003הרי זו\u0004 בכלל \u0003\"בתולת קרקע\".\u0004","שנינו במשנה בהגדרת ה\u0003מעוברת\u0004 שאם ראתה דם דייה שעתה — \u0003משיודע עוברה.\u0004 ושואלים: \u0003וכמה\u0004 הוא שיעור זמן זה של \u0003הכרת העובר? סומכוס אומר משום\u0004 (בשם) \u0003ר' מאיר: שלשה חדשים\u0004 מתחילת ההריון, \u0003ואף על פי שאין ראיה\u0004 מפורשת \u0003לדבר\u0004 זה מן הכתוב — יש \u0003זכר\u0004 (רמז) \u0003לדבר, ש\u0004כן \u0003נאמר\u0004 בהריונה של תמר מיהודה: \u0003\"ויהי כמשלש חדשים\u0004 ויוגד ליהודה לאמר... וגם הנה הרה...\" (בראשית לח, כד), שניכר בה אז שהינה מעוברת.","ושואלים: וכי רק \u0003זכר לדבר\u0004 הוא מקרא זה? והלוא \u0003קרא כתיב\u0004 \u0005[מקרא כתוב]\u0006 במפורש הוא, \u0003וראיה גדולה היא\u0004 שזמן הכרת עיבור הוא שלושה חודשים, ומה השמיענו ר' מאיר? ומשיבים: \u0003משום\u0004 שזמני ההריון של הנשים שונים הם, \u0003דאיכא\u0004 \u0005[שיש]\u0006 אשה \u0003דילדה\u0004 \u0005[שיולדת]\u0006 \u0003לתשעה\u0004 חודשי עיבור, \u0003ואיכא דילדה\u0004 \u0005[ויש שיולדת]\u0006 \u0003לשבעה\u0004 חודשי עיבור, ואפשר לומר כי כשם שזמן הכרת העובר אצל היולדת לתשעה, הוא שליש הריונה (שלושה חודשים), שמא אף אצל זו שזמן הריונה הוא שבעה חודשים, הכרת העיבור הוא שליש הריונה (חודשיים ושליש). ולכן השמיענו ר' מאיר, שבכל הנשים, ואף בזו היולדת לשבעה חודשי הריון, זמן הכרת העובר הוא שלושה חודשים.","ובדומה לנאמר מקודם מביאים עוד את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרי\u0004 אשה \u0003שהיתה בחזקת מעוברת, וראתה דם, ואחר כך הפילה רוח או כל דבר\u0004 אחר \u0003שאינו של קיימא\u0004 — אף שהתברר עתה שלא היתה בהריון, וצריכה להיטמא מעת לעת או מפקידה לפקידה, מכל מקום \u0003הרי היא\u0004 נחשבת \u0003בחזקתה\u0004 כמעוברת, \u0003ודיה שעתה.\u0004","\u0003ואף על גב שאין ראיה\u0004 מפורשת מן המקרא \u0003לדבר,\u0004 יש \u0003זכר לדבר, שנאמר: \"הרינו חלנו כמו ילדנו רוח\"\u0004 (ישעיהו כו, יח). הרי שאף שבסופו \"ילדנו רוח\" נחשב עדיין המצב שלפני כן כהריון (\"הרינו\"). ושואלים על כך: \u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 אמר שהוא \u0003\"זכר לדבר\"\u0004 והלוא מקרא מפורש הוא זה, ו\u0003הרי ראיה גדולה היא!\u0004 ומשיבים: אין זו ראיה שלימה, שכן \u0003כי כתיב האי קרא\u0004 \u0005[כאשר נאמר פסוק זה],\u0006 \u0003בזכרים כתיב\u0004 \u0005[נאמר],\u0006 שהוא דימוי בלבד, ואין ראיה שכך הוא אף להלכה.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על מה ששנינו בברייתא זו ממה ששנינו: \u0003קשתה\u0004 (היתה מקשה ללדת) \u0003שנים\u0004 ימים בתוך אחד עשר ימי זיבה, \u0003ול\u0004יום ה\u0003שלישי\u0004 הוסיפה לראות דם, ואחר כך \u0003הפילה רוח או כל דבר\u0004 אחר \u0003שאינו של קיימא\u0004 — \u0003הרי זו\u0004 נקראת \u0003יולדת בזוב,\u0004 וראיית הדם מצריכתה לנהוג כזבה גמורה, לענין טומאה וטהרה. \u0003ו\u0004מעתה יש לשאול: \u0003אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שלידת רוח וכיוצא בה דיה שעתה, אם כן \u0003לידה מעלייתא\u0004 \u0005[מעולה,\u0006 גמורה\u0005]\u0006 \u0003היא,\u0004"],["והלוא דם היוצא כתוצאה מ\u0003קושי\u0004 ה\u0003סמוך ללידה,\u0004 שעדיין לא ילדה, \u0003רחמנא טהריה\u0004 \u0005[התורה טיהרה אותו]\u0006 (ואינו נחשב לה כדם זיבה) ומדוע נחשבת זו ליולדת בזוב?! \u0003אמר רב פפי:\u0004 אכן, הריון של רוח אינו נחשב הריון, ואולם \u0003הנח\u0004 מלהקשות על דין זה שמטמאה \u0003מעת לעת,\u0004 משום שהיא טומאה מ\u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 והקלו חכמים במעוברת זו שתהא נחשבת כשאר מעוברות, ודייה שעתה.","\u0003רב פפא אמר\u0004 הסבר אחר: \u0003מידי\u0004 \u0005[כלום]\u0006 מה \u0003הוא טעמא\u0004 \u0005[הטעם]\u0006 בענין זה של מעוברת שדייה שעתה, \u0003אלא משום\u0004 שמצבה הגופני ירוד, שכן \u0003ראשה כבד עליה ואבריה כבדין עליה,\u0004 ולכן גם אינה רואה דם. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 זו המעוברת שילדה רוח וכיוצא בו, \u0003ראשה ואבריה כבדין עליה,\u0004 ולכן אינה רואה דם, ואין לטמאה אלא משעה שראתה.","ובענין הדין ששנינו במשנתנו כי המעוברת שראתה דם דייה שעתה, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא:\u0004 אשה ש\u0003ראתה\u0004 דם \u0003ו\u0004מייד \u0003אחר כך הוכר עוברה, מהו\u0004 דינה, האם דייה שעתה או שמטמאה למפרע? וצידי השאלה: האם \u0003כיון דבעידנא דחזאי\u0004 \u0005[שבזמן שראתה\u0006 את הדם\u0005]\u0006 עדיין \u0003לא הוכר עוברה\u0004 — הריהי \u0003מטמיא\u0004 \u0005[מטמאה]\u0006 כשאר נשים, מעת לעת או מפקידה לפקידה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 שב\u0003סמוך לה\u0004 להכרתה כמעוברת הוא ש\u0003חזאי\u0004 \u0005[ראתה]\u0006 — \u0003לא מטמיא\u0004 \u0005[אינה מטמאה]\u0006 למפרע, אלא כשאר הנשים המעוברות, שדיין שעתן?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' ירמיה בתשובה: \u0003מידי\u0004 \u0005[כלום]\u0006 מה \u0003הוא טעמא\u0004 \u0005[הטעם]\u0006 בענין זה שהקילו חכמים במעוברת שדייה שעתה, \u0003אלא משום\u0004 ש\u0003ראשה כבד עליה ואבריה כבדין עליה,\u0004 ולכן אינה רואה דם, ואילו זו \u0003בעידנא דחזאי\u0004 \u0005[בזמן שראתה]\u0006 עדיין לא היתה במצב זה, ועדיין \u0003אין ראשה כבד עליה ואין אבריה כבדין עליה,\u0004 ואין סיבה איפוא להקל עליה.","ועוד בדין המעוברת, \u0003בעא מיניה ההוא סבא\u0004 \u0005[שאל ממנו זקן אחד]\u0006 \u0003מר' יוחנן:\u0004 אשה שיש לה וסת (שחייבת לבדוק עצמה כשמגיע זמן וסתה), ו\u0003הגיע עת וסתה בימי עבורה, ולא בדקה, מהו\u0004 הדין? והוסיף אותו זקן ופירט: \u0003קא מיבעיא\u0004 \u0005[מסופקת היא]\u0006 \u0003לי\u0004 שאלה זו דווקא \u0003אליבא דמאן דאמר\u0004 \u0005[לפי שיטתו של מי שאומר]\u0006 שחובת הבדיקה של הנשים שיש להן \u0003וסתות\u0004 קבועות הריהי \u0003דאורייתא\u0004 \u0005[מן התורה].\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 וצידי השאלה: לשיטה זו האם \u0003כיון\u0004 שחובת הבדיקה בזמן ה\u0003וסתות\u0004 הוא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 — אף המעוברת שהוכר עוברה \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה,\u0004 ואם לא בדקה מן הסתם הריהי טמאה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 שהמעוברת \u0003דמיה מסולקין\u0004 בזמן ההריון — \u0003לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003בדיקה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לאותו זקן בתשובה: \u0003תניתוה\u0004 \u0005[שניתם,\u0006 למדתם כבר\u0005]\u0006 מעין זו במשנה להלן בפרק רביעי: \u0003ר' מאיר אומר, אם היתה\u0004 אשה זו שיש לה וסת שרויה \u0003במחבא,\u0004 מפני יראה כלשהי, \u0003והגיע שעת וסתה\u0004 שבו היא עשויה לראות דם, \u0003ולא בדקה\u0004 עצמה — הריהי \u0003טהורה,\u0004 שכן מניחים אנו שלא ראתה במצבה זה, משום \u0003ש\u0004ה\u0003חרדה מסלקת את הדמים.\u0004 ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שטהורה היא, הוא רק משום \u0003דאיכא\u0004 \u0005[שיש]\u0006 לה במצב זה \u0003חרדה, הא\u0004 \u0005[הרי]\u0006 נסיק מכאן שאם \u0003ליכא\u0004 \u0005[אין]\u0006 מצב של \u0003חרדה, והגיע\u0004 זמן \u0003וסתה ולא בדקה\u0004 — \u0003טמאה\u0004 היא,","\u0003אלמא\u0004 \u0005[מכאן]\u0006 שסבור הוא ר' מאיר כי דין \u0003וסתות\u0004 הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 שאילו היה מדברי חכמים בלבד, לא היתה נטמאת אם לא בדקה עצמה. \u0003ו\u0004מכל מקום סבור ר' מאיר כי \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003חרדה\u0004 — \u0003דמיה מסולקין, ולא בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה.\u0004 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בענין מעוברת יש לומר כי \u0003דמיה מסולקין, ולא בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה.\u0004 ולכן אף שלא בדקה הריהי טהורה.","שנינו במשנה כי האשה ה\u0003מניקה\u0004 את ילדה, אם ראתה דם דייה שעתה, \u0003עד שתגמול\u0004 את בנה מיניקה. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האשה ה\u0003מניקה שמת בנה בתוך\u0004 תקופת ההנקה שהיא בת \u0003עשרים וארבע חדש\u0004 — מפסיקה להיקרא \"מניקה\", ו\u0003הרי היא ככל הנשים, ו\u0004אם ראתה דם הריהי \u0003מטמאה מעת לעת ומפקידה לפקידה.\u0004 ומכיון שדין זה של \"מניקה\" תלוי בכך שהיא מניקה בפועל, \u0003לפיכך, אם היתה מניקתו והולכת\u0004 (ממשיכה) אף יותר מהזמן הרגיל להנקה, וכדי \u0003ארבע או חמש שנים,\u0004 וראתה דם — עדיין \u0003דיה שעתה,\u0004 אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004","\u0003ואילו\u0004 \u0003ר' יהודה ור' יוסי ור' שמעון אומרים:\u0004 דין זה של המניקות שראו ש\u0003דיין שעתן\u0004 אינו חל אלא בתקופת ההנקה הקצובה שהיא \u0003כל עשרים וארבע חדש\u0004 בלבד. \u0003לפיכך, אם היתה מניקתו\u0004 מעבר לתקופה זו, וכדי \u0003ארבע וחמש שנים,\u0004 וראתה דם — הריהי \u0003מטמאה מעת לעת ומפקידה לפקידה.\u0004","\u0003ובהסבר מחלוקתם אומרים:\u0004 \u0003כשתמצא\u0004 (ניתן) \u0003לומר\u0004 בהסבר השיטות הללו כי \u0003לדברי ר'\u0004 \u0003מאיר\u0004 — ה\u0003דם\u0004 שרואה האשה כרגיל כדם נדות, בהיותה מניקה הריהו \u0003נעכר\u0004 (נעשה עכור, משתנה) \u0003ונעשה חלב,\u0004 ולכן כל זמן שהיא מניקה בפועל, אינה רואה דם. ואילו \u0003לדברי ר'\u0004 \u0003יוסי ור' יהודה ור' שמעון,\u0004 הסיבה שאין האשה המינקת רואה דם היא משום ש\u0003אבריה\u0004 הפנימיים \u0003מתפרקין\u0004 (מתרופפים) בשעת הלידה, \u0003ואין נפשה\u0004 (מחזור הוסת התקין) \u0003חוזרת עד עשרים וארבע חדש.\u0004 ואולם מעבר לתקופה זו, בין שהיא מינקת ובין שאינה מינקת, ראויה היא לראות דם.","ושואלים: לשון זו של \u0003\"לפיכך\u0004 אם היתה מניקתו והולכת ארבע או חמש שנים דייה שעתה\" שאמר \u0003ר' מאיר למה לי?\u0004 שכיון שלדבריו ראיית הדם תלויה בהנקה בפועל, ודאי שכל זמן שהיא מניקה אינה רואה דם! ומשיבים: \u0003משום \"לפיכך\"\u0004 שאמרו \u0003ר' יוסי\u0004 ור' יהודה ור' שמעון החולקים עליו, אחז גם ר' מאיר בלשון זו.","וחוזרים ושואלים: \u0003ו\"לפיכך\"\u0004 שאמרו \u0003ר' יוסי\u0004 ור' יהודה ור' שמעון \u0003למה לי?!\u0004 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003ר' יוסי\u0004 וחבריו, \u0003תרתי אית ליה\u0004 \u0005[שתי\u0006 סיבות \u0005יש לו]\u0006 מדוע אין האשה המינקת רואה דם: האחד, משום שהדם נעכר ונעשה חלב. והשני, משום שאיבריה מתרופפים בשעת הלידה. לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006 ר' יוסי וחבריו\u0005]\u0006 בלשון זו של \"לפיכך\", כי הסיבה היא אחת: שאיבריה מתרופפים בלידה, ולאחר תקופת עשרים וארבעה חודש, הריהי שבה לתיקנה, וחוזרת ורואה דם אף שהיא עדיין מניקה.","ומציינים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כפי שהסברנו: בתקופה זו של ההנקה אין המניקת רואה דם, משום ש\u0003דם נעכר ונעשה חלב,\u0004 אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004 \u0003ר'\u0004 \u0003יוסי אומר:\u0004 משום ש\u0003אבריה מתפרקין, ואין נפשה חוזרת עליה עד עשרים וארבע חדש.\u0004 ובהסבר שיטתו זו של ר' מאיר \u0003אמר ר'\u0004 \u0003אלעאי: מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור במקרא\u0005]\u0006 לשיטת \u0003ר' מאיר\u0004 שדם נעכר ונעשה חלב? — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בתשובת איוב לרעיו: \u0003\"מי יתן טהור מטמא לא אחד\"\u0004 (איוב יד, ד), שיצירה מיוחדת היא שעשה הקדוש ברוך הוא (\"אחד\") שמן הטמא נתן את הטהור, שמדם הנדה הטמא עשה את החלב הטהור.","\u0003ורבנן\u0004 \u0005[וחכמים,\u0006 ר' יוסי וחבריו החולקים על ר' מאיר\u0005],\u0006 כיצד הם מפרשים כתוב זה? \u0003אמר ר'\u0004 \u0003יוחנן: זו שכבת זרע, שהוא\u0004 עצמו \u0003טמא, ואדם הנוצר ממנו\u0004 — \u0003טהור.\u0004","\u0003ור' אלעזר אומר: אלו מי הנדה\u0004 (מי אפר פרה אדומה) הניתנים בהזאה על טמא מת, \u0003ש\u0004כן \u0003המזה\u0004 את המים \u0003ו\u0004כן זה ש\u0003מזין עליו\u0004 — \u0003טהור, ו\u0004אילו מי ש\u0003נוגע\u0004 במים — \u0003טמא.\u0004 ושואלים על כך: \u0003ו\u0004כי \u0003מזה\u0004 מי הנדה \u0003טהור\u0004 הוא? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 במפורש בפרשת פרה אדומה: \u0003\"ומזה מי הנדה יכבס בגדיו\"\u0004 (במדבר יט, כא), הרי שטמא הוא, וטעון כיבוס בגדים! ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מזה\"\u0004 האמור בכתוב זה? האדם ה\u0003נוגע\u0004 במי הנדה, הוא הטמא, ואולם המזה את מי הנדה הריהו טהור.","ומקשים על כך: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בכתוב זה \u0003\"מזה\", והכתיב\u0004 \u0005[והרי נאמר]\u0006 באותו כתוב \u0003\"נוגע\",\u0004 כנאמר שם: \"ומזה מי הנדה יכבס בגדיו והנוגע במי הנדה יטמא עד הערב\"? הרי ש\"הנוגע\" אינו המזה! \u0003ועוד,\u0004 גם מתוכן הכתוב עצמו אי אפשר לומר שה\"מזה\" הוא הנוגע, שהרי נאמרו בכתוב דינים שונים במזה ובנוגע, שכן ה\u0003מזה\u0004 הריהו טמא ו\u0003בעי\u0004 \u0005[צריך]\u0006 \u0003כבוס\u0004 בגדים, ואילו האדם ה\u0003נוגע\u0004 במי הנדה הריהו טמא ואולם \u0003לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003כבוס\u0004 בגדים! \u0003אלא\u0004 יש לומר לשיטת ר' אלעזר שהמזה מי הנדה הריהו טהור על אף האמור \"ומזה מי הנדה וכבס בגדיו\", כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מזה\"\u0004 האמור בכתוב זה? כוונתו: ה\u0003נושא\u0004 את מי הנדה, שנטמא בכך, אף שאינו נוגע במים.","ושואלים: אם כן, \u0003וליכתוב\u0004 \u0005[ושיכתוב\u0006 המקרא\u0005]\u0006 במפורש לשון \u0003\"נושא\"\u0004 הברור, ולא לשון \"מזה\"? ומשיבים: \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב על ידי ביטוי זה שאין הנושא את מי הנדה טמא אלא \u0003עד דדרי\u0004 \u0005[שיישא]\u0006 מי נדה שיש בהם \u0003כשיעור\u0004 הראוי ל\u0003הזאה.\u0004 ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003הזאה\u0004 של מי נדה \u0003צריכה שיעור\u0004 מוגדר, כדי שתטהר, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003אין\u0004 הזאה \u0003צריכה שיעור, מאי איכא למימר\u0004 \u0005[מה יש לומר]?! ומשיבים:\u0006","\u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שהזאה \u0003אינה צריכה שיעור, הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003אגבא דגברא\u0004 \u0005[על גבו של האדם]\u0006 הנטהר בהזאה זו. \u0003אבל במנא\u0004 \u0005[בכלי]\u0006 שבו מונחים מי הנדה, וממנו מזים — \u0003בעינא\u0004 \u0005[צריך]\u0006 שיהיה בו מי נידה כ\u0003שיעור\u0004 הזאה. \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה במסכת פרה\u0005]:\u0006 \u0003כמה יהיו במים, ויהא בהן כדי\u0004 שיעור \u0003הזאה?\u0004 — \u0003כדי שיטבול ראשי גבעולין\u0004 של אזוב שבהם מזים על האדם המיטהר \u0003ויזה.\u0004","ואגב הדיון בענין טומאת מי הנדה, מסיימת הגמרא: \u0003והיינו דאמר\u0004 \u0005[וזהו שאמר]\u0006 \u0003שלמה\u0004 המלך בענין טהרת הפרה האדומה: \u0003\"אמרתי אחכמה והיא רחוקה ממני\"\u0004 (קהלת ז, כג).","שנינו במשנה כי ארבע נשים, אם ראו דם דיין שעתן, ואחת מהן היא הזקנה. ובהגדרת הזקנה דנו במשנה: \u0003איזו היא זקנה?\u0004 — \u0003כל\u0004 אשה \u0003שעברו עליה שלש עונות\u0004 ב\u0003סמוך לזקנתה\u0004 בלא שראתה בהן דם. ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 זמן זה המוגדר כ\u0003\"סמוך לזקנתה\"? אמר רב יהודה: כל\u0004 אשה שהגיעה לשלב בחייה \u0003ש\u0004בו \u0003חברותיה אומרות עליה: \"זקנה היא\",\u0004 נחשבת כזקנה. \u0003ור' שמעון\u0004 (בן לקיש) \u0003אומר:\u0004"],["\u0003כל\u0004 אשה שהגיעה לזמן \u0003ש\u0004בו \u0003קורין לה\u0004 (מכנים אותה) \u0003\"אמא, אמא\", ו\u0004היא \u0003אינה בושה\u0004 בכך. ובענין זה נחלקו \u0003ר' זירא ור' שמואל בר רב יצחק, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: כל שאינה מקפדת\u0004 על המכנים אותה כך בפניה, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: כל שאינה בושה\u0004 בכינוי זה. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לענין מי שהיא אמנם \u0003בושה\u0004 בכינוי זה \u0003ו\u0004אולם \u0003אינה מקפדת\u0004 על המכנים אותה כך.","ומבררים עוד, שנינו במשנה שכדי שתהא דיה שעתה צריכים לעבור עליה שלוש עונות בסמוך לזקנתה בלא שתראה דם, ושואלים: \u0003וכמה\u0004 היא \u0003עונה\u0004 זו? \u0003אמר ריש לקיש משום\u0004 (בשם) \u0003ר' יהודה נשיאה:\u0004 הכוונה ל\u0003עונה בינונית\u0004 שהיא של \u0003שלשים יום.\u0004 \u0003ורבא אמר\u0004 שכך אמר \u0003רב חסדא\u0004 בהגדרת משך העונה: \u0003עשרים יום.\u0004 ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 החכמים הללו \u0005חלוקים],\u0006 \u0003אלא שמר\u0004 \u0005[חכם זה,\u0006 ר' יהודה נשיאה\u0005]\u0006 שאמר כי עונה היא בת שלושים יום, הרי זה משום ש\u0003קחשיב\u0004 \u0005[הוא מחשב,\u0006 מונה\u0005]\u0006 את משך הזמן מראייה לראייה, שהם עשרת \u0003ימי טומאה\u0004 (שבעת ימי נידות ושלושה ימי זיבה) \u0003ו\u0004עשרים \u0003ימי טהרה, ו\u0004אילו \u0003מר\u0004 \u0005[חכם זה,\u0006 רב חסדא\u0005]\u0006 שאמר שעונה היא בת עשרים יום, \u0003לא חשיב\u0004 \u0005[אינו מחשב,\u0006 מונה\u0005]\u0006 את ימי טומאה, אלא ימי טהרה בלבד. ועוד בענין זה של זקנה, שדייה שעתה, \u0003תנו\u0004","\u0003רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003זקנה שעברו עליה שלש עונות\u0004 בלא שראתה דם, \u0003ו\u0004בעונה שלאחר מכן \u0003ראתה\u0004 — \u0003דיה שעתה.\u0004 \u0003ו\u0004כן אם \u0003עוד עברו עליה שלש עונות\u0004 בלא שראתה, \u0003ו\u0004שוב \u0003ראתה\u0004 — עדיין היא בגדר \"זקנה\" ש\u0003דיה שעתה.\u0004 \u0003ו\u0004אולם אם \u0003עוד עברו עליה שלש עונות, ו\u0004שוב \u0003ראתה\u0004 — \u0003הרי היא ככל הנשים,\u0004 שאף שהשתנה וסתה לתקופת זמן ארוכה יותר, כאשר ראתה דם הריהי \u0003מטמאה מעת לעת ומפקידה לפקידה.\u0004","\u0003ולא (מיבעיא\u0004 \u0005[נצרך\u0006 לומר]\u0003) שכוונה\u0004 (שדייקה) בשלוש ראיותיה אלה, שכל פעם ראתה בדיוק לאחר שלוש עונות בינוניות, לאמור לאחר תשעים יום בדיוק, \u0003אלא אפילו פיחתה\u0004 במספר הימים שבין ראייה לראייה, \u0003(ואפילו) והותירה\u0004 (הוסיפה) על מספר הימים שבין ראייה לראייה, הרי דינה כשאר הנשים, ומטמאה מעת לעת או מפקידה לפקידה.","ושואלים: מלשון הברייתא: \u0003\"אפילו פיחתה\"\u0004 ניתן לדייק כך: \u0003ולא מבעיא\u0004 \u0005[ואין צורך]\u0006 לומר שדין זה נוהג כאשר \u0003כוונה,\u0004 שכל שלוש הראיות היו כולן במרווחים קבועים. ואולם על כך יש לתמוה: \u0003אדרבה\u0004 \u0005[להיפך]\u0006 הוא הדבר, שהרי \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003כוונה\u0004 שלוש ראיותיה במרווחים קבועים, הרי בכך היא \u0003קבעה לה וסתה, ו\u0004כבר למדנו בשיטת ר' דוסא (למעלה ד,ב) שאשה שיש לה וסת קבועה, \u0003דיה שעתה!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שברייתא זו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, דפליגי עליה\u0004 \u0005[שחולקים עליו]\u0006 על \u0003ר' דוסא, דאמרי\u0004 \u0005[שאומרים]\u0006 הם כי אף \u0003אשה שיש לה וסת מטמאה מעת לעת,\u0004 אף בכך לא תיושב לשון הברייתא, שכן \u0003איפכא מבעי ליה, ולימא\u0004 \u0005[ההיפך היה צריך לו\u0006 לתנא שבברייתא לומר, \u0005ו\u0006כך \u0005לומר]:\u0006 \u0003ולא\u0004 נאמר דין זה שהזקנה הרואה שלוש פעמים לאחר שלוש עונות שב דינה להיות כשאר הנשים דווקא במקרה \u0003שפיחתה\u0004 במספר ימי ההפסקה שבין ראייה לראייה \u0003ו\u0004כן כש\u0003הותירה\u0004 במספר ימי ההפסקה שבין ראייה לראייה, \u0003אלא אפילו\u0004 אם \u0003כוונה,\u0004 וכל ראיותיה היו בדיוק לאחר תשעים יום, וקבעה לה בכך וסת, דינה הוא (לדעת חכמים) שמטמאה מעת לעת או מפקידה לפקידה.","ומשיבים: אכן יש לתקן את לשון הברייתא ו\u0003תני\u0004 \u0005[שנה]\u0006 בה כך: \u0003לא שפיחתה והותירה, אלא אפילו כוונה.\u0004 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר, ש\u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 התנא, \u0005אומר]:\u0006 \u0003ולא\u0004 נאמרה הלכה זו במקרה \u0003שכוונה\u0004 במדוייק את שלוש ראיותיה לאחר תשעים יום, \u0003אלא\u0004 רק במקרה \u0003שפיחתה ו\u0004כן כש\u0003הותירה, אבל\u0004 במקרה ש\u0003כוונה\u0004 — \u0003קבעה לה\u0004 בכך \u0003וסת, ודיה שעתה.\u0004 \u0003ו\u0004לפי נוסח זה, ברייתא זו כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 — כשיטת \u0003ר' דוסא היא.\u0004","שנינו במשנתנו ש\u0003ר' אליעזר אומר\u0004 שלא רק האשה הסמוכה לזקנתה, אלא \u0003כל אשה שעברו עליה\u0004 שלוש עונות שלא ראתה בהן, דייה שעתה, לכשתראה. ועוד בשיטתו זו של ר' אליעזר \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להם ר'\u0004 \u0003אליעזר לחכמים\u0004 כהוכחה לשיטתו מ\u0003מעשה\u0004 שהיה \u0003בריבה\u0004 (צעירה) \u0003אחת ב\u0004יישוב ששמו \u0003היתלו, שהפסיקה\u0004 מלראות דם במשך \u0003שלש עונות,\u0004 ולאחר מכן ראתה דם, \u0003ובא מעשה\u0004 זה \u0003לפני חכמים\u0004 לפסוק בו \u0003ואמרו\u0004 כי \u0003דיה שעתה.\u0004 הרי איפוא שנפסקה ההלכה כשיטתי אף בצעירה.","\u0003אמרו לו\u0004 לר' אליעזר: \u0003אין\u0004 פסק הלכה של \u0003שעת הדחק\u0004 שמקילים בה, מהוה \u0003ראיה\u0004 להלכה כללית. ושואלים: \u0003מאי\u0004 \u0005[מה,\u0006 איזו\u0005] שעת הדחק\u0006 היתה שם? \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003שני\u0004 (שנות) \u0003בצורת הוו\u0004 \u0005[היו],\u0006 וחסו חכמים מלהפסיד את הטהרות המעטות שהיו אז. ו\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאותה צעירה בהיתלו ב\u0003טהרות אפיש לעבידא\u0004 \u0005[מרובות התעסקה],\u0006 ונגעה בהן בפרק הזמן שלפני ראייתה, \u0003וחשו רבנן\u0004 \u0005[וחששו חכמים]\u0006 \u0003להפסד\u0004 מרובה של \u0003טהרות,\u0004 אם יפסקו שמטמאת למפרע.","ועוד בשיטת ר' אליעזר \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה\u0004 אירע באשה שלא היתה סמוכה לזקנתה, שלא ראתה שלוש עונות, ולאחר מכן ראתה, \u0003ועשה\u0004 (ופסק הלכה למעשה) \u0003רבי כר' אליעזר\u0004 שדייה שעתה. \u0003לאחר שנזכר\u0004 רבי שפסק זה הוא כשיטת ר' אליעזר, ולא כחכמים, \u0003אמר: כדי\u0004 (כדאי, ראוי) \u0003הוא ר'\u0004 \u0003אליעזר לסמוך עליו בשעת הדחק.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 לשון זו הנאמרת בברייתא \u0003\"לאחר שנזכר\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא: \u0003לאחר שנזכר\u0004 רבי ש\u0003אין הלכה כר' אליעזר אלא כרבנן\u0004 \u0005[כחכמים],\u0006 אף \u0003בשעת הדחק היכי עביד כוותיה\u0004 \u0005[כיצד עשה כמותו],\u0006 והרי אין זו כהלכה?","\u0003אלא\u0004 יש לומר ש\u0003לא איתמר הילכתא\u0004 \u0005[נאמרה,\u0006 נקבעה \u0005הלכה]\u0006 \u0003לא כמר\u0004 \u0005[כחכם זה]\u0006 \u0003ולא כמר\u0004 \u0005[כחכם זה],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"לאחר שנזכר\"\u0004 — \u0003לאחר שנזכר\u0004 רבי, שאף שלא נפסקה במפורש הלכה כאחת הדעות במחלוקת זו ואולם הרי זו מחלוקת \u0003דלאו\u0004 \u0005[שלא]\u0006 חכם \u0003יחיד\u0004 הוא \u0003פליג עליה\u0004 \u0005[\u0006ש\u0005חולק עליו]\u0006 על ר' אליעזר, \u0003אלא רבים פליגי עליה\u0004 \u0005[חלוקים עליו],\u0006 והיה ראוי לפסוק כמותם, והוא פסק כר' אליעזר שהוא דעת יחיד, \u0003אמר: כדי הוא ר'\u0004 \u0003אליעזר לסמוך עליו בשעת הדחק.\u0004","ובדומה למה ששנינו למעלה במי שפסקה מלראות שלוש עונות, וראתה שוב, דנים במי שטרם הגיע זמנה לראות, וראתה. שכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ה\u0003תנוקת\u0004 (שאינה בת שתים עשרה שנה) שלא הגיע זמנה לראות, שהיא בחזקת מי שאינה רואה דם (\"מסולקת דמים\"), \u0003וראתה.\u0004 מה דינה? \u0003פעם ראשונה\u0004 שראתה — \u0003דיה שעתה,\u0004 וכן פעם \u0003שניה\u0004 שראתה — \u0003דיה שעתה,\u0004 ואולם בכך כבר הוחזקה כמי שרואה, ולכן כשתראה בפעם ה\u0003שלישית\u0004 — \u0003הרי היא ככל הנשים, ומטמאה מעת לעת ומפקידה לפקידה.\u0004","ואם לאחר שכבר ראתה שלוש פעמים \u0003עברו עליה שלש עונות\u0004 (תקופות ראייה, שהן כתשעים יום), ולא ראתה שוב במשך תקופה זו — הרי היא שבה בכך להגדרתה כ\"תינוקת\", ולכן אם חזרה \u0003וראתה\u0004 דם לאחר תשעים יום אלה — \u0003דיה שעתה,\u0004 כשאר הקטנות. \u0003ו\u0004כמו כן אם \u0003עוד\u0004 (שוב) \u0003עברו עליה שלש עונות,\u0004 ולא ראתה בהן, הרי היא עדיין בגדר זה של \"תינוקת\", ולכן אם חזרה \u0003וראתה\u0004 דם לאחריהן — עדיין דינה הוא שתהא \u0003דיה שעתה.\u0004 \u0003ו\u0004אולם אם \u0003עוד עברו עליה\u0004 עוד שלש עונות שלא ראתה בהן, \u0003וראתה\u0004 שוב לאחר תשעים הימים הללו — שוב אינה נחשבת כ\"תינוקת\", אלא כזו שנשתנה ווסתה לתקופת זמן ארוכה יותר. ו\u0003הרי היא ככל הנשים, ומטמאה מעת לעת ומפקידה לפקידה.\u0004","\u0003ו\u0004עוד בדיניה של הקטנה המוחזקת כמי שאינה רואה דם: \u0003כשהגיע זמנה לראות,\u0004 כאשר נהיית היא ל\"גדולה\" בהיותה בת שתים עשרה ויום אחד, וראתה, \u0003פעם ראשונה\u0004 שראתה — דינה הוא ש\u0003דיה שעתה,\u0004 שכן עד לראייה זו הריהי מוחזקת כמי שאינה רואה דם, ואילו בראייה \u0003שניה\u0004 שתראה — הריהי כשאר הנשים הגדולות ו\u0003מטמאה מעת לעת ומפקידה לפקידה.\u0004 ואם \u0003עברו עליה שלש עונות\u0004 שאמורה לראות בהן (תשעים יום), ולא ראתה, \u0003ו\u0004לאחר תשעים יום אלה שוב \u0003ראתה\u0004 — \u0003דיה שעתה,\u0004 וכשיטת ר' אליעזר שבמשנתנו הסבור שנוהג דין זה בכל אשה (ולא רק בזו הסמוכה לזקנתה). ומעתה דנים בדברי הברייתא.","\u0003אמר מר\u0004 \u0005[החכם\u0006 שבברייתא] בדין התינוקת שהוחזקה לראות דם, שאם לאחר מכן \u0003עברו עליה שלש עונות\u0004 שלא ראתה בהן, ואחר כך ראתה — \u0003דיה שעתה.\u0004"],["ומעתה יש מקום לדון בשאלה, קטנה שלא הגיע זמנה לראות ועברו עליה שלוש עונות בהן ראתה ו\u0003הדר קחזיא\u0004 \u0005[חזרה\u0006 ו\u0005ראתה]\u0006 \u0003בעונות,\u0004 כלומר, שלש פעמים בהפסקה של עונה (שלושים יום) ביניהם, \u0003מאי\u0004 \u0005[מה]\u0006 דינה, האם מטמאה מעת לעת או דיה שעתה? \u0003אמר רב גידל, אמר רב: פעם ראשונה ושניה\u0004 — \u0003דיה שעתה, שלישית\u0004 — \u0003מטמאה מעת לעת ומפקידה לפקידה.\u0004","עוד שנינו בברייתא שאם לאחר שפסקה שלוש עונות וראתה \u0003ועוד עברו עליה שלש עונות\u0004 שלא ראתה בהן, \u0003וראתה\u0004 שוב לאחריהן — \u0003דיה שעתה.\u0004 ומעתה דנים אם לאחר מכן \u0003הדר קחזיא\u0004 \u0005[חזרה וראתה]\u0006 \u0003בעונות מאי\u0004 \u0005[מה]\u0006 יהא דינה, האם מטמאה מעת לעת ומפקידה לפקידה, או דיה שעתה?","\u0003אמר רב כהנא, אמר רב גידל, אמר רב: פעם ראשונה\u0004 — \u0003דיה שעתה, שניה\u0004 — \u0003מטמאה מעת לעת ומפקידה לפקידה.\u0004","ומעתה דנים בגוף הברייתא: הברייתא \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003רבי היא,\u0004 ש\u0003אמר\u0004 כלל בדיני החזקות: \u0003בתרי זימני הוי\u0004 \u0005[בשתי פעמים נהיית]\u0006 \u0003חזקה\u0004 ולכן בפעם השלישית הריהי ככל הנשים, אחר שהוחזקה על ידי שתי הראיות הקודמות.","ואולם מעתה \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף]\u0006 הברייתא: \u0003עברו עליה שלש עונות\u0004 שלא ראתה בהן, \u0003ו\u0004אחר כך שוב \u0003ראתה\u0004 — \u0003דיה שעתה,\u0004 והרי בכך \u0003אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004שיטת \u0003ר' אליעזר,\u0004 שכל אשה שלא ראתה שלוש עונות דיה שעתה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי הברייתא כשיטת \u0003רבי היא, ו\u0004אולם \u0003ב\u0004דין זה של \u0003עונות\u0004 \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' אליעזר, ו\u0004אולם על כך יש להקשות: \u0003מי סבר לה\u0004 \u0005[האם\u0006 אכן סבור הוא רבי כר' אליעזר בכך\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 מסופר שאירע ופסק רבי כר' אליעזר, \u0003שלאחר שנזכר\u0004 רבי שמחלוקת יחיד ורבים היא, וראוי היה לפסוק כרבים החולקים על ר' אליעזר, \u0003קאמר\u0004 \u0005[אמר]\u0006 כי ניתן לסמוך על שיטת ר' אליעזר בשעת הדחק, משמע שמלכתחילה אין רבי פוסק כר' אליעזר! \u0003אלא\u0004 יש לומר בשיטת הברייתא כי כ\u0003ר' אליעזר היא, ו\u0004אולם \u0003ב\u0004דין ה\u0003וסתות סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כרבי\u0004 שדי בשתי פעמים כדי לקבוע חזקה.","ועוד בדיני התינוקת. \u0003כתם\u0004 דם שנמצא בבגד של תינוקת שעדיין לא הגיע זמנה לראות וראתה שלוש ראיות, אם נמצא כתם זה בפרק הזמן \u0003שבין\u0004 ראייה \u0003ראשונה ו\u0004ראייה \u0003שניה\u0004 שלה — \u0003טהור\u0004 הכתם מלטמא אותה, שכיון שאינה מוחזקת לראות לא גזרו על כתמיה. ואולם אם נמצא בפרק הזמן \u0003שבין\u0004 ראייה \u0003שניה ושלישית\u0004 — \u0003חזקיה אמר: טמא.\u0004 \u0003ר'\u0004 \u0003יוחנן אמר: טהור.\u0004 ומסבירים את השיטות החלוקות: \u0003חזקיה אמר: טמא, כיון\u0004 שדינה הוא ש\u0003אילו\u0004 לא היה זה כתם אלא \u0003חזיא\u0004 \u0005[ראתה]\u0006 דם ממש בפרק זמן זה — היתה \u0003מטמאה, כתמה נמי\u0004 \u0005[גם כן]\u0006 — \u0003טמא.\u0004 \u0003ור' יוחנן אמר: טהור, כיון\u0004 ש\u0003לא אתחזקה\u0004 \u0005[הוחזקה]\u0006 \u0003בדם,\u0004 שהרי לא ראתה דם ממש אלא שתי פעמים — \u0003כתמה נמי לא מטמינן לה\u0004 \u0005[גם כן אין אנו מטמאים אותה].\u0006"],["\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על שיטת חזקיה\u0005]\u0006 \u0003ר' אלעאי: וכי מה\u0004 ההבדל \u0003בין זו\u0004 התינוקת שמחמירים בה שכתמה טמא, אף שעדיין לא ראתה דם המטמאה למפרע, \u0003ל\u0004בין ה\u0003בתולה\u0004 שנישאת \u0003ש\u0004כל עוד \u0003דמיה טהורין\u0004 אף כתמה טהור, ומניחים שכתם זה מדם בתולים בא? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא\u0004 בתשובה: \u0003זו\u0004 הבתולה שנישאת \u0003שירפה\u0004 (דמה, דם בתוליה) \u0003מצוי\u0004 הוא, ולכן גם תולים בו את הכתם. \u0003ו\u0004אילו \u0003זו\u0004 התינוקת \u0003אין שירפה\u0004 (דמה, דם טהרה) \u0003מצוי\u0004 שנוכל לתלות בו את הכתם שמצאה.","ועוד בדיני כתם התינוקת. \u0003אמר עולא, אמר ר'\u0004 \u0003יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יהוצדק: תינוקת שלא הגיע זמנה לראות\u0004 דם, \u0003וראתה\u0004 ב\u0003פעם ראשונה ושניה\u0004 — עדיין לא הוחזקה בכך להיחשב כמי שרואה, ועדיין בגדר מסולקת דמים היא, ולכן \u0003רוקה ומדרסה בשוק טהור,\u0004 אף שכרגיל רוק הנמצא בשוק וכן מדרס האשה מטמאים מספק. וכן \u0003כתמה\u0004 של תינוקת זו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003טהור\u0004 הוא. והעיר עולא: \u0003ולא ידענא\u0004 \u0005[ואין אני יודע]\u0006 \u0003אם\u0004 הלכה זו ששמעתי מר' יוחנן הינה \u0003דידיה\u0004 \u0005[שלו]\u0006 של ר' יוחנן עצמו, \u0003אם\u0004 הלכה זו היא \u0003דרביה\u0004 \u0005[של רבו],\u0006 ר' שמעון בן יהוצדק.","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[למה,\u0006 לאיזה ענין יש \u0005תוצאה\u0006 \u0005מזה\u0006 אם היא שלו או של רבו\u0005]?\u0006 ומשיבים: אם דברים אלו הם של ר' שמעון בן יהוצדק רבו, יש בכך \u0003למיהוי\u0004 \u0005[לגרום שיהיו]\u0006 \u0003דבריו של\u0004 חזקיה החולק על ר' יוחנן (בעמוד הקודם) וסבור שלאחר שתי ראיות של הקטנה מטמא כתמה, נחשבים כדעתו של \u0003אחד במקום\u0004 (כנגד) דעתם של \u0003שנים\u0004 (ר' יוחנן ורבו ר' שמעון בן יהוצדק) שאינם סבורים כן. ואילו דברים אלה הם של ר' יוחנן עצמו, הרי זו מחלוקת שקולה, דעת חכם אחד מול דעת חכם אחר.","ונמסר בענין זה, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003וכל נחותי ימא\u0004 \u0005[יורדי הים]\u0006 הבאים מהפלגה בים, \u0003אמרוה\u0004 להלכה זו של כתם התינוקת \u0003כ\u0004הלכה שנמסרה בשם \u0003ר' שמעון בן יהוצדק,\u0004 ומזה תלמד שדעת שני חכמים היא, והלכה איפוא כר' יוחנן.","\u0003אמר רב חלקיה בר טובי: תינוקת שלא הגיע זמנה לראות,\u0004 וראתה, \u0003אפילו\u0004 היתה בראייה זו \u0003שופעת\u0004 (רואה ברצף) דם \u0003כל שבעה\u0004 ימים של נידות — \u0003אינה\u0004 נחשבת זו \u0003אלא ראיה אחת,\u0004 ועדיין היא בגדר \"מסולקת דמים\" ודיה שעתה עד שתראה עוד שתי פעמים. ותוהים על לשונו: ממה שאמר \u0003\"אפילו שופעת\"\u0004 ניתן לדייק שאפילו במקרה זה כך הוא דינה, \u0003ולא מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שנוהג דין זה כש\u0003פוסקת\u0004 מלראות ורואה לאחר מכן שוב. ואולם על כך יש לשאול: \u0003אדרבה\u0004 \u0005[להיפך]\u0006 חידוש דין גדול יותר הוא ב\u0003פוסקת,\u0004 שכן אף שלכאורה \u0003הויא לה\u0004 \u0005[הרי היא]\u0006 \u0003כשתי ראיות,\u0004 הרי זה נחשב לה כראיה אחת, ובוודאי שכן הוא הדין בשופעת ברצף כל שבעה!","\u0003אלא\u0004 כך צריך לשנות בדברי רב חלקיה בר טובי: \u0003תינוקת שלא הגיע זמנה לראות, ושופעת כל שבעה\u0004 — \u0003אינה אלא ראיה אחת.\u0004 אבל אם פסקה מלראות בתוך השבעה, וחזרה וראתה שוב, הרי זה נחשב לה כשתי ראיות.","\u0003אמר רב שימי בר חייא:\u0004 הבתולה ה\u0003מדלפת,\u0004 שמפעם לפעם מטפטף הדם, ובלא הפסק ניכר בין טיפה לטיפה, \u0003אינה\u0004 נחשבת כלל \u0003כרואה\u0004 דם. ותוהים: \u0003והא קחזיא\u0004 \u0005[והרי היא רואה]\u0006 דם, וכיצד אפשר לומר שאינה נחשבת כרואה דם! אלא יש לתקן את הלשון, ו\u0003אימא\u0004 \u0005[אמור]\u0006 כך: המדלפת \u0003אינה\u0004 נחשבת \u0003כשופעת\u0004 דם שכל ראיותיה נחשבות כראייה אחת, \u0003אלא\u0004 היא נחשבת \u0003כפוסקת\u0004 בראיותיה, אף שרואה טיפות ברצף.","ותוהים על כך: \u0003מכלל\u0004 הדברים אתה למד שה\u0003שופעת\u0004 שאמרנו שנחשב לה כראיה אחת היא זו שדמה זורם ברצף, ו\u0003כי נהרא\u0004 \u0005[כמו נהר],\u0006 והרי לא ייתכן שתראה אשה כך במשך שבעה ימים! \u0003אלא\u0004 יש לחזור ולתקן את לשון הדברים, וכך \u0003אימא\u0004 \u0005[אמור]\u0006 אותם: המדלפת \u0003אינה אלא כשופעת,\u0004 שנחשב לה הטפטוף הרצוף כשפיעה מתמשכת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חזקה\u0004 היא ש\u0003בנות ישראל עד שלא הגיעו לפרקן\u0004 (זמנן לראות דם נידות) — \u0003הרי הן בחזקת טהרה, ואין\u0004 צורך שתהיינה \u0003הנשים\u0004 הבוגרות והמנוסות בדבר \u0003בודקות אותן.\u0004 ואולם \u0003משהגיעו לפרקן\u0004 — \u0003הרי הן בחזקת טומאה.\u0004 שיש להניח שכבר זבו דם נדות, אלא שלא הבחינו בדבר, וכיון שאין הן יודעות כיצד לבדוק, אין לסמוך על בדיקתן, \u0003ו\u0004לכן \u0003נשים\u0004 הבקיאות בדבר הן ה\u0003בודקות אותן.\u0004","\u0003ר'\u0004 \u0003יהודה אומר: אין בודקין אותן ב\u0004הכנסת \u0003יד\u0004 לפתח הרחם, \u0003מפני ש\u0004בכך הריהן \u0003מעוותות\u0004 (מקלקלות) \u0003אותן\u0004 על ידי שריטה שעלולה להיגרם כתוצאה מהכנסת יד, ואפשר יהיה לחשוב שהדם (שבא על ידי שריטה זו) הוא דם נדה. \u0003אלא\u0004 הדרך הנכונה היא שהנשים \u0003סכות\u0004 (מושחות, מורחות) \u0003אותן בשמן מבפנים\u0004 ובאופן זה לא תיגרם כל שריטה פנימית, \u0003ומקנחות\u0004 (מנגבות, מנקות) \u0003אותן מבחוץ, והן\u0004 (הבנות) מכאן ואילך \u0003נבדקות מאיליהן\u0004 (מעצמן), שכאשר יגיע זמנן יוצא הדם בנחת (על ידי השמן שבפנים).","שנינו במשנתנו כי לדעת תנא קמא המעוברת משעה שהוכר העובר, וכן המניקה משעה שהתחילה להניק, אם ראו דם דיין שעתן. ואילו \u0003ר' יוסי אומר\u0004 שה\u0003מעוברת\u0004 והמניקה דיין שעתן רק משעברו עליהן שלוש עונות, ולא ראו בהן דם. ונמסר כי \u0003תני\u0004 \u0005[שנה]\u0006 ה\u0003תנא\u0004 (חוזר המשניות בבית המדרש) \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אלעזר\u0004 את משנתנו בלשון זו, \u0003ר' יוסי אומר: מעוברת ומניקה שעברו עליה שלש עונות\u0004 שלא ראתה בהן — \u0003דיה שעתה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר: גירסת משנה זו שבידיך, תמוהה היא, שהרי \u0003פתחת בתרי\u0004 \u0005[בשתים] (\"מעוברת ומניקה\"),\u0006 \u0003וסיימת בחדא\u0004 \u0005[באחת]\u0006 (\"שעברו עליה\", \"דיה שעתה\")!","\u0003דלמא\u0004 \u0005[שמא]\u0006 גירסא זו במשנה \"האשה ה\u0003מעוברת והיא מניקה\u0004 שעברו עליה שלש עונות — דייה שעתה\", היא ש\u0003קאמרת\u0004 \u0005[אומר אתה], שחלק מתקופת שלוש העונות בהן לא ראתה היתה בימי עיבורה וחלק בימי הנקתה,\u0006 \u0003ומילתא\u0004 \u0005[ודבר]\u0006 הלכה \u0003אגב אורחיה\u0004 \u0005[דרך אגב]\u0006 כך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 ר' יוסי \u0005השמיע לנו],\u0006 ש(נחשבים) \u0003לה\u0004 ומצטרפים \u0003לימי מניקותה,\u0004 \u0003ו\u0004כן \u0003ימי מניקותה עולין לה\u0004 להשלים למנין שלוש עונות \u0003לימי עיבורה\u0004 אם אין בכל אחת מהן שלוש עונות שלא ראתה בהן. \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 להשלים \u0003לימי מניקותה, וימי מניקותה עולין לה\u0004 להשלים \u0003לימי עיבורה.\u0004","ומפרטים: \u0003כיצד\u0004 היא השלמה זו? היתה מעוברת ו\u0003הפסיקה\u0004 מלראות \u0003שתים\u0004 (שתי עונות) \u0003בימי עיבורה, ו\u0004כשילדה והניקה את בנה הפסיקה עוד עונה \u0003אחת בימי מניקותה,\u0004 או שהיתה מניקה את בנה והפסיקה לראות \u0003שתים בימי מניקותה ו\u0004אחר כך נתעברה שוב והפסיקה שוב עונה \u0003אחת בימי עיבורה.\u0004 או שלא ראתה עונה \u0003אחת ומחצה בימי עיבורה ו\u0004עונה \u0003אחת ומחצה בימי מניקותה\u0004 — הרי הן \u0003מצטרפות לשלש עונות,\u0004 ואם ראתה לאחר מכן — דיה שעתה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 אפשרות ש\u0003ימי ימי עיבורה עולין לה לימי מניקותה, משכחת לה\u0004 \u0005[מוצא אתה אותה],\u0006 ובאופן זה: \u0003דקמניקה ואזלא\u0004 \u0005[שהיא מניקה והולכת],\u0006 \u0003ו\u0004לאחר מכן היא \u0003מיעברה\u0004 \u0005[מתעברת],\u0006 \u0003אלא\u0004 אפשרות זו ש\u0003ימי מניקותה עולין לה לימי עיבורה, היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה],\u0006 והרי בגמר הריונה, בלידה עצמה, ראתה דם, ואין איפוא פרק זמן של שלוש עונות שלא ראתה בו?","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כהסבר לדבר, שמדובר בברייתא זו \u0003בלידה יבשתא\u0004 \u0005[יבשה]\u0006 שהיתה הלידה בלא דם. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כתירוץ \u0003שדם נדה\u0004 הוא \u0003לחוד, ודם לידה לחוד,\u0004 ואין בראיית דם לידה להפריד בין התקופה שלא ראתה בימי עיבורה והתקופה שלא ראתה בימי הנקתה שלאחר הלידה, ומצטרפות שתי התקופות לכלל שלוש עונות שלא ראתה בהן. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כתירוץ נוסף, שאכן \u0003תני\u0004 \u0005[שנה]\u0006 בברייתא זו רק \u0003חדא\u0004 \u0005[אחת]\u0006 מהלכותיה, שימי עיבורה עולים לימי מניקותה, ואל תשנה בה את ההלכה השניה, שאינה אפשרית.","שנינו במשנתנו בדין האשה המסולקת דמים: \u0003במה\u0004 (באיזה ענין) \u0003אמרו\u0004 חכמים כי אם ראתה דם \u0003דיה שעתה\u0004 — בראייה ראשונה, אבל בראייה שניה, הריהי מטמאה מעת לעת ומפקידה לפקידה. ונחלקו חכמים בכוונת הדברים. שכן \u0003אמר רב:\u0004 מה ששנינו שדיין שעתן רק בראייה הראשונה הרי זה \u0003אכולהו\u0004 \u0005[על כולם],\u0006 על כל ארבעת המקרים הנזכרים במשנה — בתולה, זקנה, מעוברת, ומניקה.","\u0003ו\u0004אילו \u0003שמואל אמר: לא שנו\u0004 חכמים במשנתנו דברים אלה \u0003אלא\u0004 בדינן של \u0003בתולה וזקנה\u0004 שראו דם, שדיין שעתן בראייה ראשונה בלבד, \u0003אבל מעוברת ומניקה\u0004 שראו דם — \u0003דיין\u0004 שעתן של המעוברות \u0003כל ימי עיבורן,\u0004 וכן \u0003דיין\u0004 של המניקות \u0003כל ימי מניקותן,\u0004 ואף בראיות שראו לאחר ראיה ראשונה.","\u0003וכן\u0004 נחלקו במחלוקת זו חכמים אחרים, שכך \u0003אמר ר'\u0004 \u0003שמעון בן לקיש:\u0004 דברים אלה שבמשנתנו אמורים \u0003אכולהו\u0004 \u0005[על כולם],\u0006 על כל ארבע הנשים הנזכרות בה כמסולקות דמים, \u0003ו\u0004אילו \u0003ר' יוחנן אמר: לא שנו\u0004 דברים אלה \u0003אלא\u0004 בדינה של ה\u0003בתולה וזקנה, אבל מעוברת ומניקה\u0004 — \u0003דיין\u0004 שעתן של המעוברות \u0003כל ימי עיבורן,\u0004 ואף בראייה שניה והלאה, וכן \u0003דיין\u0004 שעתן של המניקות \u0003כל ימי מניקותן.\u0004 ומציעים: מחלוקת זו שנחלקו בה אמוראים הריהי \u0003כ\u0004מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 שנחלקו באותו נושא. שכן שנינו: \u0003מעוברת ומניקה שהיו\u0004"],["רואות כמה פעמים דם, ואפילו היו \u0003שופעות דם ובאות\u0004 (רואות ראיות רבות וממושכות) — הריהן בגדר מסולקות דמים, ולכן \u0003דיין\u0004 שעתן. ודבר זה אמור בנשים המעוברות לאורך \u0003כל ימי עיבורן\u0004 (הריונן), \u0003ו\u0004אצל המניקות \u0003דיין\u0004 שעתן לאורך \u0003כל ימי מניקותן\u0004 (הנקתן), אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004 \u0003ר'\u0004 \u0003יוסי ור' יהודה ור' שמעון אומרים: לא אמרו\u0004 חכמים שמעוברות ומניקות שראו דם \u0003דיין שעתן אלא בראייה ראשונה\u0004 בלבד, \u0003אבל ב\u0004ראייה \u0003שניה\u0004 הריהי ככל הנשים, ו\u0003מטמאה מעת לעת ומפקידה לפקידה.\u0004 הרי שמחלוקת רב ושמואל, וכן מחלוקת ר' שמעון בן לקיש ור' יוחנן, הריהן כמחלוקת זו של תנאים.","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003אם ראתה\u0004 האשה המסולקת דמים ראייה \u0003ראשונה\u0004 מאונס, אף בראייתה השניה דיה שעתה. ובענין ראייה מאונס \u0003אמר רב הונא:\u0004 אם \u0003קפצה\u0004 האשה \u0003ו\u0004בעקבות הקפיצה \u0003ראתה\u0004 דם, הרי זו ראייה מאונס, ודיה שעתה. ואולם אם \u0003קפצה\u0004 פעם אחרת \u0003וראתה\u0004 שוב דם, וחזרה ו\u0003קפצה ו\u0004שוב \u0003ראתה\u0004 דם — \u0003קבעה לה\u0004 בכך \u0003וסת.\u0004 ומבררים את דבריו: \u0003למאי\u0004 \u0005[למה],\u0006 איזה קביעות וסת היא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שקבעה לה בכך וסת \u0003לימים,\u0004 שאם כל שלוש הקפיצות שבעקבותיהן ראתה דם היו באותו יום בשבוע, קבעה לה בכך וסת לאותו יום, שמכאן ואילך אם תראה שוב באותו יום בשבוע, ואפילו בלא שקפצה קודם לכן — דייה שעתה. וכן שמכאן ואילך עליה לבדוק עצמה בבוא אותו יום בשבוע, ואם לא בדקה הריהי טמאה מספק — אי אפשר לומר כן, שהרי כל ראיותיה היו בעקבות קפיצה, ואין לקבוע לה וסת לימים, בלא שקפצה, והראיה לכך: \u0003הא\u0004 \u0005[הרי]\u0006 ב\u0003כל יומא\u0004 \u0005[יום]\u0006 ש\u0003לא קפיץ\u0004 \u0005[לא קפצה]\u0006 בו, \u0003לא חזאי\u0004 \u0005[לא ראתה],\u0006 ומכאן שוסתה תלוי בקפיצה!","\u0003אלא\u0004 אם תאמר שכוונת רב הונא שקבעה לה בכך וסת \u0003לקפיצות,\u0004 שמכאן ואילך בכל יום בשבוע שתקפוץ, הריהי חייבת לבדוק עצמה, ואם לא בדקה — הריהי טמאה מספק. \u0003ו\u0004אולם אף זה מוקשה, שכן \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל\u0004 קביעות וסת \u0003שתקבענה\u0004 האשה \u0003מחמת אונס, אפילו\u0004 שבה וראתה דם בעקבות אותו אונס כמה ו\u0003כמה פעמים\u0004 — \u0003לא קבעה\u0004 לה בכך \u0003וסת!\u0004 ודנים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ש\u0003לא קבעה וסת כלל,\u0004 אף לא לקפיצות!","ומשיבים: \u0003לא,\u0004 הכוונה היא שאם ראתה כמה פעמים מתוך אונס כגון קפיצות, וכולן התרחשו ביום מסויים בשבוע, \u0003לא קבעה וסת לימים לחודייהו\u0004 \u0005[לעצמם],\u0006 שאין היא צריכה לבדוק בכל שבוע באותו יום, אם לא קפצה בו. \u0003ו\u0004כמו כן לא קבעה לה וסת \u0003לקפיצות לחודייהו\u0004 \u0005[לעצמן],\u0006 שאין היא צריכה לבדוק עצמה בכל פעם שתקפוץ. \u0003אבל קבעה לה\u0004 בכך \u0003וסת לימים ולקפיצות\u0004 ביחד, שמכאן ואילך אם תקפוץ באותו יום בשבוע, הריהי צריכה לבדוק עצמה, ככל אשה שקבועה לה וסת, ואם לא בדקה, הריהי טמאה מספק. ותוהים על הסבר זה: מה שלא קבעה לה בכך וסת \u0003לימים לחודייהו\u0004 \u0005[לעצמם]\u0006 \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו] הוא, שהרי אחת מהסיבות לראיותיה היא הקפיצות, ובלעדיהן אינה קובעת וסת! \u0003אמר רב אשי:\u0004 מדובר בברייתא ב\u0003כגון דקפיץ בחד\u0004 \u0005[שקפצה באחד,\u0006 ביום ראשון\u0005]\u0006 \u0003בשבת\u0004 (בשבוע), \u0003וחזאי\u0004 \u0005[וראתה],\u0006 \u0003וקפיץ בחד\u0004 \u0005[וקפצה\u0006 שוב \u0005ב\u0006יום \u0005אחד,\u0006 בראשון\u0005]\u0006 \u0003בשבת\u0004 שלאחר מכן \u0003וחזאי\u0004 \u0005[וראתה]\u0006 שוב, \u0003וב\u0004יום \u0003שבת\u0004 שלאחריה \u0003קפצה ולא חזאי\u0004 \u0005[ראתה],\u0006 \u0003ו\u0004אולם \u0003ל\u0004מחרת ב\u0003חד\u0004 \u0005[באחד]\u0006 \u0003בשבת חזאי\u0004 \u0005[ראתה]\u0006 \u0003בלא קפיצה.\u0004","ומעתה יש מקום לדברי הברייתא, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 בכך שבפעם השלישית קפצה בשבת ולא ראתה ואילו ביום ראשון בשבוע ראתה אף שלא קפצה, \u0003איגלאי מילתא\u0004 \u0005[התברר הדבר]\u0006 \u0003למפרע\u0004 שגם בשתי הראיות הקודמות שראתה כשקפצה ביום ראשון \u0003דיומא\u0004 \u0005[שהיום]\u0006 המסויים הזה בשבוע \u0003הוא דקגרים\u0004 \u0005[שגרם]\u0006 לה לראות דם בפעמים הקודמות, \u0003ולא\u0004 ה\u0003קפיצה,\u0004 ומעתה נאמר שקבעה לה בכך וסת לימים בלבד ובלא קפיצות, לכן באה הברייתא ו\u0003קא משמע לן\u0004 \u0005[משמיעה לנו]\u0006 שה\u0003קפיצה נמי\u0004 \u0005[גם כן]\u0006 שקפצה \u0003אתמול\u0004 בפעמים הקודמות ביום שבת \u0003גרמא\u0004 \u0005[גורמת]\u0006 גם היא לראייה שראתה ביום ראשון, \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא חזאי\u0004 \u0005[ראתה]\u0006 אתמול לאחר שקפצה, הרי זה \u0003משום דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא מטא\u0004 \u0005[הגיע]\u0006 \u0003זמן קפיצה\u0004 שבעקבותיה היא רואה, שהוא ביום ראשון.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 למהלך סוגיא זו, \u0003אמר רב הונא:\u0004 אם \u0003קפצה\u0004 האשה \u0003ו\u0004בעקבות כן \u0003ראתה\u0004 דם, וחזרה ושוב \u0003קפצה ו\u0004שוב \u0003ראתה,\u0004 וכן בפעם שלישית \u0003קפצה וראתה\u0004 דם — \u0003קבעה לה\u0004 בכך \u0003וסת לימים ולא לקפיצות.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אמר רב אשי:\u0004 כגון \u0003דקפיץ בחד\u0004 \u0005[שקפצה ב\u0006יום \u0005ראשון]\u0006 \u0003בשבת\u0004 (בשבוע) \u0003וחזאי\u0004 \u0005[וראתה],\u0006 וחזרה \u0003וקפיץ בחד\u0004 \u0005[וקפצה\u0006 שוב \u0005ב\u0006יום \u0005ראשון]\u0006 \u0003בשבת וחזאי\u0004 \u0005[וראתה],\u0006 \u0003וב\u0004יום \u0003שבת קפצה ולא חזאי\u0004 \u0005[ולא ראתה],\u0006 \u0003ו\u0004אולם \u0003לחד בשבת (אחרינא) חזאי\u0004 \u0005[וב\u0006יום \u0005ראשון בשבוע אחר ראתה]\u0006 \u0003בלא קפיצה, דהתם\u0004 \u0005[ששם]\u0006 במקרה שכזה, הרי מעתה \u0003איגלאי מילתא\u0004 \u0005[התברר הדבר]\u0006 \u0003דיומא\u0004 \u0005[שהיום]\u0006 \u0003הוא דקא גרים\u0004 \u0005[שגרם]\u0006 את הראיות אף בפעמים הקודמות, שהרי ראתה בפעם השלישית ביום ראשון, אף שלא קפצה בו. ואילו ביום שבת, שקפצה בו, לא ראתה.","\u0003אף על פי שאמרו\u0004 שאשה שיש לה וסת שראתה דם שלא בזמן וסתה, אינה מטמאה למפרע, ו\u0003דיה שעתה,\u0004 ואין לחשוש שיצא הדם לפני כן, מכל מקום \u0003צריכה\u0004 אשה זו, ככל שאר הנשים \u0003להיות בודקת\u0004 בכל יום כדי לדעת שהיא טהורה, לבל תטמא טהרות שהיא עוסקת בהן. \u0003חוץ מן הנדה\u0004 בתוך שבעת ימי נדתה, שבהן היא טמאה בין כה וכה. \u0003ו\u0004כן \u0003ה\u0004אשה שילדה ועתה הריהי \u0003יושבת על דם טוהר,\u0004 אינה צריכה לבדוק, שהרי אף אם תראה דם, הריהי טהורה.","\u0003ו\u0004עוד בדיני בדיקה: אף האשה שיש לה וסת, צריכה שתהא \u0003משמשת\u0004 מיטתה \u0003בעדים\u0004 (פיסות בד שבודקת בהם), לפני ואחרי התשמיש. \u0003חוץ מיושבת על דם טוהר\u0004 שאינה צריכה לכך, \u0003ו\u0004חוץ מן ה\u0003בתולה\u0004 שזה לה תשמיש ראשון, שכל ארבעת הימים שלאחר הבעילה אינה צריכה לבדוק, שאף אם תמצא דם — טהורה היא, \u0003ש\u0004כן \u0003דמיה\u0004 (דמי בתוליה) הריהם \u0003טהורים.\u0004","\u0003ו\u0004עוד בהלכות בדיקה: \u0003פעמים\u0004 בכל יום \u0003צריכה\u0004 כל אשה \u0003להיות בודקת\u0004 עצמה, ב\u0003שחרית,\u0004 שמא ראתה בלילה, \u0003ובין השמשות,\u0004 שמא ראתה ביום, \u0003ו\u0004כן צריכה היא לבדוק \u0003בשעה שהיא עוברת\u0004 (עומדת, קרובה) \u0003לשמש את ביתה,\u0004 כלומר, לתשמיש עם בעלה. ובדיני בדיקה, \u0003יתירות עליהן\u0004 על שאר הנשים, הן הנשים ה\u0003כהנות,\u0004 שהן בודקות גם \u0003בשעה שהן\u0004 רוצות להיות \u0003אוכלות בתרומה.\u0004 \u0003ר'\u0004 \u0003יהודה\u0004 מוסיף ו\u0003אומר:\u0004 הנשים הכהנות צריכות לבדוק \u0003אף בשעת עברתן\u0004 (סיומן) \u0003מלאכול בתרומה,\u0004 כדי לברר אם לא ראו דם בתוך אכילתן.","שנינו במשנתנו כי כל הנשים צריכות לבדוק, ואף אשה שיש לה וסת, \u0003חוץ מן הנדה,\u0004 שזו \u0003בתוך ימי נדתה לא בעי\u0004 \u0005[אינה צריכה]\u0006 \u0003בדיקה.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003ר' שמעון בן לקיש,\u0004 ש\u0003אמר: אשה קובעת לה וסת בתוך\u0004 אחד עשר \u0003ימי זיבתה\u0004 שבין נדה לנדה, בהסתמך על ראייה בתוך הימים האלה, \u0003ו\u0004אולם \u0003אין אשה קובעת לה וסת\u0004 אם ראתה \u0003בתוך ימי נדתה.\u0004 ולפי זה \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן\u0005]\u0006 מה ששנינו במשנתנו שאין הנדה צריכה לבדוק בתוך ימי נדתה. \u0003אלא ל\u0004דעת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 \u0003שאשה קובעת לה וסת בתוך ימי נדתה,\u0004 אם כן \u0003תבדוק\u0004 הנדה בתוך ימי נדתה, אם ראתה דם, שהרי אפשר שתראה, ו\u0003דילמא קבעה\u0004 \u0005[שמא תיקבע]\u0006 \u0003לה וסת\u0004 בהסתמך על ראייה זו!","ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003ר' יוחנן: כי אמינא אנא\u0004 \u0005[כאשר אמרתי אני]\u0006 את שיטתי זו, הרי זה רק \u0003היכא דחזיתיה\u0004 \u0005[היכן,\u0006 במקרה, \u0005שראתה אותו,\u0006 את הדם\u0005]\u0006 בתחילה, שלא ראתה דם קודם לכן, והרי הדבר דומה כבא \u0003ממעין סתום.\u0004 \u0003אבל\u0004 אם \u0003חזיתיה\u0004 \u0005[ראתה אותו]\u0006 לאחר שכבר ראתה דם, והוא בתוך ימי נידותה, והרי הדבר דומה כבא \u0003ממעין פתוח\u0004 — בזה \u0003לא אמרי\u0004 \u0005[אמרתי]\u0006 שתיקבע וסת על סמך ראייה זו.","עוד שנינו במשנתנו כי היושבת על דם טוהר אינה צריכה בדיקה כשאר הנשים. ודנים בדבר: בפירוש הלשון \"\u0003והיושבת על דם טוהר\" קא סלקא דעתך\u0004 \u0005[עולה על דעתנו]\u0006 לומר כי הכוונה היא לאשה ה\u0003מבקשת לישב על דם טוהר,\u0004 שהסתיימו ימי טומאתה ועומדת היא לפתוח בימי טהרתה, ובאה משנתנו להשמיענו כי כדי לפתוח בימי טהרתה אין היא צריכה בדיקה שתסיים את ימי טומאתה.","ויש לשאול: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רב,\u0004 ש\u0003אמר\u0004 שהדם היוצא מן האשה שבעה ימים לאחר לידת זכר וארבעה עשר ימים לאחר לידת נקבה, וכן הדם הבא לאחריהם (בשלושים ושלושה הימים הבאים בזכר, ובששים וששה הימים הבאים לנקבה) — \u0003מעין אחד הוא,\u0004 כלומר, מקור הדם הוא אחד לשני דמים אלו, אלא ש\u0003התורה טמאתו\u0004 לאותו דם שלאחר הלידה (שבוע לזכר ושבועיים לנקבה), \u0003והתורה טהרתו\u0004 לאחר מכן, ולכן גם אם האשה ממשיכה לזוב דם אחר שבוע (לזכר) או שבועיים (לנקבה) ללידתה, אומרים אנו שדם טוהר הוא, ואינה מטמאה. ולפי זה \u0003שפיר\u0004 \u0005[יפה,\u0006 מובנים] דברי המשנה.","\u0003אלא ל\u0004שיטת \u0003לוי\u0004 ש\u0003אמר\u0004 \u0003ששני מעינות\u0004 נפרדים \u0003הם,\u0004 ורק משנסתם מקור הדם הטמא, נפתח מקור הדם הטהור. וכן משנסתם מקור הדם הטהור, נפתח מקור הדם הטמא. אם כן לשיטה זו יש לשאול על האמור במשנתנו כי המבקשת לישב על דם טוהר אינה צריכה בדיקה, והרי צריכה היא ש\u0003תבדוק\u0004 עצמה, \u0003דילמא אכתי\u0004 \u0005[שמא עדיין]\u0006 \u0003לא פסק ההוא\u0004 \u0005[אותו]\u0006 \u0003מעין טמא!\u0004 ומתרצים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003לוי\u0004 בתשובה: \u0003הא\u0004 \u0005[\u0006משנתנו \u0005זו],\u0006 כשיטת \u0003מני\u0004 \u0005[מי היא]\u0006 —"],["שיטת \u0003בית שמאי היא, דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 שגם הדם היוצא לאחר הלידה וגם הדם הבא לאחריו \u0003מעין אחד הוא,\u0004 ואילו שיטתי היא כדעת בית הלל החולקים עליהם. ושואלים: \u0003ו\u0004כי \u0003סתם לן\u0004 \u0005[לנו],\u0006 כלומר, שנה ה\u0003תנא\u0004 בה דברים ללא ציון שם אומרם, \u0003כ\u0004דעת \u0003בית שמאי\u0004 שאין הלכה כמותם? ומשיבים: שנה כך התנא, כיון שמשנתנו נאמרה אכן ב\u0003סתם,\u0004 \u0003ו\u0004אולם \u0003אחר כך\u0004 תישנה משנה שבה תובא \u0003מחלוקת\u0004 בית שמאי ובית הלל, עם ייחוס שיטתם לשמם, ודרך התנא \u0003הוא\u0004 לשנות כן, \u0003ו\u0004דקדק התנא להביא כך את הדברים, שכן כלל הוא ש\u0003כל סתם ואחר כך מחלוקת\u0004 — \u0003אין הלכה כסתם.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תשובה אחרת לשאלה שנשאלה על שיטת לוי: \u0003מי קתני\u0004 \u0005[האם שנינו\u0006 במשנתנו\u0005]\u0006 \u0003\"מבקשת לישב\",\u0004 שמדובר באשה שסיימה ימי טומאתה ומבקשת להתחיל ימי טהרתה? הרי \u0003\"יושבת\u0004 על דם טוהר\" \u0003קתני\u0004 \u0005[שנינו]\u0006 במשנתנו, שכבר יושבת, ואמרה המשנה שפטורה מלבדוק בימי טהרתה. ותוהים על כך: \u0003אי\u0004 \u0005[אם]\u0006 מדובר ב\u0003יושבת\u0004 ממש על דם טוהר, \u0003מאי למימרא\u0004 \u0005[מה\u0006 חידוש \u0005יש לומר\u0006 בזה\u0005]\u0006 שפטורה מלבדוק, והרי היא בימי טהרתה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שבכל זאת \u0003תיבדוק, דדילמא\u0004 \u0005[ששמא]\u0006 אם תראה שלוש פעמים בזמנים קצובים בתוך הימים האלה, \u0003קבעה\u0004 \u0005[נקבעת]\u0006 \u0003לה\u0004 בכך מכאן ואילך \u0003וסת,\u0004 אף שהן ראיות של דם טוהר, לכן \u0003קא משמע לן\u0004 \u0005[השמיעה לנו]\u0006 המשנה שראיית דם הבא מ\u0003מעין טהור ל\u0004ענין דם הבא מ\u0003מעין טמא\u0004 (דם נדות) — \u0003לא קבעה\u0004 \u0005[אינה נקבעת]\u0006 וסת.","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ללוי,\u0004 ש\u0003אמר שני מעינות הם,\u0004 ולכן אין קובעת וסת על דם הבא ממקור אחד בהסתמך על דם הבא ממקור אחר. \u0003אלא לרב\u0004 ש\u0003אמר\u0004 כי שני סוגי הדמים שאשה רואה ממעין \u0003אחד הוא\u0004 — \u0003תבדוק\u0004 בימי טהרתה, \u0003דילמא\u0004 \u0005[שמא]\u0006 תראה שלוש פעמים בזמנים קצובים ו\u0003קבעה\u0004 \u0005[נקבעת]\u0006 \u0003לה\u0004 בכך \u0003וסת!\u0004 ומשיבים: \u0003אפילו\u0004 תאמר \u0003הכי\u0004 \u0005[כך]\u0006 ששני סוגי הדם ממקור אחד הם, לשיטת רב, מכל מקום \u0003מימי טהרה לימי טומאה לא קבעה\u0004 \u0005[אינה קובעת]\u0006 וסת.","\u0003ו\u0004עוד שנינו במשנתנו כי אף אשה שיש לה וסת \u0003משמשת\u0004 עם בעלה \u0003בעדים\u0004 לפני ואחרי התשמיש. ובאותו ענין \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה בפרק האחרון שבמסכת זו\u0005],\u0006 \u0003תינוקת\u0004 (בת פחות משתים עשרה שנה ויום אחד) \u0003שלא הגיע\u0004 עדיין \u0003זמנה לראות\u0004 דם נדה \u0003ונשאת, בית שמאי אומרים: נ\u0004 \u0003ותנין לה ארבע לילות,\u0004 שאם היא נבעלת ורואה דם במשך ארבעת הלילות הראשונים, מניחים שהדם הזה הוא דם בתולים, ומותרת לבעלה. \u0003ובית הלל אומרים:\u0004 אין לכך קיצבת זמן קבועה, אלא הרי זה בגדר דם בתולים \u0003עד שתחיה המכה\u0004 (שיתרפא הפצע) של הבתולים, גם אם נמשך הדבר זמן רב.","\u0003אמר רב גידל, אמר שמואל: לא שנו\u0004 בית הלל שהדמים שתראה הריהם בחזקת דם בתולים עד שיתרפא פצע הבתולים, \u0003אלא\u0004 רק כ\u0003שלא פסקה\u0004 מלראות דם \u0003מחמת תשמיש,\u0004 כלומר, שכל פעם שהיא משמשת עם בעלה הריהי רואה דם, והרי זה מוכיח שדם הבא מפצע הבתולים הוא, \u0003ו\u0004לכן אף אם \u0003ראתה\u0004 אז דם \u0003שלא מחמת תשמיש\u0004 סבורים בית הלל שדם זה מחמת פצע הבתולים, שטרם נרפא. \u0003אבל\u0004 אם \u0003פסקה\u0004 כבר מלראות \u0003מחמת תשמיש,\u0004 כלומר, ששימשה עם בעלה, ולא ראתה, הרי זה מוכיח שנרפא הפצע, \u0003ו\u0004אם לאחר מכן \u0003ראתה\u0004 — הרי היא \u0003טמאה.\u0004","ועוד לשיטת בית הלל זו: אם \u0003עבר\u0004 עליה \u0003לילה אחת בלא תשמיש, ו\u0004לאחר מכן \u0003ראתה\u0004 דם בלא ששימשה עם בעלה — הרי זה מוכיח שדם זה אינו דם הבתולים, והרי היא \u0003טמאה.\u0004 ועוד: אם \u0003נשתנו מראה דמים שלה\u0004 שמראה הדם שונה ממראה דם הבתולים — הריהי \u0003טמאה.\u0004 \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' יונה\u0004 על הלכה אחרונה זו שבדברי שמואל: \u0003ו\u0004אם כן, מה ששנינו במשנתנו ש\u0003בתולה שדמיה טהורים\u0004 אינה צריכה בדיקה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אינה צריכה בדיקה, אדרבה צריכה היא ש\u0003תשמש בעדים\u0004 מפני החשש \u0003דדילמא\u0004 \u0005[ששמא]\u0006 \u0003נשתנו מראה דמים שלה\u0004 ממראה דם הבתולים, ועכשיו היא רואה דם נדה!","\u0003אמר רבא:\u0004 עד שמקשים לדברי שמואל אלו ממה ששנינו בסוף משנתנו, \u0003אימא\u0004 \u0005[אמור]\u0006 את השנוי ב\u0003רישא\u0004 \u0005[בתחילת\u0006 משנתנו\u0005]\u0006 שכל הנשים צריכות לבדוק שחרית וערבית, \u0003חוץ מן הנדה והיושבת על דם טוהר\u0004 שאינן צריכות לכך, ויש לדייק באופן זה: דווקא שתי אלה \u0003הוא דלא בעיא\u0004 \u0005[שאינה צריכה]\u0006 \u0003בדיקה, אבל בתולה\u0004 אף \u0003שדמיה טהורין\u0004 בכל זאת הריהי \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה.\u0004 ובוודאי משום החשש שמא נשתנו דמיה, והרי ראיה ממשנתנו לדברי שמואל הללו! ושואלים: \u0003אלא קשיין אהדדי\u0004 \u0005[קשים\u0006 הם הדיוקים משני חלקי המשנה \u0005זה על זה],\u0006 וכיצד ניישב את דברי המשנה?","ומשיבים: אין זו סתירה, שכן אפשר לומר כי \u0003כאן\u0004 בסוף המשנה מדובר כ\u0003ששמשה\u0004 עכשיו, ובמקרה זה הריהי פטורה מלבדוק עצמה שמא יימצא דם שהשתנה מראהו מדם פציעת הבתולים, שכן אפילו אם יימצא לא נטמאנה בשל כך, מפני \u0003דאימא\u0004 \u0005[ש\u0006יש מקום \u0005לומר]\u0006 שהסיבה לשינוי המראה הוא שה\u0003שמש\u0004 (כינוי לאיבר התשמיש) \u0003עכרן\u0004 (גרם לשינוי הצבע). ואילו \u0003כאן\u0004 בתחילת המשנה שדייקנו ממנה שהבתולה שנבעלה צריכה לבדוק שחרית וערבית מדובר כ\u0003שלא שמשה\u0004 עכשיו, שמא יימצא דם שהשתנה מראהו מדם הבתולים.","ומביאים ראיה לדברי רב גידל בשם שמואל בשיטת בית הלל, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא המגדירה \u0005גם כן כך]\u0006 את שיטת בית הלל: \u0003במה דברים אמורים\u0004 שדם בתולה הריהו טהור עד שתירפא המכה? — כל זמן \u0003שלא פסקה\u0004 מלראות \u0003מחמת תשמיש, ו\u0004אף אם \u0003ראתה שלא מחמת תשמיש.\u0004","\u0003אבל\u0004 אם \u0003פסקה\u0004 לראות \u0003מחמת תשמיש,\u0004 ששימשה עם בעלה פעם אחת ולא ראתה דם, \u0003ו\u0004אם אחר כך \u0003ראתה\u0004 — הרי זו \u0003טמאה.\u0004 וכמו כן, אם \u0003עבר לילה אחת בלא תשמיש, ו\u0004לאחר מכן \u0003ראתה\u0004 בלא ששימשה עם בעלה — \u0003טמאה.\u0004 וכן אם \u0003נשתנו מראה דמים שלה\u0004 ממראה דם הבתולים — \u0003טמאה.\u0004","שנינו במשנתנו כי \u0003פעמים היא צריכה\u0004 לבדוק: שחרית, ובין השמשות. ובהסבר הדברים \u0003אמר ר'\u0004 \u0003יהודה, אמר שמואל: לא שנו\u0004 שצריכה האשה בדיקות אלה \u0003אלא ל\u0004ענין \u0003טהרות,\u0004 שבודקת ביום — כדי להחזיק בטהרה את הטהרות שהתעסקה בהן בלילה, ובלילה — כדי להחזיק בטהרה את הטהרות שהתעסקה בהן ביום. \u0003אבל ל\u0004ענין תשמיש עם \u0003בעלה מותרת\u0004 היא בלא בדיקה. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך משמעות המשנה, שהרי \"צריכה להיות בודקת \u0003שחרית\" תנן\u0004 \u0005[שנינו]\u0006 במשנה, ותשמיש המיטה נוהג בלילה, ולא ביום!","\u0003אלא אי\u0004 \u0005[אם]\u0006 דברי רב יהודה בשם שמואל \u0003אתמר\u0004 \u0005[נאמרו]\u0006 בצורתם זו, יש לומר כי \u0003אסיפא אתמר\u0004 \u0005[על סוף\u0006 המשנה \u0005נאמרו],\u0006 שנאמר שם: \"צריכה להיות בודקת... \u0003ובשעה שהיא עוברת לשמש את ביתה\".\u0004 ועל דברים אלו שבמשנה \u0003אמר רבי יהודה, אמר שמואל: לא שנו\u0004 שצריכה בדיקה כשהיא עוברת לשמש את ביתה \u0003אלא באשה\u0004 שהיא \u0003עסוקה בטהרות, דמגו דבעיא\u0004 \u0005[שמתוך ש\u0006היא \u0005צריכה]\u0006 \u0003בדיקה לטהרות, בעיא נמי\u0004 \u0005[צריכה גם כן]\u0006 \u0003בדיקה\u0004 כדי \u0003ל\u0004שמש עם \u0003בעלה, אבל\u0004 אשה ש\u0003אינה עסוקה בטהרות\u0004 — \u0003לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003בדיקה\u0004 כדי לשמש עם בעלה.","ושואלים על כך: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 רב יהודה בשם שמואל בזה? והלוא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר דבר זה (במשנה שבפרק הבא): \u0003כל הנשים בחזקת טהרה לבעליהן,\u0004 ואינן צריכות בדיקה כדי לשמש עמהם! ומשיבים: \u0003אי ממתניתין הוה אמינא\u0004 \u0005[אם מ\u0006אותה \u0005משנה הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003באשה שיש לה וסת\u0004 קבוע, ואינה צריכה לחשוש בזמן שאינו וסתה, \u0003אבל אשה שאין לה וסת\u0004 קבוע — \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה\u0004 כדי לשמש עם בעלה. ולכך בא רב יהודה בשם שמואל להשמיענו שאף אשה שאין לה וסת אינה צריכה בדיקה כדי שתוכל לשמש עם בעלה.","ומקשים: \u0003והא מתניתין\u0004 \u0005[והרי משנתנו]\u0006 \u0003באשה שיש לה וסת עסקינן\u0004 \u0005[עוסקים אנו]!\u0006 ומשיבים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 עוסקת \u0003בין\u0004 באשה \u0003שיש לה וסת, בין\u0004 באשה ש\u0003אין לה וסת, והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה משמיע לנו]:\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003יש לה וסת, מגו דבעיא\u0004 \u0005[מתוך שצריכה]\u0006 \u0003בדיקה לטהרות, בעיא נמי\u0004 \u0005[צריכה גם כן]\u0006 \u0003בדיקה ל\u0004פני תשמיש עם \u0003בעלה.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 כבר \u0003אמרה שמואל\u0004 את ההלכה הזו \u0003חדא זימנא\u0004 \u0005[פעם אחת]!\u0006 שכן \u0003אמר ר'\u0004 \u0003זירא, אמר ר'\u0004 \u0003אבא בר ירמיה, אמר שמואל: אשה שאין לה וסת\u0004 קבוע \u0003אסורה לשמש\u0004 עם בעלה \u0003עד שתבדוק.\u0004 \u0003ואוקימנא\u0004 \u0005[והעמדנו]\u0006 דבר זה \u0003ב\u0004אשה ה\u0003עסוקה בטהרות.\u0004 משמע שכאשר אינה עסוקה בטהרות אינה צריכה בדיקה לבעלה! ומשיבים: שמואל עצמו לא אמרה פעמיים, אלא \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003מכלל חברתה אתמר\u0004 \u0005[נאמרה],\u0006 שלמדו שומעיו שכך דעת שמואל בדבר אחד מתוך מה שאמר בדבר אחר.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003במה דברים אמורים\u0004 שצריכה בדיקה? — \u0003לטהרות, אבל לבעלה\u0004 — \u0003מותרת\u0004 אף בלא בדיקה. ו\u0003במה דברים אמורים\u0004 שאינה צריכה בדיקה לבעלה? — \u0003ש\u0004הלך למדינה אחרת \u0003והניחה בחזקת טהורה\u0004 ואחר כך חזר, שיכול להניח שעדיין טהורה היא, \u0003אבל הניחה בחזקת טמאה\u0004 — \u0003לעולם\u0004 האשה \u0003היא בטומאתה\u0004 עבורו, \u0003עד שתאמר לו\u0004 במפורש: \u0003\"טהורה אני\".\u0004"],["ובענין הבדיקה שלפני תשמיש, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' זירא מרב יהודה:\u0004 אף שבדרך כלל אין ה\u0003אשה\u0004 צריכה לבדוק את עצמה לפני תשמיש, אם רצתה בכך \u0003מהו שתבדוק עצמה לבעלה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא תבדוק.\u0004 אמר לו ר' זירא: \u0003ותבדוק, ומה בכך?\u0004 אמר לו: \u0003אם כן\u0004 כשבודקת עצמה, גורם הדבר ש\u0003לבו\u0004 של בעלה \u0003נוקפו\u0004 (מכה אותו), שמא אין אשתו טהורה, ולכן בודקת את עצמה, \u0003ו\u0004לכן עלול הוא שיהיה \u0003פורש\u0004 ממנה.","ועוד בענין בדיקה, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אבא מרב הונא: אשה מהו\u0004 הדין לענין \u0003שתבדוק עצמה כשיעור וסת,\u0004 כלומר, מיד אחר הבעילה, \u0003כדי ל\u0004ברר בבדיקה זו (אם תראה בה דם) אם \u0003חייב בעלה\u0004 קרבן \u0003חטאת\u0004 על שעבר בשוגג על איסור בעילת נדה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא בתשובה: \u0003מי\u0004 \u0005[האם]\u0006 בכלל \u0003משכחת לה\u0004 \u0005[מוצא אתה]\u0006 \u0003לבדיקה\u0004 ראויה שתהיה ממש \u0003כשיעור וסת\u0004 סמוך לתשמיש? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003איזהו\u0004 (מהי מידת) \u0003שיעור וסת?\u0004 — \u0003משל לשמש\u0004 (איבר התשמיש) \u0003ועד\u0004 (פיסת הבד המשמשת לבדיקה) \u0003שעומדים\u0004 שניהם \u0003בצד המשקוף\u0004 של הדלת, כלומר, במקום היציאה, ומיד \u0003ביציאות השמש\u0004 החוצה, \u0003נכנס\u0004 במקומו ה\u0003עד\u0004 ומקנח אחריו את מקומו שבצד המשקוף, כלומר, שבחלק החיצוני. ואם מצאה באותו קינוח דם — חייבים שניהם חטאת.","\u0003הוי\u0004 (הרי): מושג זה \"שיעור \u0003וסת\" שאמרו\u0004 חכמים, הריהו \u0003ל\u0004ענין \u0003קנוח\u0004 חיצוני, שאם נמצא דם על הבד שמקנחת בו מבחוץ, הרי זו הוכחה שהיתה נדה בזמן הביאה, \u0003ולא ל\u0004ענין \u0003בדיקה\u0004 פנימית, שכן עד שתכניס פנימה את העד לבדיקה זו, כבר עבר שיעור זה. ואף אם תראה דם, אין הדבר מוכיח שהיתה טמאה כבר בשעת הבעילה, ולא יתחייבו בחטאת אלא בקרבן אשם תלוי מחמת הספק! \u0003אלא\u0004 יש לומר כי כך היתה השאלה: \u0003מהו שתקנח\u0004 עצמה מיד לאחר הבעילה כשיעור וסת?","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003הכי בעא מיניה\u0004 \u0005[כך שאל אותו]\u0006 ר' אבא את רב הונא: \u0003אשה מהו שתבדוק עצמה, כדי לחייב\u0004 את בעלה לפחות \u0003אשם תלוי? אמר לו\u0004 רב הונא: \u0003לא תבדוק.\u0004 שאל אותו ר' אבא: \u0003ותבדוק, ומה בכך\u0004 אם תבדוק? אמר לו רב הונא: \u0003אם כן,\u0004 כשמתחילה לבדוק \u0003לבו נוקפו ופורש\u0004 ממנה.","\u0003ו\u0004עוד שנינו במשנתנו שכל אשה צריכה לבדוק \u0003בשעה שהיא עוברת\u0004 לשמש עם בעלה. ובענין זה \u0003אמר ר'\u0004 \u0003אמי אמר ר'\u0004 \u0003ינאי: וזהו עדן של\u0004 הנשים ה\u0003צנועות\u0004 שנוהגות כן. שאין בדיקה זו מן הדין, אלא ממידת חסידות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא בר ממל לר' אמי\u0004 בשאלה: ה\u0003תנא\u0004 במשנתנו \u0003תני\u0004 \u0005[שנה]\u0006 בענין בדיקות אלה לשון \u0003\"צריכות\",\u0004 לומר שחייבות הן בכך מעיקר הדין, \u0003ואת תני\u0004 \u0005[ואתה שונה]\u0006 לגביהן לשון \u0003\"צנועות\",\u0004 שמשמעה שרק מעצמן ומתוך מידה יתירה של צניעות נוהגות כן! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: אחזתי לשון זו, משום \u0003שאני אומר\u0004 כלל: \u0003כל המקיים דברי חכמים נקרא \"צנוע\".\u0004","\u0003אמר רבא\u0004 בדחיית כלל זה: \u0003ו\u0004הרי אם תקרא למקיים דברי חכמים \"צנוע\", משום כך תסיק שמי \u0003שאינו מקיים דברי חכמים\u0004 — \"צנוע\" הוא דלא מקרי \u0005[שאינו נקרא],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"רשע\" לא מקרי\u0004 \u0005[אינו נקרא],\u0006 והרי העובר על דברי חכמים ודאי שראוי להיקרא \"רשע\"! \u0003אלא אמר רבא:\u0004 הנשים ה\u0003צנועות\u0004 נוהגות שב\u0003עד שבדקו בו עצמן לפני תשמיש זה,\u0004 אף שנמצא נקי — \u0003אין\u0004 חוזרות ו\u0003בודקות בו\u0004 שוב \u0003לפני תשמיש אחר,\u0004 לפי ששוב אינו לבן כמקודם, ואינו יפה לבדיקה. \u0003ו\u0004אילו הנשים \u0003שאינן צנועות\u0004 — חוזרות ו\u0003בודקות\u0004 שוב באותו עד שבדקו בו פעם קודמת, \u0003ולא איכפת להן,\u0004 שאין חוששות שמא התלכלך.","ודנים עוד \u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו, \u0003אמר ר'\u0004 \u0003זירא, אמר ר'\u0004 \u0003אבא בר ירמיה, אמר שמואל: אשה שאין לה וסת\u0004 — \u0003אסורה לשמש\u0004 עם בעלה, \u0003עד שתבדוק\u0004 עצמה. ונמסר שכך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אבא בר ירמיה:\u0004 מדברי שמואל אפשר לדייק כי אשה ש\u0003אין לה וסת\u0004 — היא ש\u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה,\u0004 ואילו אשה ש\u0003יש לה וסת\u0004 — \u0003לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003בדיקה,\u0004 והרי במשנתנו נאמר שגם אשה שיש לה וסת חייבת לבדוק כשעוברת לשמש עם בעלה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא בר ירמיה לר' זירא: מן הנאמר במשנתנו שאשה ש\u0003יש לה וסת\u0004 צריכה בדיקה לשמש עם בעלה, היה אפשר להבין שדווקא כשהיא \u0003ערה, בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה,\u0004 ואם היא \u0003ישנה\u0004 — \u0003לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003בדיקה.\u0004 ואילו שמואל לימדנו שאשה ש\u0003אין לה וסת, בין ערה בין ישנה\u0004 — \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה.\u0004","\u0003אמר רבא\u0004 בשאלה: \u0003ו\u0004יכול היה ר' אבא בר ירמיה \u0003לימא ליה\u0004 \u0005[לומר לו\u0006 לר' זירא\u0005]\u0006 תשובה אחרת: מה שאמר שמואל שאשה ש\u0003יש לה וסת\u0004 צריכה בדיקה כשעוברת לשמש עם בעלה, הרי זה דווקא \u0003ל\u0004ענין אשה העוסקת ב\u0003טהרות\u0004 — שהיא \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה\u0004 לפני תשמיש. אבל אשה שאינה עוסקת בטהרות, ל\u0003בעלה\u0004 בלבד — \u0003לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003בדיקה.\u0004 ואילו אשה ש\u0003אין לה וסת\u0004 — \u0003אפילו לבעלה\u0004 בלבד, אף שאינה עוסקת בטהרות — \u0003נמי בעיא\u0004 \u0005[גם כן צריכה]\u0006 \u0003בדיקה.\u0004 \u0003ומ\u0004תוך ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה בר אבא לר' זירא \u0003הכי\u0004 \u0005[כך]:\u0006 \u0003שמע מינה קסבר\u0004 \u0005[למד מכאן\u0006 כי \u0005סבור הוא]\u0006 \u0003שמואל: כל\u0004 שהוא \u0003ל\u0004ענין תשמיש אשה עם \u0003בעלה\u0004 בלבד — \u0003לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003בדיקה\u0004 כלל.","ודנים עוד בדברי שמואל, ממה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ה\u0003חמרין\u0004 (נוהגי חמורים) \u0003ו\u0004ה\u0003פועלין\u0004 הבאים לביתם לאחר עבודתם, \u0003ו\u0004כן האנשים \u0003הבאין\u0004 לביתם \u0003מבית האבל ומבית המשתה\u0004 (חתונה) בשעה מאוחרת בלילה — \u0003נשיהם להם בחזקת טהרה\u0004 הן, \u0003ובאין ושוהין\u0004 (ומשמשים) \u0003עמהם, בין\u0004 שהיו הנשים \u0003ישנות בין\u0004 היו ערות. במה דברים אלו \u0003אמורים?\u0004 — \u0003שהניחן\u0004 (שכשעזב הבעל את ביתו) היתה אשתו \u0003בחזקת טהרה, אבל\u0004 אם \u0003הניחן בחזקת טומאה\u0004 — \u0003לעולם היא\u0004 עומדת בחזקת \u0003טמאה, עד שתאמר לו \"טהורה אני\".\u0004","\u0003ו\u0004מעתה יש לשאול: \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו],\u0006 \u0003שמואל במאי מוקי לה\u0004 \u0005[במה\u0006 הוא \u0005מעמיד אותה,\u0006 באיזה מקרה הוא אומר שמדובר בה\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 המדובר \u0003ב\u0004אשה \u0003שיש לה וסת\u0004 — \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין אשה \u0003ערה\u0004 שנאמר בברייתא שהיא פטורה מבדיקה! \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003ב\u0004אשה \u0003שאין לה וסת\u0004 — \u0003קשיא\u0004 \u0005[קשה]\u0006 על שמואל שלדעתו, כאמור, \u0003בין\u0004 אשה \u0003ערה\u0004 ו\u0003בין\u0004 אשה \u0003ישנה\u0004 אינה צריכה בדיקה!","ומשיבים: \u0003לעולם\u0004 מדובר בברייתא זו \u0003ב\u0004אשה \u0003שיש לה וסת, ו\u0004בהסבר הדין האמור בברייתא שאין היא צריכה בדיקה, אכן יש לומר שאינה צריכה בדיקה כרגיל, אלא ש\u0003כיון שתבעה\u0004 בעלה לתשמיש, ונענתה לו — \u0003אין לך בדיקה גדולה מזו,\u0004 שהרי אילו לא ידעה בוודאות שהיא טהורה, לא היתה נענית לו בלא שתבדוק עצמה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: מהו למעבד כי הא מתניתא\u0004 \u0005[לעשות,\u0006 לנהוג, \u0005כמו ברייתא זו]?\u0006 האם די כשתובעה לתשמיש בלבד?"],["","","","","","","","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב פפא: \u0003סודני\u0004 (עושה שיכר), \u0003לא\u0004 תבדוק, משום \u0003דמגניא באפיה\u0004 \u0005[ש\u0006היא \u0005מתגנה בפניו]\u0006 כשהיא בודקת. \u0003אמר רב כהנא:\u0004 כך \u0003שאלתינהו לאינשי ביתיה\u0004 \u0005[שאלתי את אנשי ביתם,\u0006 את נשותיהם] של \u0003רב פפא ו\u0004של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: כי אתו רבנן מבי רב, מצרכי לכו\u0004 \u0005[כאשר באים החכמים,\u0006 בעליכם, \u0005מבית הרב,\u0006 האם \u0005מצריכים אתכן]\u0006 לעשות \u0003בדיקה? ואמרו לי: לא.\u0004 ושואלים: \u0003ולישיילינהו לדידהו\u0004 \u0005[ושישאל את\u0006 החכמים \u0005עצמם]\u0006 מה ההלכה בענין זה, ולמה לו לשאול את נשותיהם?! ומשיבים: אילו היה שואל את החכמים עצמם לא יכול היה להסיק מתשובתם הלכה למעשה, שכן אם היו מורים שאין צורך בבדיקה, אפשר שאין זו אלא הוראה לרבים, ואולם \u0003דילמא אינהו קא מחמירי אנפשייהו\u0004 \u0005[שמא הם היו מחמירים על עצמם],\u0006 ואולם משנשאלו נשותיהם כיצד החכמים נהגו, נלמד שאף על עצמם לא החמירו בכך. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אשה שאין לה וסת\u0004 קבוע — \u0003אסורה לשמש\u0004 כלל עם בעלה, שיש חשש תמיד שמא תראה דם בשעת ביאה, ולפיכך צריך בעלה לגרש אותה, \u0003ואין לה\u0004 (אינה זכאית לקבל בגירושיה) מבעלה \u0003לא\u0004 תשלום \u0003כתובה, ולא\u0004 תשלום עבור ה\u0003פירות\u0004 של נכסי מלוג שלה שהשתמש בהם, \u0003ולא מזונות, ולא בלאות\u0004 של הבגדים והחפצים שהביאה עימה בשעת הנישואין, \u0003ויוציא\u0004 (יגרש בגט) אותה \u0003ולא מחזיר\u0004 אותה לאשה \u0003עולמית\u0004 (לעולם), אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004 \u0003ר'\u0004 \u0003חנינא בן אנטיגנוס אומר:\u0004 יכולה היא לשמש עם בעלה, ואולם \u0003משמשת\u0004 היא \u0003בשני עדים\u0004 לבדיקה, לפני ואחרי התשמיש, שכן \u0003הן,\u0004 העדים, \u0003עותוה\u0004 (פגעו בה) אם מוצאת היא עליהם דם ונטמאת, ו\u0003הן\u0004 גם אלו ש\u0003תקנוה\u0004 (עזרו לה) שאם בדקה לפני התשמיש, ולא ראתה עליהם דם, יכולה היא להסתמך עליהם, ולשמש. \u0003משום\u0004 (בשם) \u0003אבא חנן אמרו: אוי לו לבעלה.\u0004","","ומסבירים את דברי הברייתא: מה ששנינו בשיטת ר' מאיר שאשה שאין לה וסת הריהי \u0003אסורה לשמש\u0004 מיטתה עם בעלה, הטעם הוא \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003מקלקלת\u0004 (תגרום לקלקול) \u0003ליה\u0004 \u0005[לו]\u0006 אם תראה דם בשעת התשמיש. \u0003ו\u0004מה שאמר ש\u0003אין לה כתובה\u0004 — הסבר הדבר: \u0003כיון דלא חזיא\u0004 \u0005[שאינה ראויה]\u0006 \u0003לביאה\u0004 לשיטתו, \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה כתובה.\u0004 \u0003ו\u0004מה שאמר \u0003לא פירות, ולא מזונות, ולא בלאות\u0004 אשה המתגרשת מבעלה — הוא משום שכל אלו הריהם \u0003תנאי כתובה,\u0004 ותנאי הכתובה — \u0003ככתובה דמו\u0004 \u0005[נחשבים],\u0006 וכשם שאין לה כתובה, אין לה אף את כל אלו. \u0003ו\u0004על מה שאמר ר' מאיר בדינה של אשה שאין לה וסת ש\u0003יוציא\u0004 אותה בעלה בגט, \u0003ולא יחזיר עולמית.\u0004 שואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא שלא יחזיר, שהרי עומד ומחוייב הוא לגרשה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא למקרה \u0003דהדרה ואתקנה\u0004 \u0005[שחזרה ונתקנה]\u0006 ויש לה עכשיו וסת. \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שעכשיו רשאי הוא \u0003ליהדרה\u0004 \u0005[שיחזירנה],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאינו יכול להחזירה, משום \u0003דזימנין דאזלא ומנסבא, ומתקנא\u0004 \u0005[שפעמים ש\u0006היא \u0005הולכת ונישאת\u0006 לאדם אחר, \u0005ואז\u0006 היא \u0005מיתקנת]\u0006 ויש לה וסת, \u0003ואמר\u0004 \u0005[ו\u0006עשוי בעלה הראשון \u0005לומר]\u0006 לבית הדין: \u0003\"אילו הייתי יודע שכך היה\u0004 (יהיה), שתהיה לה וסת, \u0003אפילו הייתם נותנין לי מאה מנה\u0004 על מנת לגרשה — \u0003לא הייתי מגרשה!\".\u0004 \u0003ו\u0004לפי זה \u0003נמצא גט\u0004 שנתן לה, הריהו גט שבטעות, ו\u0003בטל\u0004 למפרע, והרי היא איפוא עדיין אשתו, \u0003ובניה\u0004 שנולדו לה מהאדם שנשאה הריהם \u0003ממזרין.\u0004 ולפיכך קבע ר' מאיר שכשהוא מוציא אותה, אינו מחזיר אותה עולמית. עוד שנינו בברייתא זו כי \u0003משום\u0004 (בשם) \u0003אבא חנן אמרו: אוי לו לבעלה.\u0004 ובכוונת דברים אלו נחלקו חכמים, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003לר' מאיר\u0004 הסבור שאין הבעל משלם לה את כתובתה \u0003אמר ליה\u0004 \u0005[לו]\u0006 אבא חנן את דבריו אלו, שאבא סבור \u0003דבעי לאגבויה\u0004 \u0005[שצריך להגבותה,\u0006 לפרוע לה\u0005]\u0006 את \u0003כתובתה,\u0004 ולכן אמר \"אוי לו לבעלה\", שעליו להוציא מממונו ולשלם לה את כתובתה. ו\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003לר' חנינא בן אנטיגנוס\u0004 הסבור שיכולה היא לשמש עם בעלה (בעדים) \u0003קאמר ליה\u0004 \u0005[אמר הוא לו]\u0006 את דבריו, שלדעתו אינה יכולה לשמש עם בעלה שמא תוך כדי תשמיש תראה דם ו\u0003מקלקלת ליה\u0004 \u0005[לו],\u0006 ולכן אמר \"אוי לו לבעלה\", שאסור לו לשמש עימה. ולענין הכרעה במחלוקת תנאים זו, \u0003אמר רב יהודה, אמר שמואל: הלכה כר'\u0004 \u0003חנינא בן אנטיגנוס,\u0004 שמותר לאשה שאין לה וסת לשמש עם בעלה (בעדים). ושואלים: \u0003ובמאי\u0004 \u0005[ובמה,\u0006 באיזה מקרה\u0005]\u0006 מדובר? \u0003אי\u0004 \u0005[אם]\u0006 המדובר \u0003ב\u0004אשה ה\u0003עסוקה בטהרות, הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרה שמואל חדא זימנא\u0004 \u0005[פעם אחת]\u0006 שאשה שאין לה וסת צריכה בדיקה כדי לשמש עם בעלה. \u0003ואי\u0004 \u0005[ואם]\u0006 המדובר \u0003ב\u0004אשה \u0003שאינה עסוקה בטהרות, הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 שמואל ש\u0003כל\u0004 אשה שאינה עסוקה בטהרות, \u0003לבעלה לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003בדיקה\u0004 כלל. שכן \u0003אמר ר'\u0004 \u0003זירא, אמר ר'\u0004 \u0003אבא בר ירמיה, אמר שמואל: אשה שאין לה וסת\u0004 — \u0003אסורה לשמש, עד שתבדוק, ואוקימנא לה\u0004 \u0005[והעמדנו,\u0006 הסברנו \u0005אותה]\u0006 שמדובר דווקא \u0003ב\u0004אשה ה\u0003עסוקה בטהרות,\u0004 אבל אשה שאינה עסוקה בטהרות — אינה צריכה בדיקה כדי לשמש עם בעלה. והרי איפוא סתירה בין שתי אמירות ששנו חכמים בשמו של שמואל! ומשיבים: מחלוקת היא בין החכמים בשמועתו של שמואל, ו\u0003מאן דמתני הא, לא מתני הא\u0004",""],["\u0003כל היד המרבה לבדוק\u0004 אם ראתה דם (בנשים) או קרי (באנשים), אם הוא \u0003בנשים\u0004 — הרי יד זו \u0003משובחת\u0004 היא. \u0003ו\u0004אם הוא \u0003באנשים\u0004 הבודקים עצמם — \u0003תקצץ\u0004 יד זו, משום שעלול הדבר להביא לידי הוצאת זרע לבטלה.","שנינו במשנה כי יש הבדל בין בדיקת נשים לבדיקת אנשים, שבנשים משובח הדבר ובאנשים מגונה הוא. ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונות]\u0006 ה\u0003נשים ומאי שנא\u0004 \u0005[ובמה שונים]\u0006 ה\u0003אנשים\u0004 לענין זה? ומשיבים: ה\u0003נשים לאו\u0004 \u0005[לא]\u0006 \u0003בנות הרגשה נינהו\u0004 \u0005[הן],\u0006 שאין בדיקה שכזו גורמת להן להרגשה, ולכן כשהן מרבות בבדיקה הרי הן \u0003משובחות,\u0004 ואילו ה\u0003אנשים\u0004 ש\u0003בני הרגשה נינהו\u0004 \u0005[הם],\u0006 שמתוך שבודקים עצמם באים לידי הוצאת זרע לבטלה, משום כך יד הבודקת בהם \u0003תקצץ.\u0004","ושואלים: \u0003אי הכי מאי איריא\u0004 \u0005[אם כך מה שייך,\u0006 מדוע דווקא] שנינו במשנה כי היד ה\u0003מרבה\u0004 לבדוק באנשים תקצץ, והרי אף \u0003כי\u0004 \u0005[כאשר]\u0006 היד באנשים \u0003לא מרבה\u0004 לבדוק \u0003נמי\u0004 \u0005[גם כן]\u0006 מגונה הדבר, מחשש הוצאת זרע לבטלה! ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 במשנה \"כל היד ה\u0003מרבה\u0004 לבדוק\" שנה זאת רק ביחס ל\u0003נשים,\u0004 ולא ביחס לגברים, שבדיקת גברים מגונה אפילו אם אינם מרבים לבדוק.","ועוד בענין זה של בדיקת אנשים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003במה דברים אמורים\u0004 שאין ראוי לאנשים לבדוק עצמם? \u0003לענין\u0004 בדיקה אם יצאה ממנו \u0003שכבת זרע, אבל לענין\u0004 בדיקה ל\u0003זוב\u0004 אחר שיצאה ממנו זיבה ורוצה לבדוק כדי לדעת מספר ראיותיו (שהרואה שנים — טמא ואינו מביא קרבן, והרואה שלוש אף צריך להביא קרבן) — \u0003אף הוא\u0004 האיש הבודק \u0003משובח כנשים\u0004 הבודקות.","\u0003ואפילו לענין שכבת זרע\u0004 שאין לאיש לבדוק עצמו, \u0003אם בא לבדוק בצרור\u0004 (אבן) \u0003או בחרס\u0004 שקשים הם, ואין מביאים אותו לכלל חימום — \u0003בודק.\u0004","ושואלים על כך: \u0003ובמטלית\u0004 בד, שהיא רכה — \u0003לא\u0004 יבדוק? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 האיש \u0003בודק עצמו במטלית,\u0004 לראות אם יצאה ממנו שכבת זרע \u0003ובכל דבר שרוצה!\u0004 ומשיבים: \u0003כ\u0004מו ש\u0003אמר אביי\u0004 לענין אחר, שאמר שמדובר \u0003במטלית עבה, הכא נמי\u0004 \u0005[כאן\u0006 בברייתא זו \u0005גם כן]\u0006 צריך לומר שמדובר דווקא \u0003במטלית עבה,\u0004 שהיא קשה ואינה מביאתו לכלל חימום.","\u0003והיכא איתמר\u0004 \u0005[והיכן נאמר]\u0006 בעיקרו דבר זה של \u0003אביי?\u0004 \u0003אהא דתנן\u0004 \u0005[על זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003היה\u0004 הכהן \u0003אוכל בתרומה, ו\u0004בתוך שהתרומה בפיו \u0003הרגיש שנזדעזעו איבריו,\u0004 שנעקר זרע מגופו, מה יעשה? — \u0003אוחז באמתו\u0004 (אברו) שלא יצא הזרע לחוץ, \u0003ובולע את התרומה\u0004 לפני שיצא הזרע החוצה, וייטמא בכך, וייאסר באכילת תרומה.","ותוהים על כך: \u0003אוחז? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: כל האוחז באמתו ומשתין\u0004 — \u0003כאילו מביא מבול לעולם! אמר אביי\u0004 בהסבר המשנה: הכוונה שאוחז \u0003ב\u0004אמצעות \u0003מטלית עבה.\u0004","\u0003רבא אמר\u0004 בהסבר משנה זו: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר בה באחיזה \u0003ב\u0004אמצעות \u0003מטלית רכה,\u0004 הותר הדבר, \u0003כיון דעקר עקר\u0004 \u0005[ש\u0006כבר \u0005נעקר\u0006 מתוכו הזרע, \u0005נעקר],\u0006 ואין האחיזה באמה, אף במטלית רכה, מוסיפה דבר. \u0003ו\u0004אילו \u0003אביי\u0004 האוסר לאחוז במטלית רכה, טעמו משום ש\u0003חייש\u0004 \u0005[חושש]\u0006 הוא \u0003דלמא\u0004 \u0005[שמא]\u0006 מתוך האחיזה במטלית רכה \u0003אתי לאוסופי\u0004 \u0005[יבוא להוסיף]\u0006 בפליטת זרע. \u0003ו\u0004אילו \u0003רבא לא חייש דלמא אתי לאוסופי\u0004 \u0005[אינו חושש שמא יבוא\u0006 בכך \u0005להוסיף].\u0006","ושואלים: \u0003ו\u0004האם רבא \u0003לא\u0004 חושש לכך? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למה זה\u0004 האיש הבודק עצמו שוב ושוב \u0003דומה?\u0004 — \u0003ל\u0004אדם ה\u0003נותן אצבע ב\u0004תוך ה\u0003עין, שכל זמן ש\u0004ה\u0003אצבע\u0004 נתונה \u0003בעין\u0004 — הרי ה\u0003עין מדמעת וחוזרת ומדמעת,\u0004 ואף זה גורם להוצאה נוספת של זרע!","\u0003ו\u0004אילו \u0003רבא\u0004 סבור שאין אומרים כך אלא כאשר יוצא זרעו בלא שנזדעזעו איבריו שבכגון זה יוצא הזרע מעט מעט ובבדיקה נוספת יש חשש שיוסיף ויצא, אבל כאשר כבר הרגיש שנזדעזעו איבריו ויצא ממנו זרע אין לחשוש לכך, כיון ש\u0003כל אחמומי והדר אחמומי\u0004 \u0005[חימום\u0006 המביא להוצאת זרע, \u0005ושוב חימום\u0006 שכזה\u0005]\u0006 \u0003בשעתיה\u0004 \u0005[בשעתו,\u0006 כשנעקר כבר מגופו זרע\u0005]\u0006 הרי זה \u0003לא שכיח\u0004 \u0005[אינו מצוי],\u0006 ואין לחשוש לכך, ולכן מותר לו במקרה זה לאחוז באמה אף במטלית רכה.","ודנים מעתה בענין זה שהזכרנו למעלה \u0003גופא\u0004 \u0005[לגופו],\u0006 \u0003ר' אליעזר אומר: כל האוחז באמה ומשתין\u0004 — \u0003כאילו מביא מבול לעולם.\u0004 \u0003אמרו לו\u0004 חכמים \u0003לר' אליעזר: והלא\u0004 אם אינו אוחז באמתו כשמשתין הרי \u0003נצוצות\u0004 (טיפות קטנות) \u0003נתזין על רגליו, ונראה\u0004 הוא מעתה \u0003ככרות שפכה\u0004 (סריס) שאינו יכול להטיל מימיו למרחוק, ואינו מוליד, \u0003ונמצא\u0004 שבכך הוא \u0003מוציא לעז על בניו ש\u0004אין הם בניו אלא \u0003הן ממזרים!\u0004","\u0003אמר להן\u0004 ר' אליעזר: \u0003מוטב\u0004 (עדיף) \u0003שיוציא לעז על בניו שהן ממזרים, ואל יעשה עצמו רשע שעה אחת לפני המקום\u0004 (הקדוש ברוך הוא).","ועוד בענין זה \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 כך \u0003אמר להן ר'\u0004 \u0003אליעזר לחכמים\u0004 בתשובה: \u0003אפשר\u0004 שלא ינתזו ניצוצות על רגליו, וכיצד? \u0003יעמוד אדם במקום גבוה וישתין\u0004 כלפי מטה, \u0003או\u0004 שיעשה באופן אחר: \u0003ישתין ב\u0004מקום שיש בו \u0003עפר תיחוח\u0004 (מפורר), שנבלעים בו מימי הרגלים, ואינם ניתזים כלפי מעלה. וראוי לאדם לנהוג כן, ובלבד שלא יאחז באמתו וישתין, \u0003ואל יעשה עצמו רשע שעה אחת לפני המקום.\u0004","ודנים בשתי תשובות אלה של ר' אליעזר לחכמים: \u0003הי\u0004 \u0005[איזו]\u0006 מהן \u0003אמר להו ברישא\u0004 \u0005[להם בתחילה]?\u0006 \u0003אילימא קמייתא\u0004 \u0005[אם תאמר\u0006 שאת \u0005הראשונה],\u0006 שאין לאחוז באמה אף שמוציא בכך לעז על בניו \u0003אמר להו ברישא\u0004 \u0005[להם בתחילה],\u0006 ואחר כן אמר להם את תשובתו השניה, שיש פתרון לכך שלא יינתזו ניצוצות על רגליו, ואולם דבר זה קשה, שהרי \u0003בתר\u0004 \u0005[אחרי]\u0006 ש\u0003אמר להו איסורא\u0004 \u0005[להם איסור],\u0006 \u0003הדר\u0004 \u0005[חזר]\u0006 \u0003אמר להו תקנתא\u0004 \u0005[להם תקנה,\u0006 פתרון מעשי לדבר\u0005]?\u0006 שהרי משמע שאם אין לו אפשרות בפתרון זה, יאחוז באמתו מכל מקום, והוא סתירה לדבריו הראשונים!","\u0003אלא\u0004 יש לומר כי \u0003הא\u0004 \u0005[\u0006את \u0005זה]\u0006 הפתרון המעשי \u0003אמר להו ברישא\u0004 \u0005[להם בתחילה],\u0006 שיש תקנה לדבר, \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 אם \u0003אין לו מקום גבוה ועפר תיחוח, מאי\u0004 \u0005[מה]\u0006 יעשה? ועל כך \u0003אמר להן:\u0004 אל יאחוז, שכן \u0003מוטב שיוציא לעז על בניו, ואל יעשה עצמו רשע שעה אחת לפני המקום.\u0004","\u0003וכל כך למה? מפני ש\u0004בכך שאוחז באמתו הריהו גורם לעצמו שיהיה \u0003מוציא שכבת זרע לבטלה.\u0004 שכך \u0003אמר ר'\u0004 \u0003יוחנן\u0004 בחומרת עבירה זו: \u0003כל המוציא שכבת זרע לבטלה\u0004 — \u0003חייב מיתה, ש\u0004כן \u0003נאמר\u0004 באונן בן יהודה: \"והיה אם בא אל אשת אחיו ושחת ארצה לבלתי נתן זרע לאחיו. \u0003וירע בעיני ה'\u0004 \u0003אשר עשה וימת גם אתו\"\u0004 (בראשית לח, ט—י).","\u0003ר' יצחק ור' אמי אמרי\u0004 \u0005[אומרים]:\u0006 כל המוציא שכבת זרע לבטלה — \u0003כאילו שופך דמים, ש\u0004כן \u0003נאמר:\u0004 \"...זרע מנאף ותזנה... הלא אתם ילדי פשע זרע שקר. \u0003הנחמים באלים תחת כל עץ רענן שחטי הילדים בנחלים תחת סעפי הסלעים\"\u0004 (ישעיה נז, ג—ה), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003שוחטי אלא סוחטי,\u0004 שנחשבת הוצאת (\"סוחטי\") שכבת זרע לבטלה כהמתה של הילדים שיכלו להיוולד מזרע זה.","\u0003רב אסי אמר:\u0004 כל המוציא שכבת זרע לבטלה — \u0003כאילו עובד עבודה זרה.\u0004 \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"תחת כל עץ רענן\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 במצוות איבוד עבודה זרה בארץ ישראל: \"אבד תאבדון את כל המקומות אשר עבדו שם הגוים אשר אתם יורשים אותם את אלהיהם \u0003על ההרים הרמים\u0004 ועל הגבעות \u0003ותחת כל עץ רענן\"\u0004 (דברים יב, ב).","ובענין זה של אחיזה באמה לצורך הטלת מים מסופר כי \u0003רב יהודה ושמואל\u0004 רבו \u0003הוו קיימי אאיגרא דבי כנישתא דשף ויתיב\u0004 \u0005[היו עומדים על גג בית הכנסת שנפל והתיישב]\u0006 \u0003בנהרדעא,\u0004 שהיה בית כנסת ידוע שכך היה כינויו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לשמואל:\u0004 מה אעשה, ו\u0003צריך אני להשתין? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שיננא\u0004 \u0005[גדול השיניים],\u0006 \u0003אחוז באמתך\u0004 כדי שלא יפלו המים על גג בית הכנסת \u0003והשתן לחוץ,\u0004 אל מחוץ לבית הכנסת.","ושואלים על כך: \u0003היכי עביד הכי\u0004 \u0005[כיצד עשה כך],\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: כל האוחז באמתו ומשתין\u0004 — \u0003כאילו מביא מבול לעולם!\u0004","\u0003אמר אביי:\u0004 \u0003עשאו\u0004 את הענין הזה \u0003כבולשת\u0004 (חיל בלשים, המחפשים בבתים), ומהו עניינה — \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה במסכת עבודה זרה\u0005]:\u0006 \u0003בולשת\u0004 של חיילים גויים \u0003שנכנס לעיר,\u0004 וחיפשו בבתים, ומתעורר החשש שמא אגב כך ניסכו מן היין שבבתי ישראל לעבודה זרה, ונאסר בכך היין. אם היה זה \u0003בשעת שלום,\u0004 שאין הם ממהרים במלאכתם, \u0003חביות\u0004 של יין שנמצאו \u0003פתוחות\u0004 — הריהן \u0003אסורות,\u0004 שמא ניסכו מהן, והחביות הנמצאות כשהן \u0003סתומות\u0004 (פקוקות וטוחות בטיט) — \u0003מותרות,\u0004 שודאי לא פת חון הגויים. ואולם אם היה זה \u0003בשעת מלחמה\u0004 — \u0003אלו ואלו מותרות, לפי שאין להן פנאי לנסך,\u0004 כיון שהם עסוקים במלחמה. \u0003אלמא\u0004 \u0005[מכאן]\u0006 נלמד ש\u0003כיון דבעיתי\u0004 \u0005[שיראים]\u0006 הם מפני שעת המלחמה, כל דעתם נתונה לכך, ולכן \u0003לא אתי לנסוכי\u0004 \u0005[אין\u0006 הם \u0005באים לנסך],\u0006 אם כן, \u0003הכא נמי\u0004 \u0005[כאן,\u0006 במעשה זה שברב יהודה ושמואל, \u0005גם כן]\u0006 אומרים אנו כי \u0003כיון דבעיתי\u0004 \u0005[שיראים],\u0006 לכך \u0003לא אתי להרהורי\u0004 \u0005[אין באים להרהר]\u0006 הרהור של עבירה.","ומבררים: \u0003והכא\u0004 \u0005[וכאן]\u0006 במעשה זה של רב יהודה ושמואל \u0003מאי בעיתותא איכא\u0004 \u0005[מה,\u0006 איזו \u0005יראה יש]?\u0006 ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר זה: \u0003ביעתותא דליליא ודאיגרא\u0004 \u0005[יראת של הלילה ושל הגג]\u0006 שהוא עומד עליו וחושש שמא יפול. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: הכוונה ל\u0003ביעתותא דרביה\u0004 \u0005[יראת רבו,\u0006 שמואל, על רב יהודה\u0005].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 עוד הסבר, שהכוונה ל\u0003ביעתותא\u0004 \u0005[יראת]\u0006 ה\u0003שכינה,\u0004 שהרי בית כנסת הוא. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר זה: \u0003אימתא דמריה עליה\u0004 \u0005[אימת אדוניו,\u0006 הקדוש ברוך הוא \u0005עליו],\u0006 שמיוחד היה רב יהודה ביראת ה', \u0003דקרי\u0004 \u0005[ש\u0006כך \u0005קרא]\u0006 \u0003שמואל עליה\u0004 \u0005[עליו,\u0006 על רב יהודה תלמידו\u0005]:\u0006 \u0003אין זה ילוד אשה\u0004 אלא כמלאך.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר מדוע הורה לו שמואל לנהוג כן, כיון שרב יהודה \u0003נשוי הוה\u0004 \u0005[היה],\u0006 שכך \u0003אמר רב נחמן: אם היה נשוי\u0004 — \u0003מותר\u0004 לאחוז באמה ולהטיל מימיו, שכיון שנשוי הוא ומצויה לו אשתו, אין יצרו תוקפו בכך.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר זה: \u0003כי הא אורי ליה\u0004 \u0005[כמו,\u0006 באופן \u0005זה הורה לו]\u0006 שמואל לרב יהודה, \u0003דתני\u0004 \u0005[ש\u0006כך \u0005שנה]\u0006 ברייתא זו \u0003אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' בנימין בר חייא:\u0004 אין לאחוז באמה עצמה להטיל מים, \u0003אבל מסייע\u0004 האדם המטיל מים לעצמו \u0003ב\u0004אחיזת ה\u0003ביצים\u0004 ש\u0003מלמטה,\u0004 וכך גם הורה שמואל לרב יהודה לנהוג. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 עוד הסבר: \u0003כי הא אורי ליה\u0004 \u0005[כמו,\u0006 באופן \u0005זה הורה לו],\u0006 שכך \u0003אמר ר'\u0004 \u0003אבהו, אמר ר'\u0004 \u0003יוחנן: גבול\u0004 (תחום מוגדר) \u0003יש לו\u0004 לאיסור אחיזה באמה, והוא: \u0003מעטרה\u0004 (השפה המקיפה את הגיד) \u0003ולמטה,\u0004 כלפי קצה האיבר — \u0003מותר\u0004 לאחוז, שאין זה מקום המביא לגירוי,"],["\u0003מעטרה ולמעלה\u0004 לכיוון הגוף — \u0003אסור.\u0004","\u0003אמר רב: המקשה עצמו לדעת\u0004 (בכוונה) מה דינו? — \u0003יהא בנדוי.\u0004 ושואלים: \u0003ולימא\u0004 \u0005[ויאמר]\u0006 רב שדבר זה \u0003אסור,\u0004 ודי בכך! ומשיבים: ראוי הוא לנידוי משום \u0003דקמגרי\u0004 \u0005[שהוא מגרה]\u0006 \u0003יצר הרע אנפשיה\u0004 \u0005[על עצמו].\u0006 \u0003ור' אמי אמר:\u0004 המקשה עצמו במכוון — \u0003נקרא \"עבריין\"\u0004 (הרגיל בכל העבירות), \u0003ש\u0004כן \u0003כך\u0004 היא \u0003אומנתו\u0004 (מקצועו) \u0003של\u0004 ה\u0003יצר הרע: היום אומר לו\u0004 לאדם: \u0003עשה כך\u0004 דבר עבירה מסויים, \u0003ו\u0004כיון שנענה לו האדם, \u0003למחר\u0004 היצר הרע שב ו\u0003אומר לו: עשה כך\u0004 דבר עבירה אחר. \u0003ולמחר אומר לו: לך עבוד עבודה זרה\u0004 — \u0003והולך ועובד.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך \u0003אמר ר'\u0004 \u0003אמי: כל המביא עצמו לידי הרהור\u0004 — \u0003אין מכניסין אותו במחיצתו של הקדוש ברוך הוא.\u0004 וראיה לדבר, שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 באונן בן יהודה: \"...ושחת ארצה... \u0003וירע בעיני ה'\u0004 אשר עשה\" (בראשית לח, ט—י), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"כי לא אל חפץ רשע אתה לא יגרך רע.\u0004 לא יתיצבו הוללים לנגד עיניך... ואני ברוב חסדך אבוא ביתך אשתחוה אל היכל קדשך ביראתך\" (תהלים ה, ד—ח). ומכאן שכל העושה רע (\"וירע\") כדוגמת אונן, אינו נכנס במחיצת הקדוש ברוך הוא (\"לא יגורך רע\").","\u0003ואמר ר'\u0004 \u0003אלעזר\u0004 בחומרת ענין זה: \u0003מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הכתוב]\u0006 \"ובפר ישכם כפיכם אעלים עיני גם כי תרבו תפילה אינני שומע \u0003ידיכם דמים מלאו\"\u0004 (ישעיה א, טו), שאין תפילתם של אלו נשמעת לפני הקדוש ברוך הוא — \u0003אלו המנאפים ביד\u0004 שמוציאים זרע לבטלה. וכן \u0003תנא\u0004 \u0005[שנה]\u0006 החכם \u0003דבי\u0004 \u0005[של בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 משמעות האמור בעשרת הדברות \u0003\"לא תנאף\"\u0004 (שמות כ, יג) היא — \u0003לא תהא בך\u0004 (בינך לבין עצמך) \u0003ניאוף, בין ביד בין ברגל.\u0004","ועוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הגרים, והמשחקין בתינוקות\u0004 — \u0003מעכבין את\u0004 בוא \u0003המשיח.\u0004 ודנים בדבר, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גרים\u0004 — הרי זה \u0003כ\u0004דברי \u0003ר' חלבו,\u0004 שכך \u0003אמר ר'\u0004 \u0003חלבו: קשין גרים לישראל כספחת\u0004 מפני שאינם בקיאים במצוות וישראל למדים מהם. \u0003אלא משחקין בתנוקות מאי היא\u0004 \u0005[מה הוא],\u0006 במה מעכב דבר זה את בוא המשיח?","\u0003אילימא\u0004 \u0005[אם נאמר]\u0006 משום \u0003משכב זכור\u0004 — הלא \u0003בני סקילה נינהו\u0004 \u0005[הם],\u0006 ואין הדבר רק משום שהם מעכבים את בוא המשיח! \u0003אלא\u0004 אם נאמר משום ששופך זרעו \u0003דרך אברים\u0004 אחרים שאינם מקום ערווה — \u0003בני\u0004 דור ה\u0003מבול נינהו\u0004 \u0005[הם]\u0006 וראויים הם לעונש שנענשו בני דור המבול!","\u0003אלא\u0004 כוונת הדברים לאלו \u0003דנסיבי\u0004 \u0005[שנושאים]\u0006 \u0003קטנות דלאו\u0004 \u0005[שלא]\u0006 \u0003בנות אולודי נינהו\u0004 \u0005[הולדה הן]\u0006 עדיין, ונמצא שמשחיתים זרעם שלא לשם הולדה. שכך \u0003אמר ר'\u0004 \u0003יוסי: אין\u0004 משיח \u0003בן דוד בא, עד שיכלו כל הנשמות שבגוף\u0004 (מקום כינוס הנשמות העתידות להיוולד), \u0003שנאמר:\u0004 \"כי לא לעולם אריב ולא לנצח אקצוף \u0003כי רוח מלפני יעטוף ונשמות אני עשיתי\"\u0004 (ישעיה נז, טז). שהנשמות (\"רוח\") שגזרתי עליהם קודם שיוולדו (\"מלפני\"), אחר שנמנע מהם להיוולד — הם אשר יעכבו (\"יעטוף\") את ביאת המשיח.","שנינו במשנה כי היד הבודקת \u0003באנשים תקצץ.\u0004 ובענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני בית המדרש\u0005]\u0006 שאלה זו: האם \u0003דינא תנן\u0004 \u0005[דין שנינו]\u0006 במשנה זו, שכך יש לנהוג למעשה, \u0003או לטותא תנן\u0004 \u0005[קללה\u0006 בלבד \u0005שנינו],\u0006 ואין נוהגים כן למעשה. ומפרטים: האם \u0003דינא תנן\u0004 \u0005[דין שנינו],\u0006 \u0003כי הא\u0004 \u0005[כמו\u0006 בענין \u0005זה]\u0006 של איסור הכאת יהודי שאף בו נאמרה לשון זו (\"כל המרים יד על חבירו — תקצץ ידו\"), ונהג \u0003רב הונא\u0004 כן ו\u0003קץ ידא\u0004 \u0005[קצץ יד]\u0006 של החוטא בדבר, \u0003או\u0004 שרק \u0003לטותא תנן\u0004 \u0005[קללה\u0006 בלבד \u0005שנינו]?\u0006","ומביאים ראיה לדבר, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' טרפון אומר: יד לאמה\u0004 — \u0003תקצץ ידו על טבורו.\u0004 \u0003אמרו לו\u0004 חכמים: אלא מעתה אם \u0003ישב לו\u0004 לאדם \u0003קוץ בכריסו, לא יטלנו?! אמר להן:\u0004 אכן \u0003לא\u0004 יטלנו, ואם נטלו — תקצץ ידו על טבורו. אמרו לו חכמים: \u0003והלא\u0004 אם תקצץ על טבורו הרי בכך תהא \u0003כריסו נבקעת! אמר להן: מוטב תבקע כריסו\u0004 של העושה כן \u0003ואל ירד לבאר שחת.\u0004","ודנים בדבר: \u0003אי אמרת בשלמא דינא תנן\u0004 \u0005[זה נוח אם אמרת\u0006 ש\u0005דין שנינו],\u0006 \u0003היינו דאמרי\u0004 \u0005[זהו שאמרו]\u0006 לו חכמים לר' טרפון: \u0003\"והלא כריסו נבקעת\u0004 כשקוצצים את ידו\". \u0003אלא אי אמרת לטותא תנן\u0004 \u0005[אם אומר אתה\u0006 ש\u0005קללה שנינו],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כריסו נבקעת\"?\u0004 ודוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר ש\u0003דינא תנן\u0004 \u0005[דין שנינו],\u0006 אם כן וכי \u0003לא סגי דלאו\u0004 \u0005[לא די שאינה]\u0006 נקצצת \u0003על טבורו?\u0004","\u0003אלא הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0005ר' טרפון: כל המכניס ידו\u0006 \u0003למטה מטבורו\u0004 — \u0003תקצץ.\u0004 \u0003אמרו לו\u0004 חכמים \u0003לר' טרפון:\u0004 ואם \u0003ישב לו קוץ בכריסו לא יטלנו? אמר להן: לא.\u0004 אמרו לו: \u0003והלא כריסו נבקעת\u0004 מחמת הקוץ! \u0003אמר להן: מוטב תבקע כריסו ואל ירד לבאר שחת.\u0004","האשה \u0003החרשת והשוטה והסומא ו\u0004זו \u0003שנטרפה דעתה,\u0004 שאינן יכולות לבדוק עצמן לראות אם יצא מהן דם, כיצד נוהגות? \u0003אם יש להם\u0004 נשים בקירבתן שהן \u0003פקחות\u0004 (שפויות בדעתן, הרואות) — נשים אלה \u0003מתקנות\u0004 (בודקות ומטבילות) \u0003אותן, ו\u0004על סמך כך, אם נשות כהנים \u0003הן\u0004 הריהן \u0003אוכלות בתרומה\u0004 לאחר שהעריב שמשן.","שנינו במשנתנו כי ה\u0003חרשת\u0004 — נשים פקחות בודקות אותה. ושואלים: \u0003איהי\u0004 \u0005[היא]\u0006 \u0003תבדוק לנפשה\u0004 \u0005[את עצמה]!\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר רבי:\u0004 אשה \u0003חרשת היתה בשכונתינו,\u0004 והיתה חכמה בבדיקת מראות דמים, ש\u0003לא דיה ש\u0004היתה \u0003בודקת לעצמה, אלא\u0004 אף כ\u0003שחברותיה\u0004 היו \u0003רואות\u0004 אצלן מראה דם, \u0003ו\u0004לא היו יודעות אם דם טמא הוא זה, היו \u0003מראות לה!\u0004","ומתרצים: \u0003התם\u0004 \u0005[שם,\u0006 בשכנתו של רבי\u0005]\u0006 מדובר \u0003ב\u0004חרשת כזו ש\u0003מדברת ואינה שומעת,\u0004 ואשה כזו יכולה שתהא חכמה בראיית דמים. ואילו \u0003הכא\u0004 \u0005[כאן\u0006 במשנתנו\u0005]\u0006 מדובר \u0003ב\u0004אשה \u0003שאינה מדברת ואינה שומעת,\u0004 וזו אין בה דעת לבדוק אף את עצמה. \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה במסכת תרומות\u0005]:\u0006 \u0003חרש שדברו\u0004 בו \u0003חכמים בכל מקום\u0004 (בעניינים שונים בהלכה) שנחשב כאינו בר דעת, הוא זה ש\u0003אינו שומע ו\u0004גם אינו מדבר.","עוד שנינו במשנתנו כי \u0003הסומא\u0004 — פקחות בודקות אותה. ושואלים: \u0003איהי\u0004 \u0005[היא]\u0006 \u0003תבדוק לנפשה\u0004 \u0005[את עצמה],\u0006 שהרי יש בה דעת ויודעת כיצד יש לבדוק, \u0003ו\u0004לאחר מכן \u0003תיחזי\u0004 \u0005[תראה]\u0006 את עד הבדיקה \u0003לחבירתה\u0004 הרואה! \u0003אמר ר'\u0004 \u0003יוסי בר' חנינא:\u0004 גירסה זו שבמשנתנו המונה אף את האשה ה\u0003סומא\u0004 בכלל הנשים שאינן בודקות עצמן, \u0003אינה משנה\u0004 מדוייקת, ואין לגורסה במשנתנו.","\u0003ו\u0004עוד שנינו במשנתנו כי מי \u0003שנטרפה דעתה\u0004 נבדקת על ידי פקחות. ושואלים: מי שנטרפה דעתה \u0003היינו\u0004 \u0005[זוהי]\u0006 \u0003שוטה,\u0004 וכבר נשנתה במשנה! ומשיבים: מדובר כאן בזו \u0003שנטרפה דעתה מחמת חולי\u0004 שאינה בגדר שוטה האמורה במשנה.","ועוד בעניינו של השוטה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כהן שוטה\u0004 שהיה טמא — בני דעת עוסקים בטהרתו, והם \u0003מטבילין אותו, ו\u0004לאחר מכן \u0003מאכילין אותו\u0004 (מתירים לו לאכול) מן ה\u0003תרומה לערב\u0004 (לאחר הערב שמש, כדין כל כהן שנטמא). \u0003ו\u0004אותם המטפלים בו הריהם \u0003משמרין אותו שלא יישן,\u0004 שכן אם יישן, אפשר יבוא מתוך שנתו לראיית קרי המטמאת אותו. ואם \u0003ישן\u0004 — הריהו שוב \u0003טמא,\u0004 ואסור באכילת תרומה, ואם \u0003לא ישן\u0004 — הריהו \u0003טהור.\u0004","\u0003ר'\u0004 \u0003אליעזר בר' צדוק אומר:\u0004 יש דרך אחרת להתירו באכילת תרומה, \u0003עושין לו כיס\u0004 (נרתיק) \u0003של עור,\u0004 וכורכים אותו סביב איברו, וכשבאים להאכילו תרומה רואים בנרתיק זה אם יצא ממנו זרע ונטמא. \u0003אמרו לו\u0004 חכמים: אין ראוי לעשות כן, משום שבכך \u0003כל שכן שמביא\u0004 אותו הנרתיק \u0003לידי חימום\u0004 וגורם לו להוצאת זרע! \u0003אמר להן\u0004 ר' אליעזר בר' צדוק: \u0003לדבריכם\u0004 (לשיטתכם) יוצא איפוא שכהן \u0003שוטה אין לו תקנה\u0004 (פתרון) כלל לאכול מן התרומה!","\u0003אמרו לו: לדברינו\u0004 יש דרך שיאכל מן התרומה, שאם \u0003ישן\u0004 — הריהו \u0003טמא,\u0004 ואם \u0003לא ישן\u0004 — הריהו \u0003טהור,\u0004 ואולם \u0003לדבריך\u0004 בעשיית נרתיק הכרוך עליו, אין זה פתרון ראוי, שיש לחשוש בו \u0003שמא יראה טפה\u0004 של זרע קטנה \u0003כ\u0004גודל גרגיר צמח ה\u0003חרדל, ותבלע בכיס\u0004 ולא תיראה, ונמצא אוכל בתרומה בטומאה!","ועוד בתקנתו של כהן שוטה בענין אכילת תרומה \u0003תנא\u0004 \u0005[שנה]\u0006 החכם, \u0003משום\u0004 (בשם) \u0003ר' אלעזר אמרו: עושין לו כיס של מתכת\u0004 ומניחים אותו על איברו, כדי לבדוק בו אם ראה.","ובביאור דברים אלה \u0003אמר אביי: ו\u0004כוונת הדברים \"של מתכת\" היא שנרתיק זה הריהו \u0003של נחשת,\u0004 שאינה בולעת, ואין לחשוש בה שמא ראה טיפה ונבלעה בה. \u0003כדתניא\u0004 \u0005[כמו ששנינו\u0006 במשנה במסכת פרה\u0005],\u0006 לענין שיעור כמות מי החטאת שמזים על הטמא, \u0003ר' יהודה אומר: רואין\u0004 (מחשיבים) \u0003אותן גבעולין של אזוב\u0004 שבהם מזים ממי החטאת \u0003כאילו הן של נחשת\u0004 שאינה בולעת. הרי איפוא שמתכת הנחושת אינה בולעת.","\u0003אמר רב פפא:\u0004 מכלל דברי חכמים שכיס הכרוך על האיבר יכול להביא לחימום ולהוצאת זרע, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי ה\u0003מכנסים אסורים\u0004 בלבישה, משום חשש טומאה בהם, שהרי אף הם כרוכים על איבר האדם. ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בבגדי כהנים: \u0003\"ועשה להם מכנסי בד לכסות בשר ערוה\u0004 ממתנים ועד ירכים יהיו\" (שמות כח, מב)!","ומשיבים: הבגד \u0003ההוא\u0004 (מכנסי הכהנים) עניינו שונה, \u0003כדתניא\u0004 \u0005[כ\u0006ברייתא זו \u0005ששנינו]:\u0006 \u0003מכנסי כהנים למה הן דומין\u0004 — \u0003כמין פמלניא\u0004 (מכנסי רכיבה) \u0003של פרשים,\u0004 וכך הם נראים: \u0003למעלה\u0004 — מגיעים הם \u0003עד מתנים, למטה\u0004 מגיעים הם — \u0003עד ירכים, ויש להם שנצים\u0004 (רצועות רכיסה), \u0003ואין להם לא בית הנקב\u0004 (פתח) \u0003ולא בית הערוה.\u0004","\u0003אמר אביי:\u0004"]]};
